import React from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons, COLORS } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles }) => {
  const activeTasks = tasks.filter(t => t.status !== 'Completed');
  const availableWorkers = workers.filter(w => w.status === 'Available');
  const availableVehicles = vehicles.filter(v => v.status === 'Ready');

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-3 gap-3">
        <StatCard label="Tasks" value={activeTasks.length} color="blue" />
        <StatCard label="Staff" value={availableWorkers.length} color="green" />
        <StatCard label="Fleet" value={availableVehicles.length} color="orange" />
      </div>

      <section>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold">Today's Moves</h2>
          <button className="text-sm text-blue-600 font-semibold">View all</button>
        </div>

        <div className="space-y-3">
          {tasks.length > 0 ? tasks.map(task => (
            <div key={task.id} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
              <div>
                <h3 className="font-bold text-slate-800">{task.title}</h3>
                <p className="text-sm text-slate-500">{task.customer}</p>
                <div className="flex items-center gap-2 mt-3 text-xs font-medium text-slate-400">
                  <div className="flex items-center gap-1">
                    <Icons.Calendar />
                    {task.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </div>
                  <span>•</span>
                  <span>{task.from} &rarr; {task.to}</span>
                </div>
              </div>
              <span className={`text-[10px] uppercase font-bold px-2 py-1 rounded-full ${
                task.status === 'Confirmed' ? 'bg-green-50 text-green-600' : 'bg-blue-50 text-blue-600'
              }`}>
                {task.status}
              </span>
            </div>
          )) : (
            <div className="text-center py-12 text-slate-400">
              No tasks scheduled for today.
            </div>
          )}
        </div>
      </section>

      <section className="bg-blue-600 rounded-3xl p-6 text-white overflow-hidden relative">
        <div className="relative z-10">
          <h3 className="text-xl font-bold mb-1">AI Smart Tip</h3>
          <p className="text-blue-100 text-sm mb-4">
            Optimize your Praha 4 route today to save 15% on fuel costs.
          </p>
          <button className="bg-white text-blue-600 text-xs font-bold py-2 px-4 rounded-full">
            Show Route
          </button>
        </div>
        <div className="absolute top-[-20px] right-[-20px] opacity-10">
          <Icons.Sparkles />
        </div>
      </section>
    </div>
  );
};

const StatCard = ({ label, value, color }: { label: string, value: number, color: 'blue' | 'green' | 'orange' }) => {
  const colorMap = {
    blue: 'bg-blue-50 text-blue-600',
    green: 'bg-green-50 text-green-600',
    orange: 'bg-orange-50 text-orange-600'
  };

  return (
    <div className={`p-4 rounded-2xl ${colorMap[color]} flex flex-col items-center text-center`}>
      <span className="text-2xl font-black">{value}</span>
      <span className="text-[10px] font-bold uppercase opacity-70">{label}</span>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
}

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles }) => {
  const [showModal, setShowModal] = useState(false);
  const [newTask, setNewTask] = useState<Partial<MoveTask>>({
    title: '',
    customer: '',
    from: '',
    to: '',
    status: 'Pending'
  });

  const handleAddTask = () => {
    const id = Math.random().toString(36).substr(2, 9);
    const task: MoveTask = {
      ...newTask as MoveTask,
      id,
      start: new Date(),
      end: new Date(new Date().getTime() + 2 * 60 * 60 * 1000),
      assignedWorkers: [],
      assignedVehicles: []
    };
    setTasks([...tasks, task]);
    setShowModal(false);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-bold">Movement Calendar</h2>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-blue-600 text-white p-2 rounded-full shadow-lg"
        >
          <Icons.Plus />
        </button>
      </div>

      <div className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100">
        {/* Simple day picker mock */}
        <div className="flex justify-between mb-6">
          {['M','T','W','T','F','S','S'].map((day, i) => (
            <div key={i} className={`flex flex-col items-center gap-1 ${i === 2 ? 'text-blue-600' : 'text-slate-400'}`}>
              <span className="text-[10px] font-bold uppercase">{day}</span>
              <span className={`w-8 h-8 flex items-center justify-center rounded-full text-sm font-bold ${i === 2 ? 'bg-blue-600 text-white' : ''}`}>
                {15 + i}
              </span>
            </div>
          ))}
        </div>

        <div className="space-y-6">
          <div className="relative border-l-2 border-slate-100 pl-4 space-y-8">
            {tasks.map((task) => (
              <div key={task.id} className="relative">
                <div className="absolute -left-[22px] top-1 w-3 h-3 bg-blue-600 rounded-full border-2 border-white" />
                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] text-slate-400 font-bold uppercase">
                        {task.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {task.end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                      <h4 className="font-bold text-slate-800">{task.title}</h4>
                      <p className="text-xs text-slate-500 mt-1">{task.customer} • {task.from}</p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-t-[32px] sm:rounded-[32px] p-8 shadow-2xl animate-slide-up">
            <h3 className="text-2xl font-bold mb-6">New Move Task</h3>
            <div className="space-y-4">
              <input 
                type="text" 
                placeholder="Task Title (e.g. 3+1 Apartment)" 
                className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none"
                onChange={e => setNewTask({...newTask, title: e.target.value})}
              />
              <input 
                type="text" 
                placeholder="Customer Name" 
                className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none"
                onChange={e => setNewTask({...newTask, customer: e.target.value})}
              />
              <div className="grid grid-cols-2 gap-3">
                <input 
                  type="text" 
                  placeholder="From Address" 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none"
                  onChange={e => setNewTask({...newTask, from: e.target.value})}
                />
                <input 
                  type="text" 
                  placeholder="To Address" 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none"
                  onChange={e => setNewTask({...newTask, to: e.target.value})}
                />
              </div>
              <button 
                onClick={handleAddTask}
                className="w-full bg-blue-600 text-white font-bold py-4 rounded-2xl mt-4 shadow-lg shadow-blue-200"
              >
                Create Task
              </button>
              <button 
                onClick={() => setShowModal(false)}
                className="w-full text-slate-400 font-bold py-2"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

