      setCurrentTask({ ...currentTask, assignedVehicles: [...current, id] });
    }
  };

  // Helper to check if two tasks overlap in time
  const tasksOverlap = (t1Start: Date, t1End: Date, t2Start: Date, t2End: Date) => {
    return t1Start < t2End && t2Start < t1End;
  };

  // Find all busy workers and vehicles for the current task's time slot
  const getBusyEntities = () => {
    if (!currentTask.start || !currentTask.end) return { workers: [], vehicles: [] };

    const busyWorkers = new Set<string>();
    const busyVehicles = new Set<string>();

    tasks.forEach(task => {
      // Don't check overlap with itself when editing
      if (isEditing && task.id === currentTask.id) return;

      if (tasksOverlap(currentTask.start!, currentTask.end!, task.start, task.end)) {
        task.assignedWorkers.forEach(wId => busyWorkers.add(wId));
        task.assignedVehicles.forEach(vId => busyVehicles.add(vId));
      }
