            {tasks.map((task) => (
              <div 
                key={task.id} 
                className={`relative cursor-pointer transition-transform active:scale-95 ${user.role === 'admin' ? 'hover:translate-x-1' : ''}`}
                onClick={() => handleOpenEdit(task)}
              >
                <div className="absolute -left-[22px] top-1 w-3 h-3 bg-blue-600 rounded-full border-2 border-white" />
                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                  <div className="flex justify-between items-start">
