                          {task.assignedWorkers.map(wId => {
                            const w = workers.find(work => work.id === wId);
                            return w ? <span key={wId} className="text-[9px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold">{w.name}</span> : null;
                          })}
