                            const v = vehicles.find(veh => veh.id === vId);
                            return v ? <span key={vId} className="text-[9px] bg-orange-100 text-orange-700 px-2 py-0.5 rounded-full font-bold">{v.plate}</span> : null;
                          })}
                        </div>
                      )}
                    </div>
                    {user.role === 'admin' && <div className="text-slate-300"><Icons.ChevronRight /></div>}
