                        return (
                          <button
                            key={vehicle.id}
                            disabled={isBusy && !isSelected}
                            onClick={() => toggleVehicle(vehicle.id, isBusy)}
                            className={`flex items-center justify-between p-3 rounded-xl border transition-all ${
                              isSelected
                                ? 'bg-orange-50 border-orange-200 text-orange-700' 
                                : isBusy
                                  ? 'bg-slate-50 border-slate-100 text-slate-300 cursor-not-allowed opacity-60'
                                  : 'bg-white border-slate-100 text-slate-600'
                            }`}
                          >
                            <div className="flex flex-col items-start">
                              <span className="text-xs font-bold">{vehicle.plate} ({vehicle.model})</span>
                              {isBusy && !isSelected && <span className="text-[9px] font-medium text-red-400">Vozidlo je již obsazeno</span>}
                            </div>
                            {isSelected && <div className="w-2 h-2 bg-orange-600 rounded-full" />}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </>
              )}

              <button 
                onClick={handleSaveTask}
                className="w-full bg-blue-600 text-white font-bold py-4 rounded-2xl mt-4 shadow-lg shadow-blue-200"
              >
                {isEditing ? 'Uložit změny' : 'Vytvořit úkol'}
              </button>
              <button 
                onClick={() => setShowModal(false)}
                className="w-full text-slate-400 font-bold py-2"
              >
                Zrušit
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '',
    customer: '',
    from: '',
    to: '',
    status: 'Pending',
    assignedWorkers: [],
    assignedVehicles: []
  });

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date();
    const end = new Date(start.getTime() + 2 * 60 * 60 * 1000);
    setCurrentTask({
      title: '',
      customer: '',
      from: '',
      to: '',
      status: 'Pending',
      start,
      end,
      assignedWorkers: [],
      assignedVehicles: []
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    if (user.role !== 'admin') return;
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const handleSaveTask = () => {
    if (isEditing && currentTask.id) {
      setTasks(tasks.map(t => t.id === currentTask.id ? { ...t, ...currentTask } as MoveTask : t));
    } else {
      const id = Math.random().toString(36).substr(2, 9);
      const task: MoveTask = {
        ...(currentTask as MoveTask),
        id,
        start: currentTask.start || new Date(),
        end: currentTask.end || new Date(new Date().getTime() + 2 * 60 * 60 * 1000),
        assignedWorkers: currentTask.assignedWorkers || [],
        assignedVehicles: currentTask.assignedVehicles || []
      };
      setTasks([...tasks, task]);
    }
    setShowModal(false);
  };

  const toggleWorker = (id: string, isBusy: boolean) => {
    // Pokud je pracovník zaneprázdněn a není vybrán, nedovolíme přiřazení
    if (isBusy && !currentTask.assignedWorkers?.includes(id)) return;

    const current = currentTask.assignedWorkers || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedWorkers: current.filter(wId => wId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedWorkers: [...current, id] });
    }
  };

  const toggleVehicle = (id: string, isBusy: boolean) => {
    if (isBusy && !currentTask.assignedVehicles?.includes(id)) return;

    const current = currentTask.assignedVehicles || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedVehicles: current.filter(vId => vId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedVehicles: [...current, id] });
    }
  };

  // Helper to check if two tasks overlap in time
  const tasksOverlap = (t1Start: Date, t1End: Date, t2Start: Date, t2End: Date) => {
    return t1Start < t2End && t2Start < t1End;
  };

  // Find all busy workers and vehicles for the current task's time slot
  const busy = useMemo(() => {
    if (!currentTask.start || !currentTask.end) return { workers: [], vehicles: [] };

    const busyWorkers = new Set<string>();
    const busyVehicles = new Set<string>();

    tasks.forEach(task => {
      if (isEditing && task.id === currentTask.id) return;

      if (tasksOverlap(currentTask.start!, currentTask.end!, task.start, task.end)) {
        task.assignedWorkers.forEach(wId => busyWorkers.add(wId));
        task.assignedVehicles.forEach(vId => busyVehicles.add(vId));
      }
    });

    return { 
      workers: Array.from(busyWorkers), 
      vehicles: Array.from(busyVehicles) 
    };
