  // Kontrola, zda vybrané položky kolidují (např. po změně času)
  const collisions = useMemo(() => {
    const workerCollisions = (currentTask.assignedWorkers || []).filter(id => busy.workers.includes(id));
    const vehicleCollisions = (currentTask.assignedVehicles || []).filter(id => busy.vehicles.includes(id));
    return { workers: workerCollisions, vehicles: vehicleCollisions };
  }, [currentTask.assignedWorkers, currentTask.assignedVehicles, busy]);

  const hasCollisions = collisions.workers.length > 0 || collisions.vehicles.length > 0;

