              </span>
            </div>
          ))}
        </div>

        <div className="space-y-6">
          <div className="relative border-l-2 border-slate-100 pl-4 space-y-8">
            {tasks.map((task) => (
              <div 
                key={task.id} 
                className={`relative cursor-pointer transition-all active:scale-95 ${user.role === 'admin' ? 'hover:translate-x-1' : ''}`}
                onClick={() => handleOpenEdit(task)}
              >
                <div className="absolute -left-[22px] top-1 w-3 h-3 bg-blue-600 rounded-full border-2 border-white shadow-sm" />
                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 hover:bg-white hover:shadow-md transition-all">
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">
                        {task.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {task.end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                      <h4 className="font-bold text-slate-800">{task.title}</h4>
                      <p className="text-xs text-slate-500 mt-1">{task.customer} • {task.from}</p>

                      {(task.assignedWorkers.length > 0 || task.assignedVehicles.length > 0) && (
                        <div className="flex flex-wrap gap-2 mt-3">
                          {task.assignedWorkers.map(wId => {
                            const w = workers.find(work => work.id === wId);
                            return w ? <span key={wId} className="text-[9px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold shadow-sm">{w.name}</span> : null;
                          })}
                          {task.assignedVehicles.map(vId => {
                            const v = vehicles.find(veh => veh.id === vId);
                            return v ? <span key={vId} className="text-[9px] bg-orange-100 text-orange-700 px-2 py-0.5 rounded-full font-bold shadow-sm">{v.plate}</span> : null;
                          })}
                        </div>
                      )}
                    </div>
                    {user.role === 'admin' && <div className="text-slate-300"><Icons.ChevronRight /></div>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-t-[32px] sm:rounded-[42px] p-8 shadow-2xl animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-black text-slate-900">{isEditing ? 'Upravit úkol' : 'Nové stěhování'}</h3>
                <button onClick={() => setShowModal(false)} className="p-2 text-slate-400"><Icons.Sparkles /></button>
            </div>

            {hasCollisions && (
              <div className="bg-red-50 border border-red-100 rounded-2xl p-4 mb-6 animate-pulse">
                <div className="flex items-center gap-2 text-red-600 mb-1">
