                        const hasCollision = isSelected && isBusy;

                        return (
                          <button
                            key={vehicle.id}
                            disabled={isBusy && !isSelected}
                            onClick={() => toggleVehicle(vehicle.id, isBusy)}
                            className={`flex items-center justify-between p-3 rounded-2xl border transition-all ${
                              hasCollision
                                ? 'bg-red-50 border-red-300 text-red-700'
                                : isSelected
                                  ? 'bg-orange-50 border-orange-200 text-orange-700 shadow-sm' 
                                  : isBusy
                                    ? 'bg-slate-50 border-slate-100 text-slate-300 cursor-not-allowed opacity-40 grayscale'
                                    : 'bg-white border-slate-100 text-slate-600 hover:border-orange-100'
                            }`}
                          >
                            <div className="flex flex-col items-start">
                              <span className="text-xs font-bold">{vehicle.plate} ({vehicle.model})</span>
                              {isBusy && !isSelected && <span className="text-[9px] font-bold text-red-300 uppercase">Vozidlo obsazeno</span>}
                              {hasCollision && <span className="text-[9px] font-black uppercase text-red-500">Konflikt v kalendáři!</span>}
                            </div>
                            {isSelected && (
                                <div className={`w-4 h-4 rounded-full flex items-center justify-center ${hasCollision ? 'bg-red-500' : 'bg-orange-600'}`}>
                                    <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                                </div>
                            )}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </>
              )}

              <button 
                onClick={handleSaveTask}
                disabled={hasCollisions}
                className={`w-full text-white font-black py-4 rounded-2xl mt-4 shadow-xl transition-all active:scale-95 ${
                    hasCollisions 
                    ? 'bg-slate-200 cursor-not-allowed shadow-none' 
                    : 'bg-blue-600 shadow-blue-200 hover:bg-blue-700'
                }`}
              >
                {isEditing ? 'Uložit změny' : 'Vytvořit úkol'}
              </button>
              <button 
                onClick={() => setShowModal(false)}
                className="w-full text-slate-400 font-bold py-2 hover:text-slate-600"
              >
                Zrušit
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

