                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">
                        {task.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - {task.end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                      <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{task.title}</h4>
                      <p className="text-xs text-slate-500 mt-1">{task.customer} • {task.from}</p>

                      <div className="flex flex-wrap gap-2 mt-3">
                        {task.assignedWorkers.slice(0, 2).map(wId => {
                          const w = workers.find(work => work.id === wId);
                          return w ? <span key={wId} className="text-[9px] bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-bold">{w.name}</span> : null;
                        })}
                        {task.assignedWorkers.length > 2 && <span className="text-[9px] text-slate-400 font-bold">+{task.assignedWorkers.length - 2}</span>}
                      </div>
                    </div>
                    <div className="text-slate-300"><Icons.ChevronRight /></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
