import React, { useState } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles }) => {
  const [selectedTask, setSelectedTask] = useState<MoveTask | null>(null);

  const activeTasks = tasks.filter(t => t.status !== 'Completed');
  const availableWorkers = workers.filter(w => w.status === 'Available');
  const availableVehicles = vehicles.filter(v => v.status === 'Ready');

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  const isTomorrow = (date: Date) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return date.getDate() === tomorrow.getDate() &&
      date.getMonth() === tomorrow.getMonth() &&
      date.getFullYear() === tomorrow.getFullYear();
  };

  const todayTasks = tasks.filter(t => isToday(t.start));
  const tomorrowTasks = tasks.filter(t => isTomorrow(t.start));

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const TaskCard = ({ task }: { task: MoveTask }) => (
    <div 
      onClick={() => setSelectedTask(task)}
      className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex items-center gap-4 hover:shadow-md transition-all cursor-pointer active:scale-[0.98]"
    >
      <div className="flex flex-col items-center justify-center bg-blue-50 rounded-2xl p-3 min-w-[70px]">
        <span className="text-blue-600 font-black text-lg">
          {task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}
        </span>
        <span className="text-[9px] font-bold text-blue-400 uppercase tracking-widest">START</span>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-bold text-slate-800 truncate">{task.title}</h3>
        <p className="text-xs text-slate-500 font-medium truncate">{task.customer}</p>
        <div className="flex items-center gap-2 mt-1">
          <span className="text-[10px] text-slate-400 font-bold truncate">
            {task.from} &rarr; {task.to}
          </span>
