      </div>

      <div className={`w-2 h-2 rounded-full ${
        task.status === 'Confirmed' ? 'bg-green-500' : 
        task.status === 'In Progress' ? 'bg-orange-500' : 'bg-slate-300'
      }`} />
    </div>
  );

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-3 gap-3">
        <StatCard label="Aktivní" value={activeTasks.length} color="blue" />
        <StatCard label="Lidé" value={availableWorkers.length} color="green" />
        <StatCard label="Auta" value={availableVehicles.length} color="orange" />
      </div>

      <section className="space-y-4">
        <div className="flex items-center gap-2 px-2">
          <div className="w-1 h-5 bg-blue-600 rounded-full" />
          <h2 className="text-lg font-black text-slate-800">DNES</h2>
        </div>
        <div className="space-y-3">
          {todayTasks.length > 0 ? todayTasks.map(task => (
            <TaskCard key={task.id} task={task} />
          )) : (
            <div className="bg-slate-100/50 rounded-3xl p-6 text-center border border-dashed border-slate-200">
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Dnes žádné plány</p>
            </div>
          )}
        </div>
      </section>

      <section className="space-y-4">
        <div className="flex items-center gap-2 px-2">
          <div className="w-1 h-5 bg-slate-400 rounded-full" />
          <h2 className="text-lg font-black text-slate-800">ZÍTRA</h2>
        </div>
        <div className="space-y-3">
          {tomorrowTasks.length > 0 ? tomorrowTasks.map(task => (
            <TaskCard key={task.id} task={task} />
          )) : (
            <div className="bg-slate-100/50 rounded-3xl p-6 text-center border border-dashed border-slate-200">
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Zítra bez zakázek</p>
            </div>
          )}
        </div>
      </section>

      {/* Quick Task Detail Modal */}
      {selectedTask && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4" onClick={() => setSelectedTask(null)}>
          <div 
            className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-[40px] p-8 shadow-2xl animate-slide-up"
            onClick={e => e.stopPropagation()}
