            <div className="flex justify-between items-start mb-6">
              <div>
                <span className={`text-[10px] font-black uppercase tracking-[0.2em] px-3 py-1 rounded-full mb-2 inline-block ${
                  selectedTask.status === 'Confirmed' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'
                }`}>
                  {selectedTask.status}
                </span>
                <h3 className="text-2xl font-black text-slate-900">{selectedTask.title}</h3>
              </div>
              <button onClick={() => setSelectedTask(null)} className="bg-slate-100 p-2 rounded-2xl hover:bg-slate-200 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>

            <div className="space-y-6">
              <div className="flex items-center justify-between bg-slate-50 p-4 rounded-3xl">
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Zákazník</p>
                  <p className="font-bold text-slate-800">{selectedTask.customer}</p>
                </div>
                {selectedTask.customerPhone && (
                  <a href={`tel:${selectedTask.customerPhone.replace(/\s+/g, '')}`} className="bg-blue-600 text-white p-4 rounded-2xl shadow-lg shadow-blue-100 active:scale-95 transition-all">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
                  </a>
                )}
              </div>

              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => handleOpenMaps(selectedTask.from)} className="bg-white border border-slate-100 p-5 rounded-3xl text-left hover:bg-slate-50 transition-all active:scale-95">
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-2">ODKUD</p>
                  <p className="text-xs font-bold text-slate-800 line-clamp-1">{selectedTask.from}</p>
                </button>
                <button onClick={() => handleOpenMaps(selectedTask.to)} className="bg-white border border-slate-100 p-5 rounded-3xl text-left hover:bg-slate-50 transition-all active:scale-95">
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-2">KAM</p>
                  <p className="text-xs font-bold text-slate-800 line-clamp-1">{selectedTask.to}</p>
                </button>
              </div>

              <div className="flex items-center gap-3 p-4 border-2 border-dashed border-slate-100 rounded-3xl">
                <div className="w-10 h-10 bg-blue-50 rounded-2xl flex items-center justify-center text-blue-600">
                  <Icons.Calendar />
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">ČASOVÝ RÁMEC</p>
                  <p className="text-sm font-black text-slate-800">
                    {selectedTask.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} 
                    {' - '} 
                    {selectedTask.end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                </div>
              </div>

              <button 
                onClick={() => setSelectedTask(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-3xl shadow-xl transition-all active:scale-95 mt-2"
              >
                ROZUMÍM
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard = ({ label, value, color }: { label: string, value: number, color: 'blue' | 'green' | 'orange' }) => {
  const colorMap = {
    blue: 'bg-blue-50 text-blue-600 border-blue-100',
    green: 'bg-green-50 text-green-600 border-green-100',
    orange: 'bg-orange-50 text-orange-600 border-orange-100'
  };

  return (
    <div className={`p-5 rounded-[2.5rem] ${colorMap[color]} border flex flex-col items-center text-center shadow-sm`}>
      <span className="text-2xl font-black mb-0.5">{value}</span>
      <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{label}</span>
    </div>
  );
};

