      from: 'Praha 1',
      to: 'Praha 4',
      assignedWorkers: ['1', '2'],
      assignedVehicles: ['1'],
      status: 'Confirmed'
    },
    {
      id: 't2',
      title: 'Kanceláře "TechHub"',
      customer: 'Alena Modrá',
      customerPhone: '+420 603 444 555',
      start: getTomorrow(),
      end: new Date(getTomorrow().getTime() + 6 * 60 * 60 * 1000),
      from: 'Brno Střed',
      to: 'Ostrava - Poruba',
      assignedWorkers: ['3'],
      assignedVehicles: ['2'],
      status: 'Pending'
