    const matchingWorker = workers.find(w => w.email?.toLowerCase() === mockGoogleEmail.toLowerCase());

    setUser({
      name: matchingWorker ? matchingWorker.name : 'Uživatel Stěhovák',
      email: mockGoogleEmail,
      avatar: 'https://picsum.photos/seed/user/200/200',
      role: 'admin', // For demo we keep admin role
      workerId: matchingWorker?.id
    });
  };

  const getTabLabel = (tab: AppTab) => {
    switch (tab) {
      case AppTab.DASHBOARD: return 'PŘEHLED';
      case AppTab.CALENDAR: return 'KALENDÁŘ';
      case AppTab.FLEET: return 'FLOTILA';
      case AppTab.AI_LAB: return 'AI LABORATOŘ';
      case AppTab.PROFILE: return 'PROFIL';
      default: return '';
    }
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-800 flex flex-col items-center justify-center p-6 text-white">
        <div className="w-24 h-24 bg-white rounded-3xl mb-6 flex items-center justify-center shadow-2xl text-blue-600">
