    switch (activeTab) {
      case AppTab.DASHBOARD: return <Dashboard tasks={tasks} workers={workers} vehicles={vehicles} />;
      case AppTab.CALENDAR: return <CalendarView tasks={tasks} setTasks={setTasks} workers={workers} vehicles={vehicles} user={user} />;
