import React, { useState, useRef } from 'react';
import { Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface FleetViewProps {
  workers: Worker[];
  setWorkers: React.Dispatch<React.SetStateAction<Worker[]>>;
  vehicles: Vehicle[];
  setVehicles: React.Dispatch<React.SetStateAction<Vehicle[]>>;
}

const FleetView: React.FC<FleetViewProps> = ({ workers, setWorkers, vehicles, setVehicles }) => {
  const [activeSubTab, setActiveSubTab] = useState<'workers' | 'vehicles'>('workers');

  // Modals state
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [selectedVehicle, setSelectedVehicle] = useState<Partial<Vehicle> | null>(null);

  const [showWorkerModal, setShowWorkerModal] = useState(false);
  const [selectedWorker, setSelectedWorker] = useState<Partial<Worker> | null>(null);

  const carImageRef = useRef<HTMLInputElement>(null);
  const techCertImageRef = useRef<HTMLInputElement>(null);
  const workerPhotoRef = useRef<HTMLInputElement>(null);

  const getRoleLabel = (role: string) => {
    switch(role) {
      case 'Driver': return 'Řidič';
      case 'Loader': return 'Stěhovák';
      case 'Specialist': return 'Specialista';
      default: return role;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'Available': return 'Volný';
      case 'On Task': return 'Na zakázce';
      case 'Off': return 'Mimo službu';
      case 'Ready': return 'Připraveno';
      case 'In Use': return 'V provozu';
      case 'Maintenance': return 'V servisu';
      default: return status;
    }
  };

  // Workers handlers
  const handleOpenWorkerDetail = (worker: Worker) => {
    setSelectedWorker({ ...worker });
    setShowWorkerModal(true);
  };

  const handleAddWorker = () => {
    setSelectedWorker({
      name: '',
      email: '',
      phone: '',
      role: 'Loader',
      status: 'Available',
      licenseInfo: '',
      photo: ''
    });
    setShowWorkerModal(true);
  };

  const handleSaveWorker = () => {
    if (!selectedWorker) return;

    if (selectedWorker.id) {
      setWorkers(workers.map(w => w.id === selectedWorker.id ? selectedWorker as Worker : w));
    } else {
      const newWorker: Worker = {
        ...selectedWorker as Worker,
        id: Math.random().toString(36).substr(2, 9)
      };
      setWorkers([...workers, newWorker]);
    }
    setShowWorkerModal(false);
  };

  const handleWorkerPhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedWorker(prev => prev ? { ...prev, photo: reader.result as string } : null);
      };
      reader.readAsDataURL(file);
    }
  };

  // Vehicle handlers
  const handleOpenVehicleDetail = (vehicle: Vehicle) => {
    setSelectedVehicle({ ...vehicle });
    setShowVehicleModal(true);
  };

  const handleAddVehicle = () => {
    setSelectedVehicle({
      plate: '',
      model: '',
      capacity: '',
      status: 'Ready',
      vin: '',
      stkExpiration: '',
      vignetteExpiration: '',
      insuranceInfo: ''
    });
    setShowVehicleModal(true);
  };

  const handleSaveVehicle = () => {
    if (!selectedVehicle) return;

    if (selectedVehicle.id) {
      setVehicles(vehicles.map(v => v.id === selectedVehicle.id ? selectedVehicle as Vehicle : v));
    } else {
      const newVehicle: Vehicle = {
        ...selectedVehicle as Vehicle,
        id: Math.random().toString(36).substr(2, 9)
      };
      setVehicles([...vehicles, newVehicle]);
    }
    setShowVehicleModal(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, field: 'carImage' | 'techCertImage') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedVehicle(prev => prev ? { ...prev, [field]: reader.result as string } : null);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-200 p-1 rounded-2xl flex shadow-inner">
        <button 
          onClick={() => setActiveSubTab('workers')}
          className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${activeSubTab === 'workers' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
        >
          Pracovníci
        </button>
        <button 
          onClick={() => setActiveSubTab('vehicles')}
          className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${activeSubTab === 'vehicles' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
        >
          Vozidla
        </button>
      </div>

      <div className="space-y-3">
        {activeSubTab === 'workers' ? (
          workers.map(worker => (
            <div 
              key={worker.id} 
              onClick={() => handleOpenWorkerDetail(worker)}
              className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center gap-4 hover:shadow-md transition-all cursor-pointer group"
            >
              <div className="w-12 h-12 bg-blue-50 rounded-full flex items-center justify-center text-blue-600 shadow-sm overflow-hidden border border-blue-100">
                {worker.photo ? (
                  <img src={worker.photo} className="w-full h-full object-cover" alt={worker.name} />
                ) : (
                  <Icons.User />
                )}
              </div>
              <div className="flex-1">
                <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{worker.name}</h4>
                <p className="text-xs text-slate-500">{getRoleLabel(worker.role)} • {worker.phone}</p>
                {worker.email && <p className="text-[9px] text-slate-400 font-medium truncate">{worker.email}</p>}
              </div>
              <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-tight ${
                worker.status === 'Available' ? 'bg-green-50 text-green-600' : 'bg-orange-50 text-orange-600'
              }`}>
                {getStatusLabel(worker.status)}
              </span>
            </div>
          ))
        ) : (
          vehicles.map(vehicle => (
            <div 
              key={vehicle.id} 
              onClick={() => handleOpenVehicleDetail(vehicle)}
              className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center gap-4 hover:shadow-md transition-all cursor-pointer group"
            >
              <div className="w-12 h-12 bg-orange-50 rounded-full overflow-hidden flex items-center justify-center text-orange-600 shadow-sm border border-orange-100">
                {vehicle.carImage ? (
                  <img src={vehicle.carImage} className="w-full h-full object-cover" alt="Car" />
                ) : (
                  <Icons.Truck />
                )}
              </div>
              <div className="flex-1">
                <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{vehicle.plate}</h4>
                <p className="text-xs text-slate-500">{vehicle.model} • {vehicle.capacity}</p>
                {vehicle.stkExpiration && (
                  <p className="text-[9px] text-slate-400 mt-1 font-bold uppercase">STK: {new Date(vehicle.stkExpiration).toLocaleDateString()}</p>
                )}
              </div>
              <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-tight ${
                vehicle.status === 'Ready' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'
              }`}>
                {getStatusLabel(vehicle.status)}
              </span>
            </div>
          ))
        )}
      </div>

      <button 
        onClick={activeSubTab === 'workers' ? handleAddWorker : handleAddVehicle}
        className="w-full border-2 border-dashed border-slate-200 py-4 rounded-2xl flex items-center justify-center gap-2 text-slate-400 font-bold hover:bg-slate-50 hover:border-slate-300 transition-all active:scale-[0.98]"
      >
        <Icons.Plus />
        Přidat {activeSubTab === 'workers' ? 'pracovníka' : 'vozidlo'}
      </button>

      {/* Worker Detail / Edit Modal */}
      {showWorkerModal && selectedWorker && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
