                    value={selectedWorker.phone}
                    onChange={e => setSelectedWorker({...selectedWorker, phone: e.target.value})}
                    placeholder="+420..."
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pozice</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none text-sm appearance-none"
                    value={selectedWorker.role}
                    onChange={e => setSelectedWorker({...selectedWorker, role: e.target.value as any})}
                  >
                    <option value="Driver">Řidič</option>
