import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type StatusType = MoveTask['status'];

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // States for filtering
  const [showFilters, setShowFilters] = useState(false);
  const [filterStatus, setFilterStatus] = useState<StatusType | 'All'>('All');
  const [filterWorker, setFilterWorker] = useState<string>('All');
  const [filterVehicle, setFilterVehicle] = useState<string>('All');

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '',
    customer: '',
    customerPhone: '',
    from: '',
    to: '',
    status: 'Pending',
    assignedWorkers: [],
    assignedVehicles: []
  });

  // Helper to open Google Maps
  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  // Filtering Logic
  const filteredTasks = useMemo(() => {
    return tasks.filter(task => {
      const statusMatch = filterStatus === 'All' || task.status === filterStatus;
      const workerMatch = filterWorker === 'All' || task.assignedWorkers.includes(filterWorker);
      const vehicleMatch = filterVehicle === 'All' || task.assignedVehicles.includes(filterVehicle);
      return statusMatch && workerMatch && vehicleMatch;
    });
  }, [tasks, filterStatus, filterWorker, filterVehicle]);

  // Timeline Constants
  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 80; // px

  // Calculate layout positions for tasks to handle overlaps
  const positionedTasks = useMemo(() => {
    const sorted = [...filteredTasks].sort((a, b) => a.start.getTime() - b.start.getTime());
    const columns: MoveTask[][] = [];

    sorted.forEach(task => {
      let placed = false;
      for (let i = 0; i < columns.length; i++) {
        const lastTaskInColumn = columns[i][columns[i].length - 1];
        if (task.start >= lastTaskInColumn.end) {
          columns[i].push(task);
          placed = true;
          break;
        }
      }
      if (!placed) {
        columns.push([task]);
      }
    });

    return columns.flatMap((column, colIndex) => 
      column.map(task => ({
        ...task,
        colIndex,
        totalCols: columns.length
      }))
    );
  }, [filteredTasks]);

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date();
    start.setMinutes(0);
    const end = new Date(start.getTime() + 2 * 60 * 60 * 1000);
    setCurrentTask({
      title: '',
      customer: '',
      customerPhone: '',
      from: '',
      to: '',
      status: 'Pending',
      start,
      end,
      assignedWorkers: [],
      assignedVehicles: []
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const handleSaveTask = () => {
    if (user.role !== 'admin') return;

    if (isEditing && currentTask.id) {
      setTasks(tasks.map(t => t.id === currentTask.id ? { ...t, ...currentTask } as MoveTask : t));
    } else {
      const id = Math.random().toString(36).substr(2, 9);
      const task: MoveTask = {
        ...(currentTask as MoveTask),
        id,
        start: currentTask.start || new Date(),
        end: currentTask.end || new Date(new Date().getTime() + 2 * 60 * 60 * 1000),
        assignedWorkers: currentTask.assignedWorkers || [],
        assignedVehicles: currentTask.assignedVehicles || []
      };
      setTasks([...tasks, task]);
    }
    setShowModal(false);
  };

  const toggleWorker = (id: string, isBusy: boolean) => {
    if (user.role !== 'admin') return;
    const current = currentTask.assignedWorkers || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedWorkers: current.filter(wId => wId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedWorkers: [...current, id] });
    }
  };

  const toggleVehicle = (id: string, isBusy: boolean) => {
    if (user.role !== 'admin') return;
    const current = currentTask.assignedVehicles || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedVehicles: current.filter(vId => vId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedVehicles: [...current, id] });
    }
  };

  const resetFilters = () => {
    setFilterStatus('All');
    setFilterWorker('All');
    setFilterVehicle('All');
  };

  const isFilterActive = filterStatus !== 'All' || filterWorker !== 'All' || filterVehicle !== 'All';

  // Helper for status colors
  const getStatusColorClass = (status: StatusType) => {
    switch(status) {
      case 'Completed': return 'bg-green-100 border-green-200 text-green-700';
      case 'In Progress': return 'bg-orange-100 border-orange-200 text-orange-700';
      case 'Confirmed': return 'bg-blue-100 border-blue-200 text-blue-700';
      default: return 'bg-slate-100 border-slate-200 text-slate-600';
    }
  };

  return (
    <div className="space-y-4">
      {/* Header with Filter Toggle */}
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-bold">Kalendář stěhování</h2>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-2 rounded-full transition-all border ${showFilters || isFilterActive ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-100 text-slate-400'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
          </button>
          {user.role === 'admin' && (
            <button 
              onClick={handleOpenCreate}
              className="bg-blue-600 text-white p-2 rounded-full shadow-lg hover:scale-105 transition-transform"
            >
              <Icons.Plus />
            </button>
          )}
        </div>
      </div>

      {/* Filter Bar */}
      {showFilters && (
        <div className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 space-y-4 animate-fade-in">
          <div className="flex flex-col gap-3">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Stav úkolu</label>
              <div className="flex flex-wrap gap-2">
                {(['All', 'Pending', 'Confirmed', 'In Progress', 'Completed'] as const).map(status => (
                  <button
                    key={status}
                    onClick={() => setFilterStatus(status)}
                    className={`px-3 py-1.5 rounded-full text-[10px] font-bold transition-all border ${filterStatus === status ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                  >
                    {status === 'All' ? 'Vše' : status === 'Pending' ? 'Čeká' : status === 'Confirmed' ? 'Potvrzeno' : status === 'In Progress' ? 'Probíhá' : 'Hotovo'}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pracovník</label>
                <select 
                  className="w-full bg-slate-50 border-none rounded-xl p-2.5 text-[11px] font-medium outline-none focus:ring-2 focus:ring-blue-600 transition-all"
                  value={filterWorker}
                  onChange={(e) => setFilterWorker(e.target.value)}
                >
                  <option value="All">Všichni</option>
                  {workers.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Vozidlo</label>
                <select 
                  className="w-full bg-slate-50 border-none rounded-xl p-2.5 text-[11px] font-medium outline-none focus:ring-2 focus:ring-blue-600 transition-all"
                  value={filterVehicle}
                  onChange={(e) => setFilterVehicle(e.target.value)}
                >
                  <option value="All">Všechna</option>
                  {vehicles.map(v => <option key={v.id} value={v.id}>{v.plate} ({v.model})</option>)}
                </select>
              </div>
            </div>

            {isFilterActive && (
              <button 
                onClick={resetFilters}
                className="text-[10px] font-black text-blue-600 uppercase tracking-widest hover:underline text-right"
              >
                Vymazat filtry
              </button>
            )}
          </div>
        </div>
      )}

      {/* Modern Day Timeline View */}
      <div className="bg-white rounded-[32px] shadow-sm border border-slate-100 overflow-hidden flex flex-col h-[600px]">
        {/* Days Header */}
        <div className="flex justify-between p-4 border-b border-slate-50">
          {['PO','ÚT','ST','ČT','PÁ','SO','NE'].map((day, i) => (
            <div key={i} className={`flex flex-col items-center gap-1 flex-1 ${i === 2 ? 'text-blue-600' : 'text-slate-400'}`}>
              <span className="text-[10px] font-bold uppercase tracking-wider">{day}</span>
              <span className={`w-8 h-8 flex items-center justify-center rounded-xl text-xs font-black ${i === 2 ? 'bg-blue-600 text-white shadow-lg' : ''}`}>
                {15 + i}
              </span>
            </div>
          ))}
        </div>

        {/* Scrollable Timeline */}
        <div className="flex-1 overflow-y-auto no-scrollbar relative p-4 pt-2">
          {/* Time Labels Column */}
          <div className="absolute left-4 top-2 bottom-0 w-10 z-10 pointer-events-none">
            {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
              <div 
                key={i} 
                className="text-[10px] font-bold text-slate-300 h-[80px]"
                style={{ height: `${HOUR_HEIGHT}px` }}
              >
                {String(START_HOUR + i).padStart(2, '0')}:00
              </div>
            ))}
          </div>

          {/* Grid Lines */}
          <div className="ml-12 relative h-full min-h-[1280px]">
            {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
              <div 
                key={i} 
                className="border-t border-slate-50 absolute w-full pointer-events-none"
                style={{ top: `${i * HOUR_HEIGHT}px` }}
              />
            ))}

            {/* Current Time Indicator (Static mock for now) */}
            <div className="absolute left-0 right-0 border-t-2 border-red-400 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
              <div className="w-2 h-2 rounded-full bg-red-400 -ml-1 shadow-sm" />
            </div>

            {/* Task Blocks */}
            {positionedTasks.map((task) => {
              const startDecimal = task.start.getHours() + task.start.getMinutes() / 60;
              const endDecimal = task.end.getHours() + task.end.getMinutes() / 60;
              const duration = Math.max(0.5, endDecimal - startDecimal);

              const top = (startDecimal - START_HOUR) * HOUR_HEIGHT;
              const height = duration * HOUR_HEIGHT;
              const width = 100 / task.totalCols;
              const left = task.colIndex * width;

              return (
                <div
                  key={task.id}
                  onClick={() => handleOpenEdit(task)}
                  className={`absolute p-1 transition-all cursor-pointer group z-20`}
                  style={{ 
                    top: `${top}px`, 
                    height: `${height}px`, 
                    left: `${left}%`, 
                    width: `${width}%` 
                  }}
                >
                  <div className={`h-full w-full rounded-2xl border-2 p-3 shadow-sm hover:shadow-md transition-all overflow-hidden flex flex-col ${getStatusColorClass(task.status)}`}>
                    <div className="flex justify-between items-start gap-1">
                      <h4 className="text-[11px] font-black leading-tight line-clamp-2">{task.title}</h4>
                      <span className="text-[9px] opacity-70 font-mono whitespace-nowrap">
                        {task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}
                      </span>
                    </div>

                    <div className="mt-1 flex-1 min-h-0">
                      <p className="text-[9px] opacity-70 font-bold truncate">{task.customer}</p>

                      <div className="flex flex-wrap gap-1 mt-2 items-center">
                        {/* Worker Icons Logic */}
                        {task.assignedWorkers.length <= 2 ? (
                          task.assignedWorkers.map(wId => (
                            <div key={wId} className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden">
                              <Icons.User />
                            </div>
                          ))
                        ) : (
                          <div className="flex items-center gap-0.5">
                            <div className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden">
                              <Icons.User />
                            </div>
                            <span className="text-[8px] font-black text-inherit">+{task.assignedWorkers.length - 1}</span>
                          </div>
                        )}

                        {/* Vehicle Icon */}
                        {task.assignedVehicles.length > 0 && (
                          <div className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden ml-0.5">
                            <Icons.Truck />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}

            {positionedTasks.length === 0 && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-300 pointer-events-none">
                <Icons.Calendar />
                <p className="text-xs font-bold uppercase tracking-widest mt-2">Žádné zakázky</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Task Modal (remains largely same as before for consistent editing) */}
      {showModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-t-[32px] sm:rounded-[32px] p-8 shadow-2xl animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-black text-slate-900">
                  {isEditing ? (user.role === 'admin' ? 'Upravit úkol' : 'Detail úkolu') : 'Nové stěhování'}
                </h3>
                <button onClick={() => setShowModal(false)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                </button>
            </div>

            <div className="space-y-6">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Název úkolu</label>
                  {user.role === 'admin' ? (
                    <input 
                      type="text" 
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-bold text-slate-800"
                      value={currentTask.title}
                      onChange={e => setCurrentTask({...currentTask, title: e.target.value})}
                    />
                  ) : (
                    <p className="p-4 bg-slate-50 rounded-2xl font-bold text-slate-800">{currentTask.title}</p>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Zákazník</label>
                    {user.role === 'admin' ? (
                      <input 
                        type="text" 
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-medium text-sm"
                        value={currentTask.customer}
                        onChange={e => setCurrentTask({...currentTask, customer: e.target.value})}
                      />
                    ) : (
                      <p className="p-4 bg-slate-50 rounded-2xl font-medium text-slate-700 text-sm">{currentTask.customer}</p>
                    )}
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Telefon</label>
                    {user.role === 'admin' ? (
                      <input 
                        type="tel" 
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-medium text-sm"
                        value={currentTask.customerPhone}
                        onChange={e => setCurrentTask({...currentTask, customerPhone: e.target.value})}
                      />
                    ) : (
                      <a 
                        href={`tel:${currentTask.customerPhone?.replace(/\s+/g, '')}`}
                        className="p-4 bg-blue-50 rounded-2xl font-bold text-blue-600 text-sm flex items-center gap-2"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
                        {currentTask.customerPhone}
                      </a>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Odkud</label>
                    {user.role === 'admin' ? (
                      <div className="relative group">
                        <input 
                          type="text" 
                          className="w-full bg-slate-100 border-none rounded-2xl p-4 pr-10 focus:ring-2 focus:ring-blue-600 outline-none text-sm"
                          value={currentTask.from}
                          onChange={e => setCurrentTask({...currentTask, from: e.target.value})}
                        />
                        <button 
                          onClick={() => handleOpenMaps(currentTask.from)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-300 hover:text-blue-600 transition-colors"
                          title="Zobrazit na mapě"
                        >
                          <Icons.Map />
                        </button>
                      </div>
                    ) : (
                      <button 
                        onClick={() => handleOpenMaps(currentTask.from)}
                        className="w-full p-4 bg-slate-50 rounded-2xl text-left hover:bg-blue-50 group transition-all"
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-sm font-medium text-slate-700 truncate">{currentTask.from || '---'}</span>
                          <div className="text-slate-300 group-hover:text-blue-500 transition-colors">
                            <Icons.Map />
                          </div>
                        </div>
                      </button>
                    )}
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Kam</label>
                    {user.role === 'admin' ? (
                      <div className="relative group">
                        <input 
                          type="text" 
                          className="w-full bg-slate-100 border-none rounded-2xl p-4 pr-10 focus:ring-2 focus:ring-blue-600 outline-none text-sm"
                          value={currentTask.to}
                          onChange={e => setCurrentTask({...currentTask, to: e.target.value})}
                        />
                        <button 
                          onClick={() => handleOpenMaps(currentTask.to)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-300 hover:text-blue-600 transition-colors"
                          title="Zobrazit na mapě"
                        >
                          <Icons.Map />
                        </button>
                      </div>
                    ) : (
                      <button 
                        onClick={() => handleOpenMaps(currentTask.to)}
                        className="w-full p-4 bg-slate-50 rounded-2xl text-left hover:bg-blue-50 group transition-all"
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-sm font-medium text-slate-700 truncate">{currentTask.to || '---'}</span>
                          <div className="text-slate-300 group-hover:text-blue-500 transition-colors">
                            <Icons.Map />
                          </div>
                        </div>
                      </button>
                    )}
                  </div>
                </div>

                {user.role === 'admin' && (
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Stav</label>
                    <div className="flex gap-2 flex-wrap">
                      {(['Pending', 'Confirmed', 'In Progress', 'Completed'] as const).map(s => (
                        <button
                          key={s}
                          onClick={() => setCurrentTask({...currentTask, status: s})}
                          className={`px-3 py-1.5 rounded-full text-[10px] font-bold transition-all border ${currentTask.status === s ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Assignments Section */}
              <div className="space-y-6 pt-4 border-t border-slate-100">
                <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pracovníci</label>
                  <div className="grid grid-cols-1 gap-2">
                    {workers.map(worker => {
                      const isSelected = currentTask.assignedWorkers?.includes(worker.id);
                      if (user.role !== 'admin' && !isSelected) return null;
                      return (
                        <button
                          key={worker.id}
                          disabled={user.role !== 'admin'}
                          onClick={() => toggleWorker(worker.id, false)}
                          className={`flex items-center justify-between p-4 rounded-2xl border transition-all text-left ${
                            isSelected ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-100'
                          }`}
                        >
                          <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isSelected ? 'bg-blue-100' : 'bg-slate-100'}`}>
                              <Icons.User />
                            </div>
                            <span className="text-xs font-bold">{worker.name}</span>
                          </div>
                          {isSelected && <div className="w-4 h-4 rounded-full bg-blue-600 flex items-center justify-center"><svg width="8" height="8" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="4"><polyline points="20 6 9 17 4 12"/></svg></div>}
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>

              {user.role === 'admin' ? (
                <button 
                  onClick={handleSaveTask}
                  className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl mt-4 shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
                >
                  {isEditing ? 'Uložit změny' : 'Vytvořit úkol'}
                </button>
              ) : (
                <button 
                  onClick={() => setShowModal(false)}
                  className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl mt-4"
                >
                  Zavřít
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type StatusType = MoveTask['status'];

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // States for filtering
  const [showFilters, setShowFilters] = useState(false);
  const [filterStatus, setFilterStatus] = useState<StatusType | 'All'>('All');
  const [filterWorker, setFilterWorker] = useState<string>('All');
  const [filterVehicle, setFilterVehicle] = useState<string>('All');

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '',
    customer: '',
    customerPhone: '',
    from: '',
    to: '',
    status: 'Pending',
    assignedWorkers: [],
    assignedVehicles: []
  });

  // Helper to open Google Maps
  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  // Filtering Logic
  const filteredTasks = useMemo(() => {
    return tasks.filter(task => {
      const statusMatch = filterStatus === 'All' || task.status === filterStatus;
      const workerMatch = filterWorker === 'All' || task.assignedWorkers.includes(filterWorker);
      const vehicleMatch = filterVehicle === 'All' || task.assignedVehicles.includes(filterVehicle);
      return statusMatch && workerMatch && vehicleMatch;
    });
  }, [tasks, filterStatus, filterWorker, filterVehicle]);

  // Timeline Constants
  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 80; // px

  // Calculate layout positions for tasks to handle overlaps
  const positionedTasks = useMemo(() => {
    const sorted = [...filteredTasks].sort((a, b) => a.start.getTime() - b.start.getTime());
    const columns: MoveTask[][] = [];

    sorted.forEach(task => {
      let placed = false;
      for (let i = 0; i < columns.length; i++) {
        const lastTaskInColumn = columns[i][columns[i].length - 1];
        if (task.start >= lastTaskInColumn.end) {
          columns[i].push(task);
          placed = true;
          break;
        }
      }
      if (!placed) {
        columns.push([task]);
      }
    });

    return columns.flatMap((column, colIndex) => 
      column.map(task => ({
        ...task,
        colIndex,
        totalCols: columns.length
      }))
    );
  }, [filteredTasks]);

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date();
    start.setMinutes(0);
    const end = new Date(start.getTime() + 2 * 60 * 60 * 1000);
    setCurrentTask({
      title: '',
      customer: '',
      customerPhone: '',
      from: '',
      to: '',
      status: 'Pending',
      start,
      end,
      assignedWorkers: [],
      assignedVehicles: []
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const handleSaveTask = () => {
    if (user.role !== 'admin') return;

    if (isEditing && currentTask.id) {
      setTasks(tasks.map(t => t.id === currentTask.id ? { ...t, ...currentTask } as MoveTask : t));
    } else {
      const id = Math.random().toString(36).substr(2, 9);
      const task: MoveTask = {
        ...(currentTask as MoveTask),
        id,
        start: currentTask.start || new Date(),
        end: currentTask.end || new Date(new Date().getTime() + 2 * 60 * 60 * 1000),
        assignedWorkers: currentTask.assignedWorkers || [],
        assignedVehicles: currentTask.assignedVehicles || []
      };
      setTasks([...tasks, task]);
    }
    setShowModal(false);
  };

  const toggleWorker = (id: string) => {
    if (user.role !== 'admin') return;
    const current = currentTask.assignedWorkers || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedWorkers: current.filter(wId => wId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedWorkers: [...current, id] });
    }
  };

  const toggleVehicle = (id: string) => {
    if (user.role !== 'admin') return;
    const current = currentTask.assignedVehicles || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedVehicles: current.filter(vId => vId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedVehicles: [...current, id] });
    }
  };

  const resetFilters = () => {
    setFilterStatus('All');
    setFilterWorker('All');
    setFilterVehicle('All');
  };

  const isFilterActive = filterStatus !== 'All' || filterWorker !== 'All' || filterVehicle !== 'All';

  // Helper for status colors
  const getStatusColorClass = (status: StatusType) => {
    switch(status) {
      case 'Completed': return 'bg-green-100 border-green-200 text-green-700';
      case 'In Progress': return 'bg-orange-100 border-orange-200 text-orange-700';
      case 'Confirmed': return 'bg-blue-100 border-blue-200 text-blue-700';
      default: return 'bg-slate-100 border-slate-200 text-slate-600';
    }
  };

  return (
    <div className="space-y-4">
      {/* Header with Filter Toggle */}
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-bold">Kalendář stěhování</h2>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-2 rounded-full transition-all border ${showFilters || isFilterActive ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-100 text-slate-400'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
          </button>
          {user.role === 'admin' && (
            <button 
              onClick={handleOpenCreate}
              className="bg-blue-600 text-white p-2 rounded-full shadow-lg hover:scale-105 transition-transform"
            >
              <Icons.Plus />
            </button>
          )}
        </div>
      </div>

      {/* Filter Bar */}
      {showFilters && (
        <div className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 space-y-4 animate-fade-in">
          <div className="flex flex-col gap-3">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Stav úkolu</label>
              <div className="flex flex-wrap gap-2">
                {(['All', 'Pending', 'Confirmed', 'In Progress', 'Completed'] as const).map(status => (
                  <button
                    key={status}
                    onClick={() => setFilterStatus(status)}
                    className={`px-3 py-1.5 rounded-full text-[10px] font-bold transition-all border ${filterStatus === status ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                  >
                    {status === 'All' ? 'Vše' : status === 'Pending' ? 'Čeká' : status === 'Confirmed' ? 'Potvrzeno' : status === 'In Progress' ? 'Probíhá' : 'Hotovo'}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pracovník</label>
                <select 
                  className="w-full bg-slate-50 border-none rounded-xl p-2.5 text-[11px] font-medium outline-none focus:ring-2 focus:ring-blue-600 transition-all"
                  value={filterWorker}
                  onChange={(e) => setFilterWorker(e.target.value)}
                >
                  <option value="All">Všichni</option>
                  {workers.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Vozidlo</label>
                <select 
                  className="w-full bg-slate-50 border-none rounded-xl p-2.5 text-[11px] font-medium outline-none focus:ring-2 focus:ring-blue-600 transition-all"
                  value={filterVehicle}
                  onChange={(e) => setFilterVehicle(e.target.value)}
                >
                  <option value="All">Všechna</option>
                  {vehicles.map(v => <option key={v.id} value={v.id}>{v.plate} ({v.model})</option>)}
                </select>
              </div>
            </div>

            {isFilterActive && (
              <button 
                onClick={resetFilters}
                className="text-[10px] font-black text-blue-600 uppercase tracking-widest hover:underline text-right"
              >
                Vymazat filtry
              </button>
            )}
          </div>
        </div>
      )}

      {/* Modern Day Timeline View */}
      <div className="bg-white rounded-[32px] shadow-sm border border-slate-100 overflow-hidden flex flex-col h-[600px]">
        {/* Days Header */}
        <div className="flex justify-between p-4 border-b border-slate-50">
          {['PO','ÚT','ST','ČT','PÁ','SO','NE'].map((day, i) => (
            <div key={i} className={`flex flex-col items-center gap-1 flex-1 ${i === 2 ? 'text-blue-600' : 'text-slate-400'}`}>
              <span className="text-[10px] font-bold uppercase tracking-wider">{day}</span>
              <span className={`w-8 h-8 flex items-center justify-center rounded-xl text-xs font-black ${i === 2 ? 'bg-blue-600 text-white shadow-lg' : ''}`}>
                {15 + i}
              </span>
            </div>
          ))}
        </div>

        {/* Scrollable Timeline */}
        <div className="flex-1 overflow-y-auto no-scrollbar relative p-4 pt-2">
          {/* Time Labels Column */}
          <div className="absolute left-4 top-2 bottom-0 w-10 z-10 pointer-events-none">
            {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
              <div 
                key={i} 
                className="text-[10px] font-bold text-slate-300 h-[80px]"
                style={{ height: `${HOUR_HEIGHT}px` }}
              >
                {String(START_HOUR + i).padStart(2, '0')}:00
              </div>
            ))}
          </div>

          {/* Grid Lines */}
          <div className="ml-12 relative h-full min-h-[1280px]">
            {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
              <div 
                key={i} 
                className="border-t border-slate-50 absolute w-full pointer-events-none"
                style={{ top: `${i * HOUR_HEIGHT}px` }}
              />
            ))}

            {/* Current Time Indicator (Static mock for now) */}
            <div className="absolute left-0 right-0 border-t-2 border-red-400 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
              <div className="w-2 h-2 rounded-full bg-red-400 -ml-1 shadow-sm" />
            </div>

            {/* Task Blocks */}
            {positionedTasks.map((task) => {
              const startDecimal = task.start.getHours() + task.start.getMinutes() / 60;
              const endDecimal = task.end.getHours() + task.end.getMinutes() / 60;
              const duration = Math.max(0.5, endDecimal - startDecimal);

              const top = (startDecimal - START_HOUR) * HOUR_HEIGHT;
              const height = duration * HOUR_HEIGHT;
              const width = 100 / task.totalCols;
              const left = task.colIndex * width;

              return (
                <div
                  key={task.id}
                  onClick={() => handleOpenEdit(task)}
                  className={`absolute p-1 transition-all cursor-pointer group z-20`}
                  style={{ 
                    top: `${top}px`, 
                    height: `${height}px`, 
                    left: `${left}%`, 
                    width: `${width}%` 
                  }}
                >
                  <div className={`h-full w-full rounded-2xl border-2 p-3 shadow-sm hover:shadow-md transition-all overflow-hidden flex flex-col ${getStatusColorClass(task.status)}`}>
                    <div className="flex justify-between items-start gap-1">
                      <h4 className="text-[11px] font-black leading-tight line-clamp-2">{task.title}</h4>
                      <span className="text-[9px] opacity-70 font-mono whitespace-nowrap">
                        {task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}
                      </span>
                    </div>

                    <div className="mt-1 flex-1 min-h-0">
                      <p className="text-[9px] opacity-70 font-bold truncate">{task.customer}</p>

                      <div className="flex flex-wrap gap-1 mt-2 items-center">
                        {/* Worker Icons Logic */}
                        {task.assignedWorkers.length <= 2 ? (
                          task.assignedWorkers.map(wId => (
                            <div key={wId} className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden">
                              <Icons.User />
                            </div>
                          ))
                        ) : (
                          <div className="flex items-center gap-0.5">
                            <div className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden">
                              <Icons.User />
                            </div>
                            <span className="text-[8px] font-black text-inherit">+{task.assignedWorkers.length - 1}</span>
                          </div>
                        )}

                        {/* Vehicle Icon */}
                        {task.assignedVehicles.length > 0 && (
                          <div className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden ml-0.5">
                            <Icons.Truck />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}

            {positionedTasks.length === 0 && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-300 pointer-events-none">
                <Icons.Calendar />
                <p className="text-xs font-bold uppercase tracking-widest mt-2">Žádné zakázky</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Task Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-t-[32px] sm:rounded-[32px] p-8 shadow-2xl animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-black text-slate-900">
                  {isEditing ? (user.role === 'admin' ? 'Upravit úkol' : 'Detail úkolu') : 'Nové stěhování'}
                </h3>
                <button onClick={() => setShowModal(false)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                </button>
            </div>

            <div className="space-y-6">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Název úkolu</label>
                  {user.role === 'admin' ? (
                    <input 
                      type="text" 
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-bold text-slate-800"
                      value={currentTask.title}
                      onChange={e => setCurrentTask({...currentTask, title: e.target.value})}
                    />
                  ) : (
                    <p className="p-4 bg-slate-50 rounded-2xl font-bold text-slate-800">{currentTask.title}</p>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Zákazník</label>
                    {user.role === 'admin' ? (
                      <input 
                        type="text" 
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-medium text-sm"
                        value={currentTask.customer}
                        onChange={e => setCurrentTask({...currentTask, customer: e.target.value})}
