                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Odkud</label>
                    {user.role === 'admin' ? (
                      <div className="relative group">
