import React, { useState } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
  user: {
    workerId?: string;
    role: 'admin' | 'user';
  };
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles, user }) => {
  const [selectedTask, setSelectedTask] = useState<MoveTask | null>(null);

  // Global stats remain company-wide
  const activeTasks = tasks.filter(t => t.status !== 'Completed');
  const availableWorkers = workers.filter(w => w.status === 'Available');
  const availableVehicles = vehicles.filter(v => v.status === 'Ready');

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  const isTomorrow = (date: Date) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return date.getDate() === tomorrow.getDate() &&
      date.getMonth() === tomorrow.getMonth() &&
      date.getFullYear() === tomorrow.getFullYear();
  };

  // Personalized filtering: show only tasks where the user is assigned
  // If user is admin but not linked to a worker, show all (for management purposes), 
  // but if linked, prioritize their own schedule as requested.
  const myTasks = user.workerId 
    ? tasks.filter(t => t.assignedWorkers.includes(user.workerId!))
    : (user.role === 'admin' ? tasks : []);

  const todayTasks = myTasks.filter(t => isToday(t.start));
  const tomorrowTasks = myTasks.filter(t => isTomorrow(t.start));

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const TaskCard = ({ task }: { task: MoveTask }) => (
    <div 
      onClick={() => setSelectedTask(task)}
      className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex items-center gap-4 hover:shadow-md transition-all cursor-pointer active:scale-[0.98]"
    >
      <div className="flex flex-col items-center justify-center bg-blue-50 rounded-2xl p-3 min-w-[70px]">
        <span className="text-blue-600 font-black text-lg">
          {task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}
        </span>
        <span className="text-[9px] font-bold text-blue-400 uppercase tracking-widest">START</span>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-bold text-slate-800 truncate">{task.title}</h3>
        <p className="text-xs text-slate-500 font-medium truncate">{task.customer}</p>
        <div className="flex items-center gap-2 mt-1">
          <span className="text-[10px] text-slate-400 font-bold truncate">
            {task.from} &rarr; {task.to}
          </span>
        </div>
      </div>

      <div className={`w-2 h-2 rounded-full ${
        task.status === 'Confirmed' ? 'bg-green-500' : 
        task.status === 'In Progress' ? 'bg-orange-500' : 'bg-slate-300'
      }`} />
    </div>
  );

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-3 gap-3">
        <StatCard label="Aktivní" value={activeTasks.length} color="blue" />
        <StatCard label="Lidé" value={availableWorkers.length} color="green" />
        <StatCard label="Auta" value={availableVehicles.length} color="orange" />
      </div>

      <section className="space-y-4">
        <div className="flex items-center justify-between px-2">
          <div className="flex items-center gap-2">
            <div className="w-1 h-5 bg-blue-600 rounded-full" />
            <h2 className="text-lg font-black text-slate-800 uppercase tracking-tight">Moje stěhování dnes</h2>
          </div>
          {user.workerId && <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded-lg">PERSONALIZOVÁNO</span>}
        </div>
        <div className="space-y-3">
          {todayTasks.length > 0 ? todayTasks.map(task => (
            <TaskCard key={task.id} task={task} />
          )) : (
            <div className="bg-slate-100/50 rounded-3xl p-6 text-center border border-dashed border-slate-200">
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Dnes nemáte žádné přiřazené plány</p>
            </div>
          )}
        </div>
      </section>

      <section className="space-y-4">
        <div className="flex items-center gap-2 px-2">
          <div className="w-1 h-5 bg-slate-400 rounded-full" />
          <h2 className="text-lg font-black text-slate-800 uppercase tracking-tight">Moje stěhování zítra</h2>
        </div>
        <div className="space-y-3">
          {tomorrowTasks.length > 0 ? tomorrowTasks.map(task => (
            <TaskCard key={task.id} task={task} />
          )) : (
            <div className="bg-slate-100/50 rounded-3xl p-6 text-center border border-dashed border-slate-200">
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Zítra jste bez zakázek</p>
            </div>
          )}
        </div>
      </section>

      {/* Quick Task Detail Modal */}
      {selectedTask && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4" onClick={() => setSelectedTask(null)}>
          <div 
            className="bg-white w-full max-w-md rounded-t-[40px] sm:rounded-[40px] p-8 shadow-2xl animate-slide-up"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex justify-between items-start mb-6">
              <div>
                <span className={`text-[10px] font-black uppercase tracking-[0.2em] px-3 py-1 rounded-full mb-2 inline-block ${
                  selectedTask.status === 'Confirmed' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'
                }`}>
                  {selectedTask.status}
                </span>
                <h3 className="text-2xl font-black text-slate-900">{selectedTask.title}</h3>
              </div>
              <button onClick={() => setSelectedTask(null)} className="bg-slate-100 p-2 rounded-2xl hover:bg-slate-200 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>

            <div className="space-y-6">
              <div className="flex items-center justify-between bg-slate-50 p-4 rounded-3xl">
                <div className="flex-1">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Zákazník</p>
                  <p className="font-bold text-slate-800 leading-tight">{selectedTask.customer}</p>
                  {selectedTask.customerPhone && (
                    <a 
                      href={`tel:${selectedTask.customerPhone.replace(/\s+/g, '')}`}
                      className="text-xs text-blue-600 font-bold hover:underline inline-flex items-center gap-1 mt-1"
                    >
                      <span className="scale-75"><Icons.Phone /></span>
                      {selectedTask.customerPhone}
                    </a>
                  )}
                </div>
                {selectedTask.customerPhone && (
                  <a href={`tel:${selectedTask.customerPhone.replace(/\s+/g, '')}`} className="bg-blue-600 text-white p-4 rounded-2xl shadow-lg shadow-blue-100 active:scale-95 transition-all">
                    <Icons.Phone />
                  </a>
                )}
              </div>

              <div className="grid grid-cols-2 gap-3">
                <button onClick={() => handleOpenMaps(selectedTask.from)} className="bg-white border border-slate-100 p-5 rounded-3xl text-left hover:bg-slate-50 transition-all active:scale-95">
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-2">ODKUD</p>
                  <p className="text-xs font-bold text-slate-800 line-clamp-1">{selectedTask.from}</p>
                </button>
                <button onClick={() => handleOpenMaps(selectedTask.to)} className="bg-white border border-slate-100 p-5 rounded-3xl text-left hover:bg-slate-50 transition-all active:scale-95">
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-2">KAM</p>
                  <p className="text-xs font-bold text-slate-800 line-clamp-1">{selectedTask.to}</p>
                </button>
              </div>

              <div className="flex items-center gap-3 p-4 border-2 border-dashed border-slate-100 rounded-3xl">
                <div className="w-10 h-10 bg-blue-50 rounded-2xl flex items-center justify-center text-blue-600">
                  <Icons.Calendar />
                </div>
                <div>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">ČASOVÝ RÁMEC</p>
                  <p className="text-sm font-black text-slate-800">
                    {selectedTask.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} 
                    {' - '} 
                    {selectedTask.end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                </div>
              </div>

              <button 
                onClick={() => setSelectedTask(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-3xl shadow-xl transition-all active:scale-95 mt-2"
              >
                ROZUMÍM
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard = ({ label, value, color }: { label: string, value: number, color: 'blue' | 'green' | 'orange' }) => {
  const colorMap = {
    blue: 'bg-blue-50 text-blue-600 border-blue-100',
    green: 'bg-green-50 text-green-600 border-green-100',
    orange: 'bg-orange-50 text-orange-600 border-orange-100'
  };

  return (
    <div className={`p-5 rounded-[2.5rem] ${colorMap[color]} border flex flex-col items-center text-center shadow-sm`}>
      <span className="text-2xl font-black mb-0.5">{value}</span>
      <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{label}</span>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type StatusType = MoveTask['status'];

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // States for filtering
  const [showFilters, setShowFilters] = useState(false);
  const [filterStatus, setFilterStatus] = useState<StatusType | 'All'>('All');
  const [filterWorker, setFilterWorker] = useState<string>('All');
  const [filterVehicle, setFilterVehicle] = useState<string>('All');

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '',
    customer: '',
    customerPhone: '',
    from: '',
    to: '',
    status: 'Pending',
    assignedWorkers: [],
    assignedVehicles: []
  });

  // Helper to open Google Maps
  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  // Filtering Logic
  const filteredTasks = useMemo(() => {
    return tasks.filter(task => {
      const statusMatch = filterStatus === 'All' || task.status === filterStatus;
      const workerMatch = filterWorker === 'All' || task.assignedWorkers.includes(filterWorker);
      const vehicleMatch = filterVehicle === 'All' || task.assignedVehicles.includes(filterVehicle);
      return statusMatch && workerMatch && vehicleMatch;
    });
  }, [tasks, filterStatus, filterWorker, filterVehicle]);

  // Timeline Constants
  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 80; // px

  // Calculate layout positions for tasks to handle overlaps
  const positionedTasks = useMemo(() => {
    const sorted = [...filteredTasks].sort((a, b) => a.start.getTime() - b.start.getTime());
    const columns: MoveTask[][] = [];

    sorted.forEach(task => {
      let placed = false;
      for (let i = 0; i < columns.length; i++) {
        const lastTaskInColumn = columns[i][columns[i].length - 1];
        if (task.start >= lastTaskInColumn.end) {
          columns[i].push(task);
          placed = true;
          break;
        }
      }
      if (!placed) {
        columns.push([task]);
      }
    });

    return columns.flatMap((column, colIndex) => 
      column.map(task => ({
        ...task,
        colIndex,
        totalCols: columns.length
      }))
    );
  }, [filteredTasks]);

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date();
    start.setMinutes(0);
    const end = new Date(start.getTime() + 2 * 60 * 60 * 1000);
    setCurrentTask({
      title: '',
      customer: '',
      customerPhone: '',
      from: '',
      to: '',
      status: 'Pending',
      start,
      end,
      assignedWorkers: [],
      assignedVehicles: []
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const handleSaveTask = () => {
    if (user.role !== 'admin') return;

    if (isEditing && currentTask.id) {
      setTasks(tasks.map(t => t.id === currentTask.id ? { ...t, ...currentTask } as MoveTask : t));
    } else {
      const id = Math.random().toString(36).substr(2, 9);
      const task: MoveTask = {
        ...(currentTask as MoveTask),
        id,
        start: currentTask.start || new Date(),
        end: currentTask.end || new Date(new Date().getTime() + 2 * 60 * 60 * 1000),
        assignedWorkers: currentTask.assignedWorkers || [],
        assignedVehicles: currentTask.assignedVehicles || []
      };
      setTasks([...tasks, task]);
    }
    setShowModal(false);
  };

  const toggleWorker = (id: string) => {
    if (user.role !== 'admin') return;
    const current = currentTask.assignedWorkers || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedWorkers: current.filter(wId => wId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedWorkers: [...current, id] });
    }
  };

  const toggleVehicle = (id: string) => {
    if (user.role !== 'admin') return;
    const current = currentTask.assignedVehicles || [];
    if (current.includes(id)) {
      setCurrentTask({ ...currentTask, assignedVehicles: current.filter(vId => vId !== id) });
    } else {
      setCurrentTask({ ...currentTask, assignedVehicles: [...current, id] });
    }
  };

  const resetFilters = () => {
    setFilterStatus('All');
    setFilterWorker('All');
    setFilterVehicle('All');
  };

  const isFilterActive = filterStatus !== 'All' || filterWorker !== 'All' || filterVehicle !== 'All';

  // Helper for status colors
  const getStatusColorClass = (status: StatusType) => {
    switch(status) {
      case 'Completed': return 'bg-green-100 border-green-200 text-green-700';
      case 'In Progress': return 'bg-orange-100 border-orange-200 text-orange-700';
      case 'Confirmed': return 'bg-blue-100 border-blue-200 text-blue-700';
      default: return 'bg-slate-100 border-slate-200 text-slate-600';
    }
  };

  return (
    <div className="space-y-4">
      {/* Header with Filter Toggle */}
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-bold">Kalendář stěhování</h2>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`p-2 rounded-full transition-all border ${showFilters || isFilterActive ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-100 text-slate-400'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
          </button>
          {user.role === 'admin' && (
            <button 
              onClick={handleOpenCreate}
              className="bg-blue-600 text-white p-2 rounded-full shadow-lg hover:scale-105 transition-transform"
            >
              <Icons.Plus />
            </button>
          )}
        </div>
      </div>

      {/* Filter Bar */}
      {showFilters && (
        <div className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 space-y-4 animate-fade-in">
          <div className="flex flex-col gap-3">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Stav úkolu</label>
              <div className="flex flex-wrap gap-2">
                {(['All', 'Pending', 'Confirmed', 'In Progress', 'Completed'] as const).map(status => (
                  <button
                    key={status}
                    onClick={() => setFilterStatus(status)}
                    className={`px-3 py-1.5 rounded-full text-[10px] font-bold transition-all border ${filterStatus === status ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                  >
                    {status === 'All' ? 'Vše' : status === 'Pending' ? 'Čeká' : status === 'Confirmed' ? 'Potvrzeno' : status === 'In Progress' ? 'Probíhá' : 'Hotovo'}
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pracovník</label>
                <select 
                  className="w-full bg-slate-50 border-none rounded-xl p-2.5 text-[11px] font-medium outline-none focus:ring-2 focus:ring-blue-600 transition-all"
                  value={filterWorker}
                  onChange={(e) => setFilterWorker(e.target.value)}
                >
                  <option value="All">Všichni</option>
                  {workers.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Vozidlo</label>
                <select 
                  className="w-full bg-slate-50 border-none rounded-xl p-2.5 text-[11px] font-medium outline-none focus:ring-2 focus:ring-blue-600 transition-all"
                  value={filterVehicle}
                  onChange={(e) => setFilterVehicle(e.target.value)}
                >
                  <option value="All">Všechna</option>
                  {vehicles.map(v => <option key={v.id} value={v.id}>{v.plate} ({v.model})</option>)}
                </select>
              </div>
            </div>

            {isFilterActive && (
              <button 
                onClick={resetFilters}
                className="text-[10px] font-black text-blue-600 uppercase tracking-widest hover:underline text-right"
              >
                Vymazat filtry
              </button>
            )}
          </div>
        </div>
      )}

      {/* Modern Day Timeline View */}
      <div className="bg-white rounded-[32px] shadow-sm border border-slate-100 overflow-hidden flex flex-col h-[600px]">
        {/* Days Header */}
        <div className="flex justify-between p-4 border-b border-slate-50">
          {['PO','ÚT','ST','ČT','PÁ','SO','NE'].map((day, i) => (
            <div key={i} className={`flex flex-col items-center gap-1 flex-1 ${i === 2 ? 'text-blue-600' : 'text-slate-400'}`}>
              <span className="text-[10px] font-bold uppercase tracking-wider">{day}</span>
              <span className={`w-8 h-8 flex items-center justify-center rounded-xl text-xs font-black ${i === 2 ? 'bg-blue-600 text-white shadow-lg' : ''}`}>
                {15 + i}
              </span>
            </div>
          ))}
        </div>

        {/* Scrollable Timeline */}
        <div className="flex-1 overflow-y-auto no-scrollbar relative p-4 pt-2">
          {/* Time Labels Column */}
          <div className="absolute left-4 top-2 bottom-0 w-10 z-10 pointer-events-none">
            {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
              <div 
                key={i} 
                className="text-[10px] font-bold text-slate-300 h-[80px]"
                style={{ height: `${HOUR_HEIGHT}px` }}
              >
                {String(START_HOUR + i).padStart(2, '0')}:00
              </div>
            ))}
          </div>

          {/* Grid Lines */}
          <div className="ml-12 relative h-full min-h-[1280px]">
            {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
              <div 
                key={i} 
                className="border-t border-slate-50 absolute w-full pointer-events-none"
                style={{ top: `${i * HOUR_HEIGHT}px` }}
              />
            ))}

            {/* Current Time Indicator (Static mock for now) */}
            <div className="absolute left-0 right-0 border-t-2 border-red-400 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
              <div className="w-2 h-2 rounded-full bg-red-400 -ml-1 shadow-sm" />
            </div>

            {/* Task Blocks */}
            {positionedTasks.map((task) => {
              const startDecimal = task.start.getHours() + task.start.getMinutes() / 60;
              const endDecimal = task.end.getHours() + task.end.getMinutes() / 60;
              const duration = Math.max(0.5, endDecimal - startDecimal);

              const top = (startDecimal - START_HOUR) * HOUR_HEIGHT;
              const height = duration * HOUR_HEIGHT;
              const width = 100 / task.totalCols;
              const left = task.colIndex * width;

              return (
                <div
                  key={task.id}
                  onClick={() => handleOpenEdit(task)}
                  className={`absolute p-1 transition-all cursor-pointer group z-20`}
                  style={{ 
                    top: `${top}px`, 
                    height: `${height}px`, 
                    left: `${left}%`, 
                    width: `${width}%` 
                  }}
                >
                  <div className={`h-full w-full rounded-2xl border-2 p-3 shadow-sm hover:shadow-md transition-all overflow-hidden flex flex-col ${getStatusColorClass(task.status)}`}>
                    <div className="flex justify-between items-start gap-1">
                      <h4 className="text-[11px] font-black leading-tight line-clamp-2">{task.title}</h4>
                      <span className="text-[9px] opacity-70 font-mono whitespace-nowrap">
                        {task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}
                      </span>
                    </div>

                    <div className="mt-1 flex-1 min-h-0">
                      <p className="text-[9px] opacity-70 font-bold truncate">{task.customer}</p>

                      <div className="flex flex-wrap gap-1 mt-2 items-center">
                        {/* Worker Icons Logic */}
                        {task.assignedWorkers.length <= 2 ? (
                          task.assignedWorkers.map(wId => (
                            <div key={wId} className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden">
                              <Icons.User />
                            </div>
                          ))
                        ) : (
                          <div className="flex items-center gap-0.5">
                            <div className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden">
                              <Icons.User />
                            </div>
                            <span className="text-[8px] font-black text-inherit">+{task.assignedWorkers.length - 1}</span>
                          </div>
                        )}

                        {/* Vehicle Icon */}
                        {task.assignedVehicles.length > 0 && (
                          <div className="w-4 h-4 rounded-full bg-white/40 flex items-center justify-center scale-75 overflow-hidden ml-0.5">
                            <Icons.Truck />
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}

            {positionedTasks.length === 0 && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-300 pointer-events-none">
                <Icons.Calendar />
                <p className="text-xs font-bold uppercase tracking-widest mt-2">Žádné zakázky</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Task Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-t-[32px] sm:rounded-[32px] p-8 shadow-2xl animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-black text-slate-900">
                  {isEditing ? (user.role === 'admin' ? 'Upravit úkol' : 'Detail úkolu') : 'Nové stěhování'}
                </h3>
                <button onClick={() => setShowModal(false)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                </button>
            </div>

            <div className="space-y-6">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Název úkolu</label>
                  {user.role === 'admin' ? (
                    <input 
                      type="text" 
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-bold text-slate-800"
                      value={currentTask.title}
                      onChange={e => setCurrentTask({...currentTask, title: e.target.value})}
                    />
                  ) : (
                    <p className="p-4 bg-slate-50 rounded-2xl font-bold text-slate-800">{currentTask.title}</p>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Zákazník</label>
                    {user.role === 'admin' ? (
                      <input 
                        type="text" 
                        className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-medium text-sm"
                        value={currentTask.customer}
                        onChange={e => setCurrentTask({...currentTask, customer: e.target.value})}
                      />
                    ) : (
                      <p className="p-4 bg-slate-50 rounded-2xl font-medium text-slate-700 text-sm">{currentTask.customer}</p>
                    )}
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Telefon</label>
                    {user.role === 'admin' ? (
                      <div className="relative group">
                        <input 
                          type="tel" 
                          className="w-full bg-slate-100 border-none rounded-2xl p-4 pr-10 focus:ring-2 focus:ring-blue-600 outline-none font-medium text-sm"
                          value={currentTask.customerPhone}
                          onChange={e => setCurrentTask({...currentTask, customerPhone: e.target.value})}
                        />
                        {currentTask.customerPhone && (
                          <a 
                            href={`tel:${currentTask.customerPhone.replace(/\s+/g, '')}`}
                            className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-300 hover:text-blue-600 transition-colors"
                            title="Zavolat"
                          >
                            <Icons.Phone />
                          </a>
                        )}
                      </div>
                    ) : (
                      <a 
                        href={`tel:${currentTask.customerPhone?.replace(/\s+/g, '')}`}
                        className="p-4 bg-blue-50 rounded-2xl font-bold text-blue-600 text-sm flex items-center gap-2 group hover:bg-blue-100 transition-colors"
                      >
                        <Icons.Phone />
                        {currentTask.customerPhone}
                      </a>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Odkud</label>
                    {user.role === 'admin' ? (
                      <div className="relative group">
                        <input 
                          type="text" 
                          className="w-full bg-slate-100 border-none rounded-2xl p-4 pr-10 focus:ring-2 focus:ring-blue-600 outline-none text-sm"
                          value={currentTask.from}
                          onChange={e => setCurrentTask({...currentTask, from: e.target.value})}
                        />
                        <button 
                          onClick={() => handleOpenMaps(currentTask.from)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-300 hover:text-blue-600 transition-colors"
                          title="Zobrazit na mapě"
                        >
                          <Icons.Map />
                        </button>
                      </div>
                    ) : (
                      <button 
                        onClick={() => handleOpenMaps(currentTask.from)}
                        className="w-full p-4 bg-slate-50 rounded-2xl text-left hover:bg-blue-50 group transition-all"
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-sm font-medium text-slate-700 truncate">{currentTask.from || '---'}</span>
                          <div className="text-slate-300 group-hover:text-blue-500 transition-colors">
                            <Icons.Map />
                          </div>
                        </div>
                      </button>
                    )}
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Kam</label>
                    {user.role === 'admin' ? (
                      <div className="relative group">
                        <input 
                          type="text" 
                          className="w-full bg-slate-100 border-none rounded-2xl p-4 pr-10 focus:ring-2 focus:ring-blue-600 outline-none text-sm"
                          value={currentTask.to}
                          onChange={e => setCurrentTask({...currentTask, to: e.target.value})}
                        />
                        <button 
                          onClick={() => handleOpenMaps(currentTask.to)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-300 hover:text-blue-600 transition-colors"
                          title="Zobrazit na mapě"
                        >
                          <Icons.Map />
                        </button>
                      </div>
                    ) : (
                      <button 
                        onClick={() => handleOpenMaps(currentTask.to)}
                        className="w-full p-4 bg-slate-50 rounded-2xl text-left hover:bg-blue-50 group transition-all"
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-sm font-medium text-slate-700 truncate">{currentTask.to || '---'}</span>
                          <div className="text-slate-300 group-hover:text-blue-500 transition-colors">
                            <Icons.Map />
                          </div>
                        </div>
                      </button>
                    )}
                  </div>
                </div>

                {user.role === 'admin' && (
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Stav</label>
                    <div className="flex gap-2 flex-wrap">
                      {(['Pending', 'Confirmed', 'In Progress', 'Completed'] as const).map(s => (
                        <button
                          key={s}
                          onClick={() => setCurrentTask({...currentTask, status: s})}
                          className={`px-3 py-1.5 rounded-full text-[10px] font-bold transition-all border ${currentTask.status === s ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Assignments Section */}
              <div className="space-y-6 pt-4 border-t border-slate-100">
                {/* Workers Section */}
                <div className="space-y-3">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pracovníci</label>
                  <div className="grid grid-cols-1 gap-2">
                    {workers.map(worker => {
                      const isSelected = currentTask.assignedWorkers?.includes(worker.id);
                      if (user.role !== 'admin' && !isSelected) return null;
                      return (
                        <button
                          key={worker.id}
                          disabled={user.role !== 'admin'}
                          onClick={() => toggleWorker(worker.id)}
                          className={`flex items-center justify-between p-4 rounded-2xl border transition-all text-left ${
                            isSelected ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-100'
                          }`}
                        >
                          <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isSelected ? 'bg-blue-100' : 'bg-slate-100'}`}>
                              <Icons.User />
                            </div>
                            <span className="text-xs font-bold">{worker.name}</span>
                          </div>
                          {isSelected && <div className="w-4 h-4 rounded-full bg-blue-600 flex items-center justify-center"><svg width="8" height="8" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="4"><polyline points="20 6 9 17 4 12"/></svg></div>}
                        </button>
                      );
                    })}
                  </div>
                </div>

                {/* Vehicles Section */}
                <div className="space-y-3 pt-2">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Vozidla</label>
                  <div className="grid grid-cols-1 gap-2">
                    {vehicles.map(vehicle => {
                      const isSelected = currentTask.assignedVehicles?.includes(vehicle.id);
                      if (user.role !== 'admin' && !isSelected) return null;
                      return (
                        <button
                          key={vehicle.id}
                          disabled={user.role !== 'admin'}
                          onClick={() => toggleVehicle(vehicle.id)}
                          className={`flex items-center justify-between p-4 rounded-2xl border transition-all text-left ${
                            isSelected ? 'bg-orange-50 border-orange-200 text-orange-700' : 'bg-white border-slate-100'
                          }`}
                        >
                          <div className="flex items-center gap-3">
                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isSelected ? 'bg-orange-100' : 'bg-slate-100'}`}>
                              <Icons.Truck />
                            </div>
                            <div>
                              <p className="text-xs font-bold">{vehicle.plate}</p>
                              <p className="text-[10px] opacity-70 font-medium">{vehicle.model}</p>
                            </div>
                          </div>
                          {isSelected && <div className="w-4 h-4 rounded-full bg-orange-600 flex items-center justify-center"><svg width="8" height="8" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="4"><polyline points="20 6 9 17 4 12"/></svg></div>}
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>

              {user.role === 'admin' ? (
                <button 
                  onClick={handleSaveTask}
                  className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl mt-4 shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
                >
                  {isEditing ? 'Uložit změny' : 'Vytvořit úkol'}
                </button>
              ) : (
                <button 
                  onClick={() => setShowModal(false)}
                  className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl mt-4"
                >
                  Zavřít
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useRef } from 'react';
import { Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface FleetViewProps {
  workers: Worker[];
  setWorkers: React.Dispatch<React.SetStateAction<Worker[]>>;
  vehicles: Vehicle[];
  setVehicles: React.Dispatch<React.SetStateAction<Vehicle[]>>;
}

const FleetView: React.FC<FleetViewProps> = ({ workers, setWorkers, vehicles, setVehicles }) => {
  const [activeSubTab, setActiveSubTab] = useState<'workers' | 'vehicles'>('workers');

  // Modals state
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [selectedVehicle, setSelectedVehicle] = useState<Partial<Vehicle> | null>(null);

  const [showWorkerModal, setShowWorkerModal] = useState(false);
  const [selectedWorker, setSelectedWorker] = useState<Partial<Worker> | null>(null);

  const carImageRef = useRef<HTMLInputElement>(null);
  const techCertImageRef = useRef<HTMLInputElement>(null);
  const workerPhotoRef = useRef<HTMLInputElement>(null);

  const getRoleLabel = (role: string) => {
    switch(role) {
      case 'Driver': return 'Řidič';
      case 'Loader': return 'Stěhovák';
      case 'Specialist': return 'Specialista';
      default: return role;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'Available': return 'Volný';
      case 'On Task': return 'Na zakázce';
      case 'Off': return 'Mimo službu';
      case 'Ready': return 'Připraveno';
      case 'In Use': return 'V provozu';
      case 'Maintenance': return 'V servisu';
      default: return status;
    }
  };

  // Workers handlers
  const handleOpenWorkerDetail = (worker: Worker) => {
    setSelectedWorker({ ...worker });
    setShowWorkerModal(true);
  };

  const handleAddWorker = () => {
    setSelectedWorker({
      name: '',
      email: '',
      phone: '',
      role: 'Loader',
      status: 'Available',
      licenseInfo: '',
      photo: ''
    });
    setShowWorkerModal(true);
  };

  const handleSaveWorker = () => {
    if (!selectedWorker) return;

    if (selectedWorker.id) {
      setWorkers(workers.map(w => w.id === selectedWorker.id ? selectedWorker as Worker : w));
    } else {
      const newWorker: Worker = {
        ...selectedWorker as Worker,
        id: Math.random().toString(36).substr(2, 9)
      };
      setWorkers([...workers, newWorker]);
    }
    setShowWorkerModal(false);
  };

  const handleWorkerPhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedWorker(prev => prev ? { ...prev, photo: reader.result as string } : null);
      };
      reader.readAsDataURL(file);
    }
  };

  // Vehicle handlers
  const handleOpenVehicleDetail = (vehicle: Vehicle) => {
    setSelectedVehicle({ ...vehicle });
    setShowVehicleModal(true);
  };

  const handleAddVehicle = () => {
    setSelectedVehicle({
      plate: '',
      model: '',
      capacity: '',
      status: 'Ready',
      vin: '',
      stkExpiration: '',
      vignetteExpiration: '',
      insuranceInfo: ''
    });
    setShowVehicleModal(true);
  };

  const handleSaveVehicle = () => {
    if (!selectedVehicle) return;

    if (selectedVehicle.id) {
      setVehicles(vehicles.map(v => v.id === selectedVehicle.id ? selectedVehicle as Vehicle : v));
    } else {
      const newVehicle: Vehicle = {
        ...selectedVehicle as Vehicle,
        id: Math.random().toString(36).substr(2, 9)
      };
      setVehicles([...vehicles, newVehicle]);
    }
    setShowVehicleModal(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, field: 'carImage' | 'techCertImage') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedVehicle(prev => prev ? { ...prev, [field]: reader.result as string } : null);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-200 p-1 rounded-2xl flex shadow-inner">
        <button 
          onClick={() => setActiveSubTab('workers')}
          className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${activeSubTab === 'workers' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
        >
          Pracovníci
        </button>
        <button 
          onClick={() => setActiveSubTab('vehicles')}
          className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${activeSubTab === 'vehicles' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
        >
          Vozidla
        </button>
      </div>

      <div className="space-y-3">
        {activeSubTab === 'workers' ? (
          workers.map(worker => (
            <div 
              key={worker.id} 
              onClick={() => handleOpenWorkerDetail(worker)}
              className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center gap-4 hover:shadow-md transition-all cursor-pointer group"
            >
              <div className="w-12 h-12 bg-blue-50 rounded-full flex items-center justify-center text-blue-600 shadow-sm overflow-hidden border border-blue-100">
                {worker.photo ? (
                  <img src={worker.photo} className="w-full h-full object-cover" alt={worker.name} />
                ) : (
                  <Icons.User />
                )}
              </div>
              <div className="flex-1">
                <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{worker.name}</h4>
                <div className="flex items-center gap-2">
                  <p className="text-xs text-slate-500">{getRoleLabel(worker.role)} •</p>
                  <a 
                    href={`tel:${worker.phone.replace(/\s+/g, '')}`} 
                    onClick={(e) => e.stopPropagation()}
                    className="text-xs text-blue-600 font-bold hover:underline"
                  >
                    {worker.phone}
                  </a>
                </div>
                {worker.email && <p className="text-[9px] text-slate-400 font-medium truncate">{worker.email}</p>}
              </div>
              <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-tight ${
                worker.status === 'Available' ? 'bg-green-50 text-green-600' : 'bg-orange-50 text-orange-600'
              }`}>
                {getStatusLabel(worker.status)}
              </span>
            </div>
          ))
        ) : (
          vehicles.map(vehicle => (
            <div 
              key={vehicle.id} 
              onClick={() => handleOpenVehicleDetail(vehicle)}
              className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center gap-4 hover:shadow-md transition-all cursor-pointer group"
            >
              <div className="w-12 h-12 bg-orange-50 rounded-full overflow-hidden flex items-center justify-center text-orange-600 shadow-sm border border-orange-100">
                {vehicle.carImage ? (
                  <img src={vehicle.carImage} className="w-full h-full object-cover" alt="Car" />
                ) : (
                  <Icons.Truck />
                )}
              </div>
              <div className="flex-1">
                <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{vehicle.plate}</h4>
                <p className="text-xs text-slate-500">{vehicle.model} • {vehicle.capacity}</p>
                {vehicle.stkExpiration && (
                  <p className="text-[9px] text-slate-400 mt-1 font-bold uppercase">STK: {new Date(vehicle.stkExpiration).toLocaleDateString()}</p>
                )}
              </div>
              <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-tight ${
                vehicle.status === 'Ready' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'
              }`}>
                {getStatusLabel(vehicle.status)}
              </span>
            </div>
          ))
        )}
      </div>

      <button 
        onClick={activeSubTab === 'workers' ? handleAddWorker : handleAddVehicle}
        className="w-full border-2 border-dashed border-slate-200 py-4 rounded-2xl flex items-center justify-center gap-2 text-slate-400 font-bold hover:bg-slate-50 hover:border-slate-300 transition-all active:scale-[0.98]"
      >
        <Icons.Plus />
        Přidat {activeSubTab === 'workers' ? 'pracovníka' : 'vozidlo'}
      </button>

      {/* Worker Detail / Edit Modal */}
      {showWorkerModal && selectedWorker && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-t-[32px] sm:rounded-[32px] p-8 shadow-2xl animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-2xl font-black text-slate-900">{selectedWorker.id ? 'Detail pracovníka' : 'Nový pracovník'}</h3>
              <button onClick={() => setShowWorkerModal(false)} className="p-2 text-slate-400 hover:text-slate-600">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>

            <div className="space-y-5">
              <div className="flex justify-center mb-6">
                <div 
                  onClick={() => workerPhotoRef.current?.click()}
                  className="w-32 h-32 bg-slate-100 rounded-[40px] border-4 border-white shadow-xl overflow-hidden relative group cursor-pointer"
                >
                  {selectedWorker.photo ? (
                    <>
                      <img src={selectedWorker.photo} className="w-full h-full object-cover" alt="Profile" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white text-[10px] font-bold">ZMĚNIT</div>
                    </>
                  ) : (
                    <div className="flex flex-col items-center justify-center h-full gap-2 text-slate-300">
                      <Icons.User />
                      <span className="text-[8px] font-black uppercase">FOTOGRAFIE</span>
                    </div>
                  )}
                </div>
                <input type="file" ref={workerPhotoRef} hidden accept="image/*" onChange={handleWorkerPhotoUpload} />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Jméno a příjmení</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none font-bold text-slate-800"
                  value={selectedWorker.name}
                  onChange={e => setSelectedWorker({...selectedWorker, name: e.target.value})}
                  placeholder="např. Jan Novák"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Email (pro propojení s účtem)</label>
                <input 
                  type="email" 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none text-sm"
                  value={selectedWorker.email}
                  onChange={e => setSelectedWorker({...selectedWorker, email: e.target.value})}
                  placeholder="uzivatel@email.cz"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Telefon</label>
                  <div className="relative group">
                    <input 
                      type="tel" 
                      className="w-full bg-slate-100 border-none rounded-2xl p-4 pr-10 focus:ring-2 focus:ring-blue-600 outline-none text-sm"
                      value={selectedWorker.phone}
                      onChange={e => setSelectedWorker({...selectedWorker, phone: e.target.value})}
                      placeholder="+420..."
                    />
                    {selectedWorker.phone && (
                      <a 
                        href={`tel:${selectedWorker.phone.replace(/\s+/g, '')}`}
                        className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-300 hover:text-blue-600 transition-colors"
                        title="Zavolat"
                      >
                        <Icons.Phone />
                      </a>
                    )}
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pozice</label>
                  <select 
                    className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none text-sm appearance-none"
                    value={selectedWorker.role}
                    onChange={e => setSelectedWorker({...selectedWorker, role: e.target.value as any})}
                  >
                    <option value="Driver">Řidič</option>
                    <option value="Loader">Stěhovák</option>
                    <option value="Specialist">Specialista</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Řidičský průkaz (Skupiny)</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none text-sm font-bold"
                  value={selectedWorker.licenseInfo}
                  onChange={e => setSelectedWorker({...selectedWorker, licenseInfo: e.target.value})}
                  placeholder="např. B, C, C1"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Stav dostupnosti</label>
                <div className="flex gap-2">
                  {(['Available', 'On Task', 'Off'] as const).map(status => (
                    <button
                      key={status}
                      onClick={() => setSelectedWorker({...selectedWorker, status})}
                      className={`flex-1 py-3 rounded-xl text-[10px] font-bold transition-all border ${
                        selectedWorker.status === status 
                        ? 'bg-blue-600 border-blue-600 text-white shadow-md' 
                        : 'bg-slate-50 border-slate-100 text-slate-400'
                      }`}
                    >
                      {getStatusLabel(status)}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={handleSaveWorker}
                className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl mt-4 shadow-xl shadow-blue-100 hover:bg-blue-700 transition-colors active:scale-[0.98]"
              >
                Uložit zaměstnance
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicle Detail / Edit Modal */}
      {showVehicleModal && selectedVehicle && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-t-[32px] sm:rounded-[32px] p-8 shadow-2xl animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
