              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Pojišťovna / Info</label>
                <textarea 
                  className="w-full bg-slate-100 border-none rounded-2xl p-4 focus:ring-2 focus:ring-blue-600 outline-none text-sm min-h-[80px]"
