          className="bg-blue-900 text-white font-bold py-4 px-8 rounded-2xl flex items-center gap-3 shadow-xl hover:bg-blue-800 transition-all w-full max-w-xs justify-center active:scale-95"
        >
          <img src="https://www.google.com/favicon.ico" className="w-5 h-5 brightness-150" alt="Google" />
          Přihlásit se přes Google
        </button>
        <p className="mt-8 text-[10px] text-slate-300 font-bold uppercase tracking-[0.3em]">Premium Logistics System</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col max-w-md mx-auto shadow-2xl overflow-hidden relative border-x border-slate-200">
      {/* Premium Header */}
      <header className="bg-white/90 backdrop-blur-lg border-b border-slate-100 p-5 sticky top-0 z-20 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-900 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-900/20">
            <Icons.Truck />
          </div>
          <div>
            <h1 className="text-lg font-black text-slate-900 leading-none">Stěhovák <span className="text-red-600">2.0</span></h1>
            <p className="text-[9px] text-red-600 font-black tracking-widest mt-0.5">{getTabLabel(activeTab)}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-2xl overflow-hidden border-2 border-white shadow-md">
            <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
        {/* Czech Flag Accent Line */}
        <div className="absolute bottom-0 left-0 w-full h-[2px] flex">
          <div className="h-full w-1/3 bg-blue-900"></div>
          <div className="h-full w-1/3 bg-white"></div>
          <div className="h-full w-1/3 bg-red-600"></div>
