        </button>
      </div>

      {/* Main Calendar Container */}
      <div className="bg-white rounded-[3rem] shadow-sm border border-slate-100 overflow-hidden flex flex-col h-[600px]">
        {viewMode === 'day' && renderDayView()}
        {viewMode !== 'day' && (
          <div className="flex-1 flex flex-col items-center justify-center p-10 text-center text-slate-300">
             <div className="scale-150 mb-5 opacity-20"><Icons.Calendar /></div>
             <p className="text-xs font-black uppercase tracking-widest">Detailní pohledy ve vývoji</p>
          </div>
        )}
      </div>
    </div>
  );
};

