import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

// Fixed: Correct SDK initialization following guidelines
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  /**
   * Thinking mode for complex queries (Gemini 3 Pro)
   */
  async thinkComplex(prompt: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });
    return response.text || "No response generated.";
  },

  /**
   * Analyze images (Gemini 3 Pro)
   */
  async analyzeImage(imagePrompt: string, base64Image: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: imagePrompt }
        ]
      }
    });
    return response.text || "Could not analyze image.";
  },

  /**
   * Generate images (Gemini 3 Pro Image)
   */
  async generateImage(prompt: string, size: '1K' | '2K' | '4K'): Promise<string | null> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        imageConfig: {
          aspectRatio: "1:1",
          imageSize: size
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  },

  /**
   * Edit images (Gemini 2.5 Flash Image)
   */
  async editImage(base64Image: string, editPrompt: string): Promise<string | null> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: editPrompt }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  },

  /**
   * Maps Grounding (Gemini 2.5 Flash)
   */
  async getMapsInfo(query: string, lat?: number, lng?: number): Promise<{ text: string, links: any[] }> {
    const ai = getAI();
    const config: any = {
      tools: [{ googleMaps: {} }],
    };

    if (lat !== undefined && lng !== undefined) {
      config.toolConfig = {
        retrievalConfig: {
          latLng: { latitude: lat, longitude: lng }
        }
      };
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: query,
      config
    });

    return {
      text: response.text || "",
      links: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  }
};

import React, { useState, useRef } from 'react';
import { geminiService } from '../services/geminiService';
import { Icons } from '../constants';

const AILab: React.FC = () => {
  const [activeTool, setActiveTool] = useState<'thinking' | 'vision' | 'generation' | 'maps' | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [input, setInput] = useState('');
  const [imageSize, setImageSize] = useState<'1K' | '2K' | '4K'>('1K');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSelectedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const runThinking = async () => {
    if (!input) return;
    setLoading(true);
    setResult(null);
    try {
      const res = await geminiService.thinkComplex(input);
      setResult(res);
    } catch (e) {
      setResult("Chyba při zpracování strategického plánu.");
    }
    setLoading(false);
  };

  const runVision = async () => {
    if (!selectedImage || !input) return;
    setLoading(true);
    setResult(null);
    try {
      const base64 = selectedImage.split(',')[1];
      const res = await geminiService.analyzeImage(input, base64);
      setResult(res);
    } catch (e) {
      setResult("Chyba při analýze obrázku.");
    }
    setLoading(false);
  };

  const runGeneration = async () => {
    if (!input) return;

    // Fixed: Handle mandatory API key selection for gemini-3-pro-image-preview
    try {
      if (typeof (window as any).aistudio?.hasSelectedApiKey === 'function') {
        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        if (!hasKey) {
          await (window as any).aistudio.openSelectKey();
        }
      }
    } catch (err) {
      console.warn("API Key check skipped or failed", err);
    }

    setLoading(true);
    setResult(null);
    try {
      const res = await geminiService.generateImage(input, imageSize);
      setResult(res);
    } catch (e: any) {
      // Fixed: Graceful handling of "Requested entity was not found" error by re-prompting for API key
      if (e?.message?.includes("Requested entity was not found.")) {
        try {
          await (window as any).aistudio.openSelectKey();
        } catch (err) {}
      }
      setResult("Chyba při generování obrázku.");
    }
    setLoading(false);
  };

  const runMaps = async () => {
    if (!input) return;
    setLoading(true);
    setResult(null);
    try {
      const res = await geminiService.getMapsInfo(input, 50.0755, 14.4378);
      setResult(res);
    } catch (e) {
      setResult({ text: "Chyba při načítání mapových informací.", links: [] });
    }
    setLoading(false);
  };

  const reset = () => {
    setActiveTool(null);
    setResult(null);
    setInput('');
    setSelectedImage(null);
  };

  const getToolTitle = (tool: string) => {
    switch(tool) {
      case 'thinking': return 'Strategický Plánovač';
      case 'vision': return 'Vizuální Odhadce';
      case 'generation': return 'Generátor Reklamy';
      case 'maps': return 'Průzkumník Trasy';
      default: return tool;
    }
  };

  if (!activeTool) {
    return (
      <div className="space-y-4">
        <h2 className="text-xl font-bold mb-4">Gemini AI Laboratoř</h2>
        <div className="grid grid-cols-2 gap-4">
          <ToolCard 
            title="Strategický Plánovač" 
            desc="Hloubkové myšlení pro komplexní logistiku." 
            icon={<Icons.Sparkles />} 
            onClick={() => setActiveTool('thinking')} 
          />
          <ToolCard 
            title="Vizuální Odhadce" 
            desc="Analyzujte fotky místností pro odhad objemu." 
            icon={<Icons.Camera />} 
            onClick={() => setActiveTool('vision')} 
          />
          <ToolCard 
            title="Generátor Reklamy" 
            desc="Tvořte vizuály a postery pro sociální sítě." 
            icon={<Icons.Plus />} 
            onClick={() => setActiveTool('generation')} 
          />
          <ToolCard 
            title="Průzkumník Trasy" 
            desc="Získejte aktuální info o místech a trasách." 
            icon={<Icons.Map />} 
            onClick={() => setActiveTool('maps')} 
          />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3">
        <button onClick={reset} className="p-2 bg-slate-100 rounded-full">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <h2 className="text-lg font-bold">{getToolTitle(activeTool)}</h2>
      </div>

      <div className="bg-white rounded-[32px] p-6 shadow-xl border border-slate-100 space-y-4">
        {activeTool === 'vision' && (
          <div className="space-y-4">
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="w-full aspect-video bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center gap-2 cursor-pointer overflow-hidden"
            >
              {selectedImage ? (
                <img src={selectedImage} className="w-full h-full object-cover" alt="Upload" />
              ) : (
                <>
                  <Icons.Camera />
                  <span className="text-xs font-bold text-slate-400">Klikněte pro nahrání fotky pokoje</span>
                </>
              )}
            </div>
            <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleImageUpload} />
          </div>
        )}

        {activeTool === 'generation' && (
          <div className="flex justify-center gap-2">
            {(['1K', '2K', '4K'] as const).map(size => (
              <button 
                key={size}
                onClick={() => setImageSize(size)}
                className={`px-4 py-2 rounded-xl text-xs font-bold border-2 transition-all ${imageSize === size ? 'bg-blue-600 border-blue-600 text-white' : 'border-slate-100 text-slate-400'}`}
              >
                {size}
              </button>
            ))}
          </div>
        )}

        <textarea 
          placeholder={
            activeTool === 'thinking' ? "Popište komplexní logistický problém..." :
            activeTool === 'vision' ? "Co mám na této fotce analyzovat?" :
            activeTool === 'generation' ? "Popište obrázek, který chcete vytvořit..." :
            "Zeptejte se na blízké lokace nebo trasy..."
          }
          value={input}
          onChange={e => setInput(e.target.value)}
          className="w-full bg-slate-50 border-none rounded-2xl p-4 min-h-[120px] focus:ring-2 focus:ring-blue-600 outline-none text-sm leading-relaxed"
        />

        <button 
          onClick={
            activeTool === 'thinking' ? runThinking :
            activeTool === 'vision' ? runVision :
            activeTool === 'generation' ? runGeneration :
            runMaps
          }
          disabled={loading || !input}
          className="w-full bg-blue-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-blue-100 flex items-center justify-center gap-3 disabled:opacity-50"
        >
          {loading ? (
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
          ) : (
            <>
              <Icons.Sparkles />
              Spustit AI
            </>
          )}
        </button>
      </div>

      {result && (
        <div className="animate-fade-in space-y-4">
          <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest px-2">Výsledek</h3>
          <div className="bg-blue-50 text-blue-900 p-6 rounded-[32px] border border-blue-100">
            {activeTool === 'generation' && typeof result === 'string' && result.startsWith('data:') ? (
              <div className="space-y-4">
                <img src={result} className="w-full rounded-2xl shadow-lg" alt="Generated" />
                <button className="w-full py-3 text-xs font-bold text-blue-600 bg-white rounded-xl shadow-sm">Uložit do galerie</button>
              </div>
            ) : activeTool === 'maps' ? (
              <div className="space-y-4">
                <p className="whitespace-pre-wrap text-sm leading-relaxed">{result.text}</p>
                {result.links.length > 0 && (
                  <div className="pt-4 border-t border-blue-100 space-y-2">
                    {result.links.map((link: any, i: number) => (
                      <a key={i} href={link.maps?.uri} target="_blank" rel="noreferrer" className="flex items-center justify-between bg-white p-3 rounded-xl text-xs font-bold shadow-sm">
                        <span>{link.maps?.title || "Zobrazit na mapě"}</span>
                        <Icons.ChevronRight />
                      </a>
                    ))}
                  </div>
                )}
              </div>
            ) : (
              <p className="whitespace-pre-wrap text-sm leading-relaxed">{result}</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

