import React, { useState } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
  user: {
    workerId?: string;
    role: 'admin' | 'user';
  };
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles, user }) => {
  const [selectedTask, setSelectedTask] = useState<MoveTask | null>(null);

  const activeTasks = tasks.filter(t => t.status !== 'Completed');
  const availableWorkers = workers.filter(w => w.status === 'Available');
  const availableVehicles = vehicles.filter(v => v.status === 'Ready');

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  const isTomorrow = (date: Date) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return date.getDate() === tomorrow.getDate() &&
      date.getMonth() === tomorrow.getMonth() &&
      date.getFullYear() === tomorrow.getFullYear();
  };

  const myTasks = user.workerId 
    ? tasks.filter(t => t.assignedWorkers.includes(user.workerId!))
    : (user.role === 'admin' ? tasks : []);

  const todayTasks = myTasks.filter(t => isToday(t.start));
  const tomorrowTasks = myTasks.filter(t => isTomorrow(t.start));

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const TaskCard = ({ task }: { task: MoveTask }) => (
    <div 
      onClick={() => setSelectedTask(task)}
      className="bg-slate-800 p-5 rounded-[2.5rem] shadow-sm border border-slate-700 flex items-center gap-5 hover:bg-slate-700 hover:border-blue-500/30 transition-all cursor-pointer active:scale-[0.98] group"
    >
      <div className="flex flex-col items-center justify-center bg-slate-900 group-hover:bg-blue-600 group-hover:text-white rounded-[2rem] p-4 min-w-[75px] transition-colors duration-300 text-slate-400">
        <span className="font-black text-xl leading-none group-hover:text-white transition-colors">
          {task.start.getHours()}
        </span>
        <span className="text-[10px] font-black opacity-40 uppercase mt-1">HOD</span>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-black text-slate-100 text-base leading-tight group-hover:text-blue-400 transition-colors">{task.title}</h3>
        <p className="text-xs text-slate-400 font-bold mt-1 uppercase tracking-tight">{task.customer}</p>
        <div className="flex items-center gap-2 mt-2">
          <div className="flex -space-x-2">
            {task.assignedWorkers.slice(0, 3).map((_, i) => (
              <div key={i} className="w-5 h-5 rounded-full bg-slate-700 border-2 border-slate-800 flex items-center justify-center text-[8px] font-black text-blue-400"><Icons.User /></div>
            ))}
          </div>
          <span className="text-[10px] text-slate-500 font-bold truncate">
            {task.from}
          </span>
        </div>
      </div>

      <div className={`w-3 h-3 rounded-full shadow-[0_0_10px_rgba(0,0,0,0.5)] ${
        task.status === 'Confirmed' ? 'bg-blue-500' : 
        task.status === 'In Progress' ? 'bg-red-500 animate-pulse' : 'bg-slate-600'
      }`} />
    </div>
  );

  return (
    <div className="space-y-10">
      {/* Dark Stat Cards */}
      <div className="grid grid-cols-3 gap-4">
        <StatCard label="Aktivní" value={activeTasks.length} color="blue" />
        <StatCard label="Tým" value={availableWorkers.length} color="slate" />
        <StatCard label="Flotila" value={availableVehicles.length} color="red" />
      </div>

      <section className="space-y-5">
        <div className="flex items-center justify-between px-2">
          <h2 className="text-xl font-black text-slate-100 tracking-tighter uppercase">Dnešní <span className="text-red-500">Mise</span></h2>
          <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_#ef4444]" />
        </div>
        <div className="space-y-4">
          {todayTasks.length > 0 ? todayTasks.map(task => (
            <TaskCard key={task.id} task={task} />
          )) : (
            <div className="bg-slate-800/50 rounded-[2.5rem] p-10 text-center border-2 border-dashed border-slate-700">
              <p className="text-xs font-black text-slate-600 uppercase tracking-widest">Žádné dnešní úkoly</p>
            </div>
          )}
        </div>
      </section>

      <section className="space-y-5">
        <h2 className="text-xl font-black text-slate-100 tracking-tighter px-2 uppercase">Plány <span className="text-blue-500">Zítra</span></h2>
        <div className="space-y-4">
          {tomorrowTasks.length > 0 ? tomorrowTasks.map(task => (
            <TaskCard key={task.id} task={task} />
          )) : (
            <div className="bg-slate-800/50 rounded-[2.5rem] p-10 text-center border-2 border-dashed border-slate-700">
              <p className="text-xs font-black text-slate-600 uppercase tracking-widest">Zítra volno</p>
            </div>
          )}
        </div>
      </section>

      {/* Dark Detail Modal */}
      {selectedTask && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-50 flex items-end sm:items-center justify-center p-4" onClick={() => setSelectedTask(null)}>
          <div 
            className="bg-slate-900 w-full max-w-md rounded-[3rem] p-8 shadow-2xl animate-slide-up border border-slate-800"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex justify-between items-start mb-8">
              <div>
                <span className="text-[10px] font-black uppercase tracking-[0.2em] px-3 py-1 bg-red-600 text-white rounded-lg mb-3 inline-block">
                  {selectedTask.status}
                </span>
                <h3 className="text-3xl font-black text-white tracking-tighter">{selectedTask.title}</h3>
              </div>
              <button onClick={() => setSelectedTask(null)} className="bg-slate-800 p-3 rounded-2xl hover:bg-slate-700 transition-colors text-slate-400">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>

            <div className="space-y-8">
              <div className="flex items-center justify-between bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl shadow-blue-600/20">
                <div className="flex-1">
                  <p className="text-[10px] font-black text-white/50 uppercase tracking-widest mb-1">Zákazník</p>
                  <p className="text-xl font-black leading-tight">{selectedTask.customer}</p>
                </div>
                {selectedTask.customerPhone && (
                  <a href={`tel:${selectedTask.customerPhone.replace(/\s+/g, '')}`} className="bg-slate-900/40 text-white p-4 rounded-2xl shadow-lg active:scale-95 transition-all">
                    <Icons.Phone />
                  </a>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleOpenMaps(selectedTask.from)} className="bg-slate-800 p-6 rounded-[2rem] text-left hover:bg-slate-700 transition-all border border-slate-700">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">PŘEVZETÍ</p>
                  <p className="text-xs font-black text-slate-200 truncate">{selectedTask.from}</p>
                </button>
                <button onClick={() => handleOpenMaps(selectedTask.to)} className="bg-slate-800 p-6 rounded-[2rem] text-left hover:bg-slate-700 transition-all border border-slate-700">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">CÍL</p>
                  <p className="text-xs font-black text-slate-200 truncate">{selectedTask.to}</p>
                </button>
              </div>

              <button 
                onClick={() => setSelectedTask(null)}
                className="w-full bg-blue-600 text-white font-black py-5 rounded-[2rem] shadow-xl shadow-blue-600/20 transition-all active:scale-95 text-sm uppercase tracking-widest"
              >
                Potvrdit hotovo
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard = ({ label, value, color }: { label: string, value: number, color: 'blue' | 'red' | 'slate' }) => {
  const themes = {
    blue: 'bg-blue-600 text-white shadow-blue-600/30',
    red: 'bg-red-600 text-white shadow-red-600/30',
    slate: 'bg-slate-800 text-slate-100 border border-slate-700'
  };

  return (
    <div className={`p-6 rounded-[2.5rem] ${themes[color]} flex flex-col items-center text-center shadow-xl transition-transform hover:-translate-y-1`}>
      <span className="text-3xl font-black mb-1">{value}</span>
      <span className={`text-[10px] font-black uppercase tracking-widest ${color === 'slate' ? 'opacity-40' : 'opacity-60'}`}>{label}</span>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons, COLORS } from '../constants';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type ViewMode = 'day' | 'week' | 'month';
type StatusType = MoveTask['status'];

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('day');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  const [showFilters, setShowFilters] = useState(false);
  const [filterStatus, setFilterStatus] = useState<StatusType | 'All'>('All');
  const [filterWorker, setFilterWorker] = useState<string>('All');
  const [filterVehicle, setFilterVehicle] = useState<string>('All');

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '', customer: '', customerPhone: '', from: '', to: '',
    status: 'Pending', notes: '',
    assignedWorkers: [], assignedVehicles: []
  });

  const isSameDay = (d1: Date, d2: Date) => 
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate();

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const formatForInput = (date?: Date) => {
    if (!date) return '';
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate);
    if (viewMode === 'day') newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1));
    else if (viewMode === 'week') newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7));
    else if (viewMode === 'month') newDate.setMonth(currentDate.getMonth() + (direction === 'next' ? 1 : -1));
    setCurrentDate(newDate);
  };

  const filteredTasks = useMemo(() => {
    return tasks.filter(task => {
      const statusMatch = filterStatus === 'All' || task.status === filterStatus;
      const workerMatch = filterWorker === 'All' || task.assignedWorkers.includes(filterWorker);
      const vehicleMatch = filterVehicle === 'All' || task.assignedVehicles.includes(filterVehicle);

      let dateMatch = false;
      if (viewMode === 'day') {
        dateMatch = isSameDay(task.start, currentDate);
      } else if (viewMode === 'week') {
        const startOfWeek = new Date(currentDate);
        startOfWeek.setDate(currentDate.getDate() - currentDate.getDay() + (currentDate.getDay() === 0 ? -6 : 1));
        const endOfWeek = new Date(startOfWeek);
        endOfWeek.setDate(startOfWeek.getDate() + 6);
        dateMatch = task.start >= startOfWeek && task.start <= endOfWeek;
      } else {
        dateMatch = task.start.getMonth() === currentDate.getMonth() && task.start.getFullYear() === currentDate.getFullYear();
      }

      return statusMatch && workerMatch && vehicleMatch && dateMatch;
    });
  }, [tasks, filterStatus, filterWorker, filterVehicle, currentDate, viewMode]);

  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 90;

  const positionedTasks = useMemo(() => {
    if (viewMode !== 'day') return [];
    const sorted = [...filteredTasks].sort((a, b) => a.start.getTime() - b.start.getTime());
    const columns: MoveTask[][] = [];

    sorted.forEach(task => {
      let placed = false;
      for (let i = 0; i < columns.length; i++) {
        const lastTaskInColumn = columns[i][columns[i].length - 1];
        if (task.start >= lastTaskInColumn.end) {
          columns[i].push(task);
          placed = true;
          break;
        }
      }
      if (!placed) columns.push([task]);
    });

    return columns.flatMap((column, colIndex) => 
      column.map(task => ({ ...task, colIndex, totalCols: columns.length }))
    );
  }, [filteredTasks, viewMode]);

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date(currentDate);
    start.setHours(9, 0, 0, 0);
    const end = new Date(start.getTime() + 2 * 60 * 60 * 1000);
    setCurrentTask({
      title: '', customer: '', customerPhone: '', from: '', to: '',
      status: 'Pending', start, end, notes: '',
      assignedWorkers: [], assignedVehicles: []
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const handleSaveTask = () => {
    if (user.role !== 'admin') return;
    if (isEditing && currentTask.id) {
      setTasks(tasks.map(t => t.id === currentTask.id ? { ...t, ...currentTask } as MoveTask : t));
    } else {
      const id = Math.random().toString(36).substr(2, 9);
      const task: MoveTask = {
        ...(currentTask as MoveTask),
        id,
        start: currentTask.start || new Date(),
        end: currentTask.end || new Date(new Date().getTime() + 2 * 60 * 60 * 1000),
        assignedWorkers: currentTask.assignedWorkers || [],
        assignedVehicles: currentTask.assignedVehicles || []
      };
      setTasks([...tasks, task]);
    }
    setShowModal(false);
  };

  const getStatusColorClass = (status: StatusType) => {
    switch(status) {
      case 'Completed': return 'bg-slate-800 border-slate-700 text-slate-500';
      case 'In Progress': return 'bg-red-600 border-red-500 text-white shadow-lg shadow-red-600/30';
      case 'Confirmed': return 'bg-blue-600 border-blue-500 text-white shadow-lg shadow-blue-600/30';
      default: return 'bg-slate-700 border-slate-600 text-slate-200';
    }
  };

  const renderDayView = () => (
    <div className="flex-1 overflow-y-auto no-scrollbar relative p-5 pt-4 bg-slate-900">
      <div className="absolute left-4 top-4 bottom-0 w-12 z-10 pointer-events-none">
        {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
          <div key={i} className="text-[10px] font-black text-slate-600" style={{ height: `${HOUR_HEIGHT}px` }}>
            {String(START_HOUR + i).padStart(2, '0')}:00
          </div>
        ))}
      </div>
      <div className="ml-14 relative h-full min-h-[1440px]">
        {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
          <div key={i} className="border-t border-slate-800 absolute w-full pointer-events-none" style={{ top: `${i * HOUR_HEIGHT}px` }} />
        ))}
        {isSameDay(currentDate, new Date()) && (
          <div className="absolute left-0 right-0 border-t-2 border-red-500 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
            <div className="w-2 h-2 rounded-full bg-red-500 -ml-1 shadow-[0_0_10px_#ef4444] ring-4 ring-red-500/10" />
          </div>
        )}
        {positionedTasks.map((task: any) => {
          const startDecimal = task.start.getHours() + task.start.getMinutes() / 60;
          const endDecimal = task.end.getHours() + task.end.getMinutes() / 60;
          const duration = Math.max(0.5, endDecimal - startDecimal);
          const top = (startDecimal - START_HOUR) * HOUR_HEIGHT;
          const height = duration * HOUR_HEIGHT;
          const width = 100 / task.totalCols;
          const left = task.colIndex * width;

          return (
            <div key={task.id} onClick={() => handleOpenEdit(task)} className={`absolute p-1 transition-all cursor-pointer group z-20`} style={{ top: `${top}px`, height: `${height}px`, left: `${left}%`, width: `${width}%` }}>
              <div className={`h-full w-full rounded-[1.5rem] border p-4 shadow-sm hover:shadow-xl hover:scale-[1.02] transition-all overflow-hidden flex flex-col ${getStatusColorClass(task.status)}`}>
                <div className="flex justify-between items-start mb-1">
                  <h4 className="text-[12px] font-black leading-tight line-clamp-2">{task.title}</h4>
                  <span className={`text-[9px] font-black opacity-60`}>
                    {task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}
                  </span>
                </div>
                <p className={`text-[10px] font-bold uppercase tracking-tight truncate opacity-80`}>{task.customer}</p>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      {/* Dark Tab Toggle */}
      <div className="flex items-center justify-between">
        <div className="flex bg-slate-900 p-1 rounded-2xl shadow-sm border border-slate-800">
          {(['day', 'week', 'month'] as ViewMode[]).map(m => (
            <button key={m} onClick={() => setViewMode(m)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === m ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' : 'text-slate-600 hover:text-slate-400'}`}>
              {m === 'day' ? 'Den' : m === 'week' ? 'Týden' : 'Měsíc'}
            </button>
          ))}
        </div>
        {user.role === 'admin' && (
          <button onClick={handleOpenCreate} className="bg-red-600 text-white p-3 rounded-2xl shadow-xl shadow-red-600/30 active:scale-95 transition-all">
            <Icons.Plus />
          </button>
        )}
      </div>

      {/* Dark Date Navigation */}
      <div className="bg-slate-800 rounded-[2rem] p-5 shadow-sm border border-slate-700 flex items-center justify-between">
        <button onClick={() => navigateDate('prev')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <div className="text-center">
          <p className="text-xs font-black text-slate-100 uppercase tracking-[0.2em]">
            {viewMode === 'day' ? currentDate.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' }) :
             viewMode === 'week' ? `Týden ${Math.ceil(currentDate.getDate() / 7)}` :
             currentDate.toLocaleDateString('cs-CZ', { month: 'long', year: 'numeric' })}
          </p>
          {viewMode === 'day' && <p className="text-[10px] font-bold text-red-500 uppercase tracking-widest mt-0.5">{currentDate.toLocaleDateString('cs-CZ', { weekday: 'long' })}</p>}
        </div>
        <button onClick={() => navigateDate('next')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
