          </div>
        )}
      </div>

      {/* Re-style Task Modal for Dark Mode (Shared Logic) */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-md rounded-t-[32px] sm:rounded-[32px] p-8 shadow-2xl animate-slide-up border border-slate-800 overflow-y-auto no-scrollbar max-h-[90vh]">
