import React, { useState, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons, COLORS } from '../constants';

interface CalendarViewProps {
  tasks: MoveTask[];
  setTasks: React.Dispatch<React.SetStateAction<MoveTask[]>>;
  workers: Worker[];
  vehicles: Vehicle[];
  user: { role: 'admin' | 'user' };
}

type ViewMode = 'day' | 'week' | 'month';

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, setTasks, workers, vehicles, user }) => {
  const [viewMode, setViewMode] = useState<ViewMode>('day');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  const [currentTask, setCurrentTask] = useState<Partial<MoveTask>>({
    title: '', customer: '', customerPhone: '', from: '', to: '',
    status: 'Pending', notes: '', assignedWorkers: [], assignedVehicles: []
  });

  const isSameDay = (d1: Date, d2: Date) => 
    d1.getFullYear() === d2.getFullYear() &&
    d1.getMonth() === d2.getMonth() &&
    d1.getDate() === d2.getDate();

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate);
    if (viewMode === 'day') newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1));
    else if (viewMode === 'week') newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7));
    else if (viewMode === 'month') newDate.setMonth(currentDate.getMonth() + (direction === 'next' ? 1 : -1));
    setCurrentDate(newDate);
  };

  const filteredTasks = useMemo(() => {
    return tasks.filter(task => isSameDay(task.start, currentDate));
  }, [tasks, currentDate]);

  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 90;

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date(currentDate);
    start.setHours(9, 0, 0, 0);
    const end = new Date(start.getTime() + 3 * 60 * 60 * 1000);
    setCurrentTask({
      title: '', customer: '', customerPhone: '', from: '', to: '',
      status: 'Pending', start, end, assignedWorkers: [], assignedVehicles: []
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const saveTask = () => {
    if (!currentTask.title || !currentTask.start || !currentTask.end) return;
    const taskData = {
      ...currentTask,
      id: currentTask.id || Math.random().toString(36).substr(2, 9),
      start: new Date(currentTask.start),
      end: new Date(currentTask.end)
    } as MoveTask;

    if (isEditing) {
      setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
      setTasks([...tasks, taskData]);
    }
    setShowModal(false);
  };

  const toggleResource = (id: string, type: 'worker' | 'vehicle') => {
    if (type === 'worker') {
      const current = currentTask.assignedWorkers || [];
      const updated = current.includes(id) ? current.filter(wid => wid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedWorkers: updated});
    } else {
      const current = currentTask.assignedVehicles || [];
      const updated = current.includes(id) ? current.filter(vid => vid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedVehicles: updated});
    }
  };

  const formatForInput = (date?: Date) => {
    if (!date) return '';
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex bg-slate-900 p-1 rounded-2xl border border-slate-800 shadow-inner">
          <button className="px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest bg-blue-600 text-white shadow-lg shadow-blue-600/20">Den</button>
          <button className="px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-600">Týden</button>
        </div>
        <button onClick={handleOpenCreate} className="bg-red-600 text-white p-3 rounded-2xl shadow-xl shadow-red-600/30 active:scale-95 transition-all">
          <Icons.Plus />
        </button>
      </div>

      <div className="bg-slate-800 rounded-[2rem] p-5 shadow-sm border border-slate-700 flex items-center justify-between">
        <button onClick={() => navigateDate('prev')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <div className="text-center">
          <p className="text-xs font-black text-slate-100 uppercase tracking-widest">
            {currentDate.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' })}
          </p>
          <p className="text-[10px] font-bold text-red-500 uppercase tracking-widest mt-0.5">{currentDate.toLocaleDateString('cs-CZ', { weekday: 'long' })}</p>
        </div>
        <button onClick={() => navigateDate('next')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </div>

      <div className="bg-slate-800 rounded-[3rem] shadow-sm border border-slate-700 overflow-hidden flex flex-col h-[600px] relative">
        <div className="flex-1 overflow-y-auto no-scrollbar relative p-5 pt-4 bg-slate-900">
          <div className="absolute left-4 top-4 bottom-0 w-12 z-10 pointer-events-none text-slate-700 text-[10px] font-black">
            {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
              <div key={i} style={{ height: `${HOUR_HEIGHT}px` }}>{START_HOUR + i}:00</div>
            ))}
          </div>
          <div className="ml-14 relative h-full min-h-[1440px]">
             {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
               <div key={i} className="border-t border-slate-800 absolute w-full pointer-events-none" style={{ top: `${i * HOUR_HEIGHT}px` }} />
             ))}
             {filteredTasks.map(task => {
               const top = (task.start.getHours() + task.start.getMinutes()/60 - START_HOUR) * HOUR_HEIGHT;
               const height = (task.end.getTime() - task.start.getTime()) / (1000 * 60 * 60) * HOUR_HEIGHT;
               return (
                 <div key={task.id} onClick={() => handleOpenEdit(task)} className="absolute w-full p-1 z-20" style={{ top: `${top}px`, height: `${height}px` }}>
                   <div className={`h-full w-full rounded-2xl border p-4 shadow-lg flex flex-col justify-between ${task.status === 'Confirmed' ? 'bg-blue-600 border-blue-500 text-white' : 'bg-red-600 border-red-500 text-white'}`}>
                     <div>
                       <h4 className="text-xs font-black leading-none">{task.title}</h4>
                       <p className="text-[9px] font-bold opacity-70 uppercase mt-1">{task.customer}</p>
                     </div>
                     <p className="text-[8px] font-black uppercase text-right opacity-60">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</p>
                   </div>
                 </div>
               );
             })}
          </div>
        </div>
      </div>

      {/* Task Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-lg z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-lg rounded-[32px] p-8 border border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
            <h3 className="text-2xl font-black text-white mb-6 uppercase tracking-tighter">{isEditing ? 'Upravit úkol' : 'Nový stěhovák'}</h3>
            <div className="space-y-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Název akce</label>
                <input value={currentTask.title} onChange={e => setCurrentTask({...currentTask, title: e.target.value})} placeholder="např. Stěhování bytu 3+1" className="w-full bg-slate-800 rounded-xl p-4 text-white border-none font-bold" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Zákazník</label>
                    <input value={currentTask.customer} onChange={e => setCurrentTask({...currentTask, customer: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Telefon</label>
                    <input value={currentTask.customerPhone} onChange={e => setCurrentTask({...currentTask, customerPhone: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Začátek</label>
                    <input type="datetime-local" value={formatForInput(currentTask.start)} onChange={e => setCurrentTask({...currentTask, start: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Konec</label>
                    <input type="datetime-local" value={formatForInput(currentTask.end)} onChange={e => setCurrentTask({...currentTask, end: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Přiřadit Tým</label>
                <div className="flex flex-wrap gap-2">
                   {workers.map(w => (
                     <button key={w.id} onClick={() => toggleResource(w.id, 'worker')} className={`px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all border ${currentTask.assignedWorkers?.includes(w.id) ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}>{w.name}</button>
                   ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Přiřadit Flotilu</label>
                <div className="flex flex-wrap gap-2">
                   {vehicles.map(v => (
                     <button key={v.id} onClick={() => toggleResource(v.id, 'vehicle')} className={`px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all border ${currentTask.assignedVehicles?.includes(v.id) ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}>{v.plate}</button>
                   ))}
                </div>
              </div>

              <button onClick={saveTask} className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 mt-4">Uložit Zakázku</button>
              <button onClick={() => setShowModal(false)} className="w-full text-slate-500 font-bold py-2">Zrušit</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useRef } from 'react';
import { geminiService } from '../services/geminiService';
import { Icons } from '../constants';

const AILab: React.FC = () => {
  const [activeTool, setActiveTool] = useState<'thinking' | 'vision' | 'generation' | 'maps' | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [input, setInput] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSelectedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const runTool = async () => {
    if (!input && activeTool !== 'vision') return;
    setLoading(true);
    setResult(null);
    try {
      if (activeTool === 'thinking') {
        const res = await geminiService.thinkComplex(input);
        setResult(res);
      } else if (activeTool === 'vision' && selectedImage) {
        const base64 = selectedImage.split(',')[1];
        const res = await geminiService.analyzeImage(input || "Co vidíš na této fotce v kontextu stěhování?", base64);
        setResult(res);
      } else if (activeTool === 'generation') {
        const res = await geminiService.generateImage(input, '1K');
        setResult(res);
      } else if (activeTool === 'maps') {
        const res = await geminiService.getMapsInfo(input);
        setResult(res);
      }
    } catch (e) {
      setResult("Omlouváme se, AI služba je momentálně přetížena.");
    }
    setLoading(false);
  };

  const reset = () => { setActiveTool(null); setResult(null); setInput(''); setSelectedImage(null); };

  if (!activeTool) {
    return (
      <div className="space-y-6">
        <h2 className="text-xl font-black text-white tracking-tighter uppercase">Gemini <span className="text-blue-400">AI</span> Laboratoř</h2>
        <div className="grid grid-cols-2 gap-4">
          <ToolCard title="Plánovač" desc="Strategické myšlení." icon={<Icons.Sparkles />} onClick={() => setActiveTool('thinking')} />
          <ToolCard title="Vision" desc="Analýza objemu z foto." icon={<Icons.Camera />} onClick={() => setActiveTool('vision')} />
          <ToolCard title="Design" desc="Tvorba vizuálů." icon={<Icons.Plus />} onClick={() => setActiveTool('generation')} />
          <ToolCard title="Průzkum" desc="Mapová data." icon={<Icons.Map />} onClick={() => setActiveTool('maps')} />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center gap-3">
        <button onClick={reset} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <h2 className="text-lg font-black text-white uppercase tracking-tight">{activeTool === 'thinking' ? 'Strategický Plánovač' : activeTool === 'vision' ? 'Vizuální Odhad' : activeTool === 'generation' ? 'AI Design' : 'Průzkum Trasy'}</h2>
      </div>

      <div className="bg-slate-800 rounded-[32px] p-6 shadow-xl border border-slate-700 space-y-4">
        {activeTool === 'vision' && (
          <div onClick={() => fileInputRef.current?.click()} className="aspect-video bg-slate-900 rounded-2xl border-2 border-dashed border-slate-700 flex flex-col items-center justify-center cursor-pointer overflow-hidden mb-4">
            {selectedImage ? <img src={selectedImage} className="w-full h-full object-cover" /> : <div className="text-slate-600 text-center p-4"><Icons.Camera /><p className="text-[10px] font-black mt-2">NAHRÁT FOTKU PROSTORY</p></div>}
            <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleImageUpload} />
          </div>
        )}

        <textarea 
          placeholder={activeTool === 'thinking' ? "Zadejte logistický oříšek..." : activeTool === 'vision' ? "Zeptejte se na fotku (např. kolik krabic bude potřeba?)" : "Popište co má AI vytvořit..."}
          value={input}
          onChange={e => setInput(e.target.value)}
          className="w-full bg-slate-900 border-none rounded-2xl p-5 min-h-[140px] focus:ring-2 focus:ring-blue-500 outline-none text-sm text-slate-100 placeholder-slate-600"
        />

        <button 
          onClick={runTool}
          disabled={loading || (!input && activeTool !== 'vision')}
          className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 flex items-center justify-center gap-3 disabled:opacity-30 transition-all"
        >
          {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <><Icons.Sparkles /> Vyvolat AI</>}
        </button>
      </div>

      {result && (
        <div className="bg-blue-600/10 border border-blue-500/20 p-6 rounded-[32px] animate-fade-in overflow-hidden">
          {typeof result === 'string' && result.startsWith('data:') ? (
            <img src={result} className="w-full rounded-xl shadow-2xl" />
          ) : typeof result === 'object' && result.text ? (
             <div className="space-y-4">
               <p className="text-blue-100 text-sm leading-relaxed">{result.text}</p>
               {result.links?.map((l:any, i:number) => (
                 <a key={i} href={l.maps?.uri} target="_blank" className="flex items-center justify-between bg-slate-900 p-3 rounded-xl text-[10px] font-black text-blue-400">
                   {l.maps?.title || "ZOBRAZIT MÍSTO"} <Icons.ChevronRight />
                 </a>
               ))}
             </div>
          ) : (
            <p className="text-blue-100 text-sm leading-relaxed whitespace-pre-wrap">{result}</p>
          )}
        </div>
      )}
    </div>
  );
};

const ToolCard = ({ title, desc, icon, onClick }: { title: string, desc: string, icon: React.ReactNode, onClick: () => void }) => (
  <button onClick={onClick} className="bg-slate-800 p-6 rounded-[28px] text-left border border-slate-700 shadow-sm hover:bg-slate-750 hover:border-blue-500/30 transition-all group">
