    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
    return new Date(date.setDate(diff));
  };

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate);
    if (viewMode === 'day') {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1));
    } else {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7));
    }
    setCurrentDate(newDate);
  };

  const START_HOUR = 6;
  const END_HOUR = 22;
  const HOUR_HEIGHT = 90;

  const handleOpenCreate = () => {
    setIsEditing(false);
    const start = new Date(currentDate);
    start.setHours(9, 0, 0, 0);
    const end = new Date(start.getTime() + 3 * 60 * 60 * 1000);
    setCurrentTask({
      title: '', customer: '', customerPhone: '', from: '', to: '',
      status: 'Pending', start, end, assignedWorkers: [], assignedVehicles: []
    });
    setShowModal(true);
  };

  const handleOpenEdit = (task: MoveTask) => {
    setIsEditing(true);
    setCurrentTask({ ...task });
    setShowModal(true);
  };

  const saveTask = () => {
    if (!currentTask.title || !currentTask.start || !currentTask.end) return;
    const taskData = {
      ...currentTask,
      id: currentTask.id || Math.random().toString(36).substr(2, 9),
      start: new Date(currentTask.start),
      end: new Date(currentTask.end)
    } as MoveTask;

    if (isEditing) {
      setTasks(tasks.map(t => t.id === taskData.id ? taskData : t));
    } else {
      setTasks([...tasks, taskData]);
    }
    setShowModal(false);
  };

  const toggleResource = (id: string, type: 'worker' | 'vehicle') => {
    if (type === 'worker') {
      const current = currentTask.assignedWorkers || [];
      const updated = current.includes(id) ? current.filter(wid => wid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedWorkers: updated});
    } else {
      const current = currentTask.assignedVehicles || [];
      const updated = current.includes(id) ? current.filter(vid => vid !== id) : [...current, id];
      setCurrentTask({...currentTask, assignedVehicles: updated});
    }
  };

  const formatForInput = (date?: Date) => {
    if (!date) return '';
    const d = new Date(date);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };

  const renderDayView = () => {
    const dayTasks = tasks.filter(task => isSameDay(task.start, currentDate));
    return (
      <div className="flex-1 overflow-y-auto no-scrollbar relative p-5 pt-4 bg-slate-900">
        <div className="absolute left-4 top-4 bottom-0 w-12 z-10 pointer-events-none text-slate-700 text-[10px] font-black">
          {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
            <div key={i} style={{ height: `${HOUR_HEIGHT}px` }}>{START_HOUR + i}:00</div>
          ))}
        </div>
        <div className="ml-14 relative h-full min-h-[1440px]">
           {Array.from({ length: END_HOUR - START_HOUR + 1 }).map((_, i) => (
             <div key={i} className="border-t border-slate-800 absolute w-full pointer-events-none" style={{ top: `${i * HOUR_HEIGHT}px` }} />
           ))}
           {isSameDay(currentDate, new Date()) && (
              <div className="absolute left-0 right-0 border-t-2 border-red-500 z-10 flex items-center pointer-events-none" style={{ top: `${(new Date().getHours() - START_HOUR + new Date().getMinutes()/60) * HOUR_HEIGHT}px` }}>
                <div className="w-2 h-2 rounded-full bg-red-500 -ml-1 shadow-[0_0_10px_#ef4444]" />
              </div>
            )}
           {dayTasks.map(task => {
             const startHour = task.start.getHours() + task.start.getMinutes()/60;
             const endHour = task.end.getHours() + task.end.getMinutes()/60;
             const top = (startHour - START_HOUR) * HOUR_HEIGHT;
             const height = (endHour - startHour) * HOUR_HEIGHT;
             return (
               <div key={task.id} onClick={() => handleOpenEdit(task)} className="absolute w-full p-1 z-20" style={{ top: `${top}px`, height: `${height}px` }}>
                 <div className={`h-full w-full rounded-2xl border p-4 shadow-lg flex flex-col justify-between overflow-hidden ${task.status === 'Confirmed' ? 'bg-blue-600 border-blue-500 text-white' : 'bg-red-600 border-red-500 text-white'}`}>
                   <div>
                     <h4 className="text-xs font-black leading-none truncate">{task.title}</h4>
                     <p className="text-[9px] font-bold opacity-70 uppercase mt-1 truncate">{task.customer}</p>
                   </div>
                   <p className="text-[8px] font-black uppercase text-right opacity-60">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</p>
                 </div>
               </div>
             );
           })}
        </div>
      </div>
    );
  };

  const renderWeekView = () => {
    const monday = getMonday(currentDate);
    const weekDays = Array.from({ length: 7 }).map((_, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      return d;
    });

    return (
      <div className="flex-1 overflow-y-auto no-scrollbar p-5 space-y-4 bg-slate-900">
        {weekDays.map((day, idx) => {
          const dayTasks = tasks.filter(t => isSameDay(t.start, day));
          const isToday = isSameDay(day, new Date());
          return (
            <div key={idx} className={`bg-slate-800 rounded-3xl p-5 border-2 transition-all ${isToday ? 'border-red-600 shadow-[0_0_20px_rgba(220,38,38,0.1)]' : 'border-slate-700'}`}>
              <div className="flex justify-between items-center mb-4">
                <div>
                  <h4 className={`text-sm font-black uppercase tracking-widest ${isToday ? 'text-red-500' : 'text-slate-100'}`}>
                    {day.toLocaleDateString('cs-CZ', { weekday: 'long' })}
                  </h4>
                  <p className="text-[10px] font-bold text-slate-500 mt-0.5">{day.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' })}</p>
                </div>
                {dayTasks.length > 0 && <span className="bg-slate-900 text-blue-400 text-[10px] font-black px-3 py-1 rounded-full border border-slate-700">{dayTasks.length} akce</span>}
              </div>

              <div className="space-y-2">
                {dayTasks.length > 0 ? dayTasks.map(task => (
                  <div key={task.id} onClick={() => handleOpenEdit(task)} className="bg-slate-900/50 p-3 rounded-xl border border-slate-700/50 flex items-center justify-between group cursor-pointer hover:bg-slate-900 transition-all">
                    <div className="flex items-center gap-3">
                      <div className={`w-1.5 h-1.5 rounded-full ${task.status === 'Confirmed' ? 'bg-blue-500' : 'bg-red-500'}`} />
                      <div>
                        <p className="text-xs font-bold text-slate-200 group-hover:text-blue-400 transition-colors">{task.title}</p>
                        <p className="text-[9px] text-slate-500 font-black uppercase">{task.customer}</p>
                      </div>
                    </div>
                    <span className="text-[10px] font-black text-slate-600">{task.start.getHours()}:{task.start.getMinutes().toString().padStart(2, '0')}</span>
                  </div>
                )) : (
                  <p className="text-[10px] text-slate-600 italic font-medium px-1">Žádné zakázky na tento den.</p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const getNavigationLabel = () => {
    if (viewMode === 'day') {
      return currentDate.toLocaleDateString('cs-CZ', { day: 'numeric', month: 'long' });
    } else {
      const monday = getMonday(currentDate);
      const sunday = new Date(monday);
      sunday.setDate(monday.getDate() + 6);
      return `${monday.getDate()}. - ${sunday.getDate()}. ${sunday.toLocaleDateString('cs-CZ', { month: 'long' })}`;
    }
  };

  return (
    <div className="space-y-6">
      {/* View Switcher */}
      <div className="flex items-center justify-between">
        <div className="flex bg-slate-900 p-1 rounded-2xl border border-slate-800 shadow-inner">
          <button 
            onClick={() => setViewMode('day')}
            className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'day' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Den
          </button>
          <button 
            onClick={() => setViewMode('week')}
            className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'week' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}
          >
            Týden
          </button>
        </div>
        {user.role === 'admin' && (
          <button onClick={handleOpenCreate} className="bg-red-600 text-white p-3 rounded-2xl shadow-xl shadow-red-600/30 active:scale-95 transition-all">
            <Icons.Plus />
          </button>
        )}
      </div>

      {/* Navigation */}
      <div className="bg-slate-800 rounded-[2rem] p-5 shadow-sm border border-slate-700 flex items-center justify-between">
        <button onClick={() => navigateDate('prev')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <div className="text-center">
          <p className="text-xs font-black text-slate-100 uppercase tracking-widest">
            {getNavigationLabel()}
          </p>
          {viewMode === 'day' && <p className="text-[10px] font-bold text-red-500 uppercase tracking-widest mt-0.5">{currentDate.toLocaleDateString('cs-CZ', { weekday: 'long' })}</p>}
          {viewMode === 'week' && <p className="text-[10px] font-bold text-blue-500 uppercase tracking-widest mt-0.5">Týdenní přehled</p>}
        </div>
        <button onClick={() => navigateDate('next')} className="p-3 text-slate-500 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
        </button>
      </div>

      {/* Main Content Area */}
      <div className="bg-slate-800 rounded-[3rem] shadow-sm border border-slate-700 overflow-hidden flex flex-col h-[600px] relative">
        {viewMode === 'day' ? renderDayView() : renderWeekView()}
      </div>

      {/* Task Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-lg z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-lg rounded-[32px] p-8 border border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar shadow-2xl">
            <h3 className="text-2xl font-black text-white mb-6 uppercase tracking-tighter">{isEditing ? 'Upravit zakázku' : 'Nová zakázka'}</h3>
            <div className="space-y-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Název akce</label>
                <input value={currentTask.title} onChange={e => setCurrentTask({...currentTask, title: e.target.value})} placeholder="např. Stěhování bytu 3+1" className="w-full bg-slate-800 rounded-xl p-4 text-white border-none font-bold" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Zákazník</label>
                    <input value={currentTask.customer} onChange={e => setCurrentTask({...currentTask, customer: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Telefon</label>
                    <input value={currentTask.customerPhone} onChange={e => setCurrentTask({...currentTask, customerPhone: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-sm text-white border-none" />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Začátek</label>
                    <input type="datetime-local" value={formatForInput(currentTask.start)} onChange={e => setCurrentTask({...currentTask, start: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-500 uppercase px-1">Konec</label>
                    <input type="datetime-local" value={formatForInput(currentTask.end)} onChange={e => setCurrentTask({...currentTask, end: new Date(e.target.value)})} className="w-full bg-slate-800 rounded-xl p-3 text-xs text-white border-none" />
                 </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Tým (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {workers.map(w => (
                     <button key={w.id} onClick={() => toggleResource(w.id, 'worker')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${currentTask.assignedWorkers?.includes(w.id) ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}>{w.name}</button>
                   ))}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Vozidla (kliknutím vyber)</label>
                <div className="flex flex-wrap gap-2">
                   {vehicles.map(v => (
                     <button key={v.id} onClick={() => toggleResource(v.id, 'vehicle')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${currentTask.assignedVehicles?.includes(v.id) ? 'bg-red-600 border-red-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}>{v.plate}</button>
                   ))}
                </div>
              </div>

              <div className="flex gap-4 pt-4">
                <button onClick={() => setShowModal(false)} className="flex-1 text-slate-500 font-black uppercase text-xs tracking-widest">Zrušit</button>
                <button onClick={saveTask} className="flex-[2] bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 uppercase text-xs tracking-widest">Uložit změny</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

