        <NavButton active={activeTab === AppTab.PROFILE} onClick={() => setActiveTab(AppTab.PROFILE)} icon={<Icons.User />} label="Profil" />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}

const NavButton: React.FC<NavButtonProps> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center justify-center gap-1.5 transition-all relative ${active ? 'text-blue-400' : 'text-slate-600'}`}
  >
    <div className={`transition-all duration-300 ${active ? 'scale-110 -translate-y-1' : 'scale-100'}`}>{icon}</div>
    <span className={`text-[9px] font-black uppercase tracking-wider transition-opacity duration-300 ${active ? 'opacity-100' : 'opacity-60'}`}>{label}</span>
    {active && <div className="absolute -bottom-1 w-1 h-1 bg-red-600 rounded-full" />}
  </button>
);

