              <Icons.Calendar />
            </div>
            <div className="relative z-10">
              <h2 className="text-sm font-black text-purple-300 uppercase tracking-widest mb-2">Plný potenciál na dosah</h2>
              <p className="text-slate-400 text-xs mb-5 max-w-xs mx-auto">Propojte aplikaci s vaším Google Kalendářem pro automatickou synchronizaci a plánování zakázek.</p>
              <button 
                onClick={onAuthorizeCalendar}
                className="bg-purple-600 text-white font-black py-3 px-8 rounded-2xl shadow-xl shadow-purple-600/20 transition-all active:scale-95 text-xs uppercase tracking-widest hover:bg-purple-500"
              >
                Propojit Kalendář
              </button>
            </div>
        </section>
      ) : (
        <section className="bg-green-600/10 border border-green-500/20 rounded-[3rem] p-4 animate-fade-in text-center flex items-center justify-center gap-3">
            <div className="w-8 h-8 bg-green-500/20 text-green-400 rounded-full flex items-center justify-center">
                ✓
            </div>
            <p className="text-xs font-black text-green-400 uppercase tracking-widest">
                Google Kalendář je propojen
            </p>
        </section>
      )}

      {/* Personalized Start Times */}
      <div className="grid grid-cols-2 gap-4">
        <StartCard 
          label="Tvůj dnešní start" 
          time={myTodayStartTask ? formatTime(myTodayStartTask.start) : '--:--'} 
          subtitle={myTodayStartTask?.title || 'Dnes nemáš zakázku'}
          color="red" 
        />
        <StartCard 
          label="Tvůj zítřejší start" 
          time={myTomorrowStartTask ? formatTime(myTomorrowStartTask.start) : '--:--'} 
          subtitle={myTomorrowStartTask?.title || 'Zítra nemáš zakázku'}
          color="blue" 
        />
      </div>

      {/* Tomorrow Morning Reminder Section (Admin/Global focus) */}
      {user.role === 'admin' && firstTaskTomorrowGlobal && (
        <section className="bg-blue-600/10 border border-blue-500/20 rounded-[3rem] p-6 animate-fade-in relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
            <Icons.Sparkles />
          </div>
