const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);
  const [user, setUser] = useState<AppUser | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const [isGsiLoaded, setIsGsiLoaded] = useState(false);
  const [isOriginAuthorized, setIsOriginAuthorized] = useState(true);
  const [currentOrigin, setCurrentOrigin] = useState('');

  const [tokenClient, setTokenClient] = useState<any>(null);
  const [isCalendarAuthorized, setIsCalendarAuthorized] = useState(false);

  const [workers, setWorkers] = useState<Worker[]>([
    { id: '1', name: 'Jan Novák', email: 'admin@stehovak2.com', phone: '777123456', role: 'Driver', status: 'Available' },
    { id: '2', name: 'Petr Svoboda', email: 'petr.svoboda@example.com', phone: '777654321', role: 'Loader', status: 'On Task' },
    { id: '3', name: 'Marek Kučera', email: 'marek.kucera@example.com', phone: '777987654', role: 'Loader', status: 'Available' },
  ]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([
    { id: '1', plate: '1AB 1234', model: 'Iveco Daily', capacity: '15m3', status: 'Ready' },
    { id: '2', plate: '2BC 5678', model: 'Mercedes Sprinter', capacity: '12m3', status: 'In Use' },
  ]);

  const [transactions, setTransactions] = useState<Transaction[]>([
    { id: 'tr1', type: 'income', amount: 4500, description: 'Zakázka #t1 - Karel D.', date: new Date(), userId: '1', userName: 'Jan Novák' },
    { id: 'tr2', type: 'expense', amount: 2100, description: 'PHM - Shell Praha 4', date: new Date(), userId: '1', userName: 'Jan Novák' },
  ]);

  const getTomorrow = () => {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    d.setHours(9, 0, 0, 0);
    return d;
  };

  const [tasks, setTasks] = useState<MoveTask[]>([
    {
      id: 't1',
      title: 'Stěhování bytu 2+kk',
      customer: 'Karel Dvořák',
      customerPhone: '+420 720 123 456',
      start: new Date(new Date().setHours(10, 0, 0, 0)),
      end: new Date(new Date().setHours(14, 0, 0, 0)),
      from: 'Praha 1',
      to: 'Praha 4',
      assignedWorkers: ['1', '2'],
      assignedVehicles: ['1'],
      status: 'Confirmed'
    },
    {
      id: 't2',
      title: 'Kanceláře "TechHub"',
      customer: 'Alena Modrá',
      customerPhone: '+420 603 444 555',
      start: getTomorrow(),
      end: new Date(getTomorrow().getTime() + 6 * 60 * 60 * 1000),
      from: 'Brno Střed',
      to: 'Ostrava - Poruba',
      assignedWorkers: ['3'],
      assignedVehicles: ['2'],
      status: 'Pending'
    }
  ]);

  useEffect(() => {
    const origin = window.location.origin;
    setCurrentOrigin(origin);
    // Zobrazí varování pouze pro ne-https (lokální vývoj) adresy, které nejsou v seznamu.
    if (!AUTHORIZED_ORIGINS.includes(origin) && window.location.protocol !== 'https:') {
        setIsOriginAuthorized(false);
    }
  }, []);

  const isClientIdValid = GOOGLE_CLIENT_ID && !GOOGLE_CLIENT_ID.startsWith('YOUR_') && !GOOGLE_CLIENT_ID.startsWith('VASE_') && GOOGLE_CLIENT_ID.endsWith('.apps.googleusercontent.com');

  const handleCredentialResponse = useCallback((response: any) => {
    const payload = decodeJwt(response.credential);
    if (payload) {
      const email = payload.email;
      const matchingWorker = workers.find(w => w.email?.toLowerCase() === email.toLowerCase());

      setUser({
        id: matchingWorker ? matchingWorker.id : 'user-' + Math.random().toString(36).substr(2, 4),
        name: payload.name || matchingWorker?.name || 'Uživatel Stěhovák',
        email: email,
        avatar: payload.picture || 'https://picsum.photos/seed/user/200/200',
        role: (matchingWorker?.id === '1' || email === 'admin@stehovak2.com') ? 'admin' : 'user',
        workerId: matchingWorker?.id
      });
      setAuthError(null);
    } else {
      setAuthError("Chyba při dekódování tokenu. Zkuste to znovu.");
    }
  }, [workers]);

  useEffect(() => {
    const initGsi = () => {
      // @ts-ignore
      if (window.google) {
        setIsGsiLoaded(true);
        if (isClientIdValid) {
            // @ts-ignore
            window.google.accounts.id.initialize({
              client_id: GOOGLE_CLIENT_ID,
              callback: handleCredentialResponse,
              auto_select: false,
              ux_mode: 'popup', 
              cancel_on_tap_outside: true,
            });

            const btnElement = document.getElementById("googleBtn");
            if (btnElement) {
              // @ts-ignore
              window.google.accounts.id.renderButton(
                btnElement,
                { 
                  theme: "filled_blue", 
                  size: "large", 
                  width: 280, 
                  shape: "pill", 
                  text: "signin_with", 
                  locale: "cs" 
                }
              );
            }
        }
      } else {
        setTimeout(initGsi, 200);
      }
    };

    if (!user) {
      initGsi();
    }
  }, [user, handleCredentialResponse, isClientIdValid]);

  // New useEffect for GAPI and OAuth Token Client, runs after user logs in
  useEffect(() => {
    if (!user || !isClientIdValid) return; // Wait for user login and valid client ID

    const initClients = () => {
      // @ts-ignore
      if (window.gapi && window.google) {
        // GAPI client
        // @ts-ignore
        gapi.load('client', () => {
          // @ts-ignore
          gapi.client.init({ discoveryDocs: [CALENDAR_DISCOVERY_DOC] });
        });

        // OAuth Token client
        // @ts-ignore
        const client = window.google.accounts.oauth2.initTokenClient({
          client_id: GOOGLE_CLIENT_ID,
          scope: CALENDAR_SCOPE,
          callback: (tokenResponse: any) => {
            if (tokenResponse && tokenResponse.access_token) {
              // @ts-ignore
              gapi.client.setToken(tokenResponse);
              setIsCalendarAuthorized(true);
            }
          },
          error_callback: (error: any) => {
            console.error('GAPI Auth Error:', error);
            // Ignorujeme chybu, pokud uživatel zavřel vyskakovací okno
            if (error.type === 'popup_closed') return;
            setAuthError("Chyba při propojování kalendáře. Zkuste to znovu.");
          }
        });
        setTokenClient(client);
      } else {
        setTimeout(initClients, 100);
      }
    };
    initClients();
  }, [user, isClientIdValid]);

  const handleAuthorizeCalendar = () => {
    if (tokenClient) {
      // Použijeme 'consent' pro vynucení souhlasu, což je bezpečnější pro explicitní akci uživatele.
      // Odstranili jsme nevalidní prompt: '', který způsoboval chyby.
      tokenClient.requestAccessToken({ prompt: 'consent' });
    }
  };

  const handleManualLogin = () => {
    setUser({
      id: '1',
      name: 'Jan Novák (Demo)',
      email: 'admin@stehovak2.com',
      avatar: 'https://picsum.photos/seed/admin/200/200',
      role: 'admin',
      workerId: '1'
    });
  };

  const getTabLabel = (tab: AppTab) => {
    switch (tab) {
      case AppTab.DASHBOARD: return 'PŘEHLED';
      case AppTab.CALENDAR: return 'KALENDÁŘ';
      case AppTab.FLEET: return 'FLOTILA';
      case AppTab.AI_LAB: return 'AI LABORATOŘ';
      case AppTab.PROFILE: return 'PROFIL';
      default: return '';
    }
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white animate-fade-in relative overflow-hidden">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-blue-600/10 rounded-full blur-[120px] pointer-events-none" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-red-600/10 rounded-full blur-[120px] pointer-events-none" />

        <div className="w-28 h-28 bg-blue-600 rounded-[35px] mb-8 flex items-center justify-center shadow-[0_20px_50px_rgba(59,130,246,0.3)] text-white transform rotate-3 relative z-10">
          <div className="transform -rotate-3 scale-125"><Icons.Truck /></div>
        </div>

        <h1 className="text-4xl font-black mb-2 tracking-tighter relative z-10">Stěhovák <span className="text-red-500">2.0</span></h1>
        <p className="text-slate-400 mb-12 text-center font-medium max-w-[250px] relative z-10">
          Logistický systém pro moderní týmy.
        </p>

        <div className="space-y-4 w-full max-w-[280px] relative z-10 flex flex-col items-center">
          {!isOriginAuthorized && (
            <div className="w-full text-center p-5 bg-purple-500/10 border border-purple-500/20 rounded-3xl">
              <p className="text-purple-400 text-xs font-black uppercase tracking-widest">NEAUTORIZOVANÝ PŮVOD</p>
              <p className="text-slate-300 text-sm mt-3 font-bold">
                  Váš původ <code className="bg-slate-700/50 text-purple-300 px-1.5 py-0.5 rounded-md font-mono text-xs">{currentOrigin}</code> není rozpoznán.
              </p>
              <p className="text-slate-400 text-[11px] mt-2 leading-relaxed">
                  Přidejte tuto URL do "Autorizovaných JavaScript zdrojů" ve vaší Google Cloud Console a do pole <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">AUTHORIZED_ORIGINS</code> v <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">App.tsx</code>.
              </p>
            </div>
          )}

          {!isClientIdValid ? (
            <div className="w-full text-center p-5 bg-yellow-500/10 border border-yellow-500/20 rounded-3xl">
              <p className="text-yellow-400 text-xs font-black uppercase tracking-widest">AKCE VYŽADOVÁNA</p>
              <p className="text-slate-300 text-sm mt-3 font-bold">
                  Nastavte Google Client ID
              </p>
              <p className="text-slate-400 text-[11px] mt-2 leading-relaxed">
                  Pro aktivaci přihlášení vložte Váš klíč do souboru <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">App.tsx</code>. Klíč musí končit na <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">.apps.googleusercontent.com</code>.
              </p>
              <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer" className="text-blue-400 text-xs font-bold mt-4 inline-block hover:underline">
                  Získat Client ID v Google Cloud Console &rarr;
              </a>
            </div>
          ) : (
            <div id="googleBtn" className="min-h-[44px]"></div>
          )}

          <button 
            onClick={handleManualLogin}
            className="text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-slate-300 transition-colors py-2"
          >
            Vstoupit v demo režimu
          </button>
        </div>

        {authError && (
          <div className="mt-8 px-4 py-3 bg-red-500/10 border border-red-500/20 rounded-2xl animate-slide-up relative z-10">
            <p className="text-red-500 text-[10px] font-black uppercase tracking-widest text-center">
              {authError}
            </p>
          </div>
        )}

        <div className="absolute bottom-12 text-center w-full">
           <p className="text-[10px] text-slate-700 font-black uppercase tracking-[0.4em]">Premium Logistics Core</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col w-full md:max-w-6xl mx-auto shadow-2xl overflow-hidden relative border-x border-slate-800">
      <header className="bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 p-5 sticky top-0 z-40 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-600/20">
            <Icons.Truck />
          </div>
          <div>
            <h1 className="text-lg font-black text-white leading-none">Stěhovák <span className="text-red-500">2.0</span></h1>
            <p className="text-[9px] text-red-500 font-black tracking-widest mt-0.5">{getTabLabel(activeTab)}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-2xl overflow-hidden border-2 border-slate-700 shadow-md">
            <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
        <div className="absolute bottom-0 left-0 w-full h-[2px] flex">
          <div className="h-full w-1/3 bg-blue-600"></div>
          <div className="h-full w-1/3 bg-slate-200"></div>
          <div className="h-full w-1/3 bg-red-600"></div>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto no-scrollbar p-5 pb-32">
        {activeTab === AppTab.DASHBOARD && <Dashboard tasks={tasks} workers={workers} vehicles={vehicles} user={user} isCalendarAuthorized={isCalendarAuthorized} onAuthorizeCalendar={handleAuthorizeCalendar} />}
        {activeTab === AppTab.CALENDAR && <CalendarView tasks={tasks} setTasks={setTasks} workers={workers} vehicles={vehicles} user={user} />}
        {activeTab === AppTab.FLEET && <FleetView workers={workers} setWorkers={setWorkers} vehicles={vehicles} setVehicles={setVehicles} />}
        {activeTab === AppTab.AI_LAB && <AILab />}
        {activeTab === AppTab.PROFILE && <Profile user={user} onLogout={() => setUser(null)} transactions={transactions} setTransactions={setTransactions} />}
      </main>

      <nav className="bg-slate-900/95 backdrop-blur-2xl border-t border-slate-800 fixed bottom-0 left-0 right-0 w-full md:max-w-6xl mx-auto z-40 flex justify-around p-4 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] rounded-t-[35px]">
        <NavButton active={activeTab === AppTab.DASHBOARD} onClick={() => setActiveTab(AppTab.DASHBOARD)} icon={<Icons.Home />} label="Domů" />
        <NavButton active={activeTab === AppTab.CALENDAR} onClick={() => setActiveTab(AppTab.CALENDAR)} icon={<Icons.Calendar />} label="Kalendář" />
        <NavButton active={activeTab === AppTab.FLEET} onClick={() => setActiveTab(AppTab.FLEET)} icon={<Icons.Truck />} label="Flotila" />
        <NavButton active={activeTab === AppTab.AI_LAB} onClick={() => setActiveTab(AppTab.AI_LAB)} icon={<Icons.Sparkles />} label="AI Lab" />
        <NavButton active={activeTab === AppTab.PROFILE} onClick={() => setActiveTab(AppTab.PROFILE)} icon={<Icons.User />} label="Profil" />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}

const NavButton: React.FC<NavButtonProps> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className="flex flex-col items-center justify-center gap-1.5 transition-all relative"
  >
    <div className={`transition-all duration-300 ${active ? 'scale-110 -translate-y-1 text-blue-400' : 'scale-100 text-white'}`}>
      {icon}
    </div>
    <span className={`text-[9px] font-black uppercase tracking-wider transition-opacity duration-300 ${active ? 'opacity-100 text-blue-400' : 'opacity-60 text-slate-400'}`}>
      {label}
    </span>
    {active && <div className="absolute -bottom-1 w-1 h-1 bg-blue-600 rounded-full" />}
  </button>
);

export default App;

import React, { useState } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
  user: {
    workerId?: string;
    role: 'admin' | 'user';
  };
  isCalendarAuthorized: boolean;
  onAuthorizeCalendar: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles, user, isCalendarAuthorized, onAuthorizeCalendar }) => {
  const [selectedTask, setSelectedTask] = useState<MoveTask | null>(null);

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  const isTomorrow = (date: Date) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return date.getDate() === tomorrow.getDate() &&
      date.getMonth() === tomorrow.getMonth() &&
      date.getFullYear() === tomorrow.getFullYear();
  };

  // Logic for "My assigned tasks" specifically for the top start cards
  const myAssignedTasks = user.workerId 
    ? tasks.filter(t => t.assignedWorkers.includes(user.workerId!))
    : [];

  const myTodayStartTask = [...myAssignedTasks]
    .filter(t => isToday(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const myTomorrowStartTask = [...myAssignedTasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  // Logic for lists (Admins see all, users see assigned)
  const myTasksForList = user.role === 'admin' 
    ? tasks 
    : tasks.filter(t => t.assignedWorkers.includes(user.workerId || ''));

  const todayTasks = myTasksForList.filter(t => isToday(t.start));
  const tomorrowTasks = myTasksForList.filter(t => isTomorrow(t.start));

  // Find the company's first task for tomorrow (for the notification section)
  const firstTaskTomorrowGlobal = [...tasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const sendNotification = (type: 'whatsapp' | 'sms', task: MoveTask) => {
    const timeStr = `${task.start.getHours()}:${task.start.getMinutes().toString().padStart(2, '0')}`;
    const message = `Stěhovák 2.0: Připomínka zítřejšího startu. První zakázka '${task.title}' začíná v ${timeStr}. Buďte připraveni!`;
    const encodedMsg = encodeURIComponent(message);

    if (type === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');
    } else {
      window.location.href = `sms:?body=${encodedMsg}`;
    }
  };

  const formatTime = (date: Date) => {
    return `${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`;
  };

  // Fix: Explicitly define TaskCardProps to resolve TypeScript error with the 'key' prop in lists.
  interface TaskCardProps {
    task: MoveTask;
  }

  // FIX: Explicitly type TaskCard as a React.FC to ensure TypeScript recognizes it as a component that can accept a 'key' prop.
  const TaskCard: React.FC<TaskCardProps> = ({ task }) => (
    <div 
      onClick={() => setSelectedTask(task)}
      className="bg-slate-800 p-5 rounded-[2.5rem] shadow-sm border border-slate-700 flex items-center gap-5 hover:bg-slate-700 hover:border-blue-500/30 transition-all cursor-pointer active:scale-[0.98] group"
    >
      <div className="flex flex-col items-center justify-center bg-slate-900 group-hover:bg-blue-600 group-hover:text-white rounded-[2rem] p-4 min-w-[75px] transition-colors duration-300 text-slate-400">
        <span className="font-black text-xl leading-none group-hover:text-white transition-colors">
          {task.start.getHours()}
        </span>
        <span className="text-[10px] font-black opacity-40 uppercase mt-1">HOD</span>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-black text-slate-100 text-base leading-tight group-hover:text-blue-400 transition-colors">{task.title}</h3>
        <p className="text-xs text-slate-400 font-bold mt-1 uppercase tracking-tight">{task.customer}</p>
        <div className="flex items-center gap-2 mt-2">
          <div className="flex -space-x-2">
            {task.assignedWorkers.slice(0, 3).map((_, i) => (
              <div key={i} className="w-5 h-5 rounded-full bg-slate-700 border-2 border-slate-800 flex items-center justify-center text-[8px] font-black text-blue-400"><Icons.User /></div>
            ))}
          </div>
          <span className="text-[10px] text-slate-500 font-bold truncate">
            {task.from}
          </span>
        </div>
      </div>

      <div className={`w-3 h-3 rounded-full shadow-[0_0_10px_rgba(0,0,0,0.5)] ${
        task.status === 'Confirmed' ? 'bg-blue-500' : 
        task.status === 'In Progress' ? 'bg-red-500 animate-pulse' : 'bg-slate-600'
      }`} />
    </div>
  );

  return (
    <div className="space-y-10">
      {/* Calendar Authorization Section */}
      {!isCalendarAuthorized ? (
        <section className="bg-purple-600/10 border border-purple-500/20 rounded-[3rem] p-6 animate-fade-in relative overflow-hidden text-center">
            <div className="absolute -top-4 -right-4 p-8 opacity-5 pointer-events-none text-purple-400">
              <Icons.Calendar />
            </div>
            <div className="relative z-10">
              <h2 className="text-sm font-black text-purple-300 uppercase tracking-widest mb-2">Plný potenciál na dosah</h2>
              <p className="text-slate-400 text-xs mb-5 max-w-xs mx-auto">Propojte aplikaci s vaším Google Kalendářem pro automatickou synchronizaci a plánování zakázek.</p>
              <button 
                onClick={onAuthorizeCalendar}
                className="bg-purple-600 text-white font-black py-3 px-8 rounded-2xl shadow-xl shadow-purple-600/20 transition-all active:scale-95 text-xs uppercase tracking-widest hover:bg-purple-500"
              >
                Propojit Kalendář
              </button>
            </div>
        </section>
      ) : (
        <section className="bg-green-600/10 border border-green-500/20 rounded-[3rem] p-4 animate-fade-in text-center flex items-center justify-center gap-3">
            <div className="w-8 h-8 bg-green-500/20 text-green-400 rounded-full flex items-center justify-center">
                ✓
            </div>
            <p className="text-xs font-black text-green-400 uppercase tracking-widest">
                Google Kalendář je propojen
            </p>
        </section>
      )}

      {/* Personalized Start Times */}
      <div className="grid grid-cols-2 gap-4">
        <StartCard 
          label="Tvůj dnešní start" 
          time={myTodayStartTask ? formatTime(myTodayStartTask.start) : '--:--'} 
          subtitle={myTodayStartTask?.title || 'Dnes nemáš zakázku'}
          color="red" 
        />
        <StartCard 
          label="Tvůj zítřejší start" 
          time={myTomorrowStartTask ? formatTime(myTomorrowStartTask.start) : '--:--'} 
          subtitle={myTomorrowStartTask?.title || 'Zítra nemáš zakázku'}
          color="blue" 
        />
      </div>

      {/* Tomorrow Morning Reminder Section (Admin/Global focus) */}
      {user.role === 'admin' && firstTaskTomorrowGlobal && (
        <section className="bg-blue-600/10 border border-blue-500/20 rounded-[3rem] p-6 animate-fade-in relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
            <Icons.Sparkles />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4">
               <span className="w-2 h-2 bg-blue-400 rounded-full animate-pulse shadow-[0_0_8px_#60a5fa]" />
               <h2 className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Zítřejší ranní start (Firma)</h2>
            </div>
            <div className="flex items-end justify-between">
               <div>
