          setApiKeySelected(true);
          setCheckingApiKey(false);
      }
  };

  const isClientIdValid = GOOGLE_CLIENT_ID && !GOOGLE_CLIENT_ID.startsWith('YOUR_') && !GOOGLE_CLIENT_ID.startsWith('VASE_') && GOOGLE_CLIENT_ID.endsWith('.apps.googleusercontent.com');

  const handleCredentialResponse = useCallback((response: any) => {
    const payload = decodeJwt(response.credential);
    if (payload) {
      const email = payload.email;
      const matchingWorker = workers.find(w => w.email?.toLowerCase() === email.toLowerCase());

      setUser({
        id: matchingWorker ? matchingWorker.id : 'user-' + Math.random().toString(36).substr(2, 4),
        name: payload.name || matchingWorker?.name || 'Uživatel Stěhovák',
        email: email,
        avatar: payload.picture || 'https://picsum.photos/seed/user/200/200',
        role: (matchingWorker?.id === '1' || email === 'admin@stehovak2.com') ? 'admin' : 'user',
        workerId: matchingWorker?.id
      });
      setAuthError(null);
    } else {
      setAuthError("Chyba při dekódování tokenu. Zkuste to znovu.");
    }
  }, [workers]);

  useEffect(() => {
    const initGsi = () => {
      // @ts-ignore
      if (window.google) {
        setIsGsiLoaded(true);
        if (isClientIdValid) {
            // @ts-ignore
            window.google.accounts.id.initialize({
              client_id: GOOGLE_CLIENT_ID,
              callback: handleCredentialResponse,
              auto_select: false,
              ux_mode: 'popup', 
              cancel_on_tap_outside: true,
            });

            const btnElement = document.getElementById("googleBtn");
            if (btnElement) {
              // @ts-ignore
              window.google.accounts.id.renderButton(
                btnElement,
                { 
                  theme: "filled_blue", 
                  size: "large", 
                  width: 280, 
                  shape: "pill", 
                  text: "signin_with", 
                  locale: "cs" 
                }
              );
            }
        }
      } else {
        setTimeout(initGsi, 200);
      }
    };

    if (!user && apiKeySelected) {
      initGsi();
    }
  }, [user, apiKeySelected, handleCredentialResponse, isClientIdValid]);

  // New useEffect for GAPI and OAuth Token Client, runs after user logs in
  useEffect(() => {
    if (!user || !isClientIdValid) return; // Wait for user login and valid client ID

    const initClients = () => {
      // @ts-ignore
      if (window.gapi && window.google) {
        // GAPI client
        // @ts-ignore
        gapi.load('client', () => {
          // @ts-ignore
          gapi.client.init({ discoveryDocs: [CALENDAR_DISCOVERY_DOC] });
        });

        // OAuth Token client
        // @ts-ignore
        const client = window.google.accounts.oauth2.initTokenClient({
          client_id: GOOGLE_CLIENT_ID,
          scope: CALENDAR_SCOPE,
          callback: (tokenResponse: any) => {
            if (tokenResponse && tokenResponse.access_token) {
              // @ts-ignore
              gapi.client.setToken(tokenResponse);
              setIsCalendarAuthorized(true);
              setAuthError(null);
            }
          },
          error_callback: (error: any) => {
            console.error('GAPI Auth Error:', error);
            if (error.type === 'popup_closed') return;

            if (error.error === 'invalid_client') {
              setAuthError("Chyba 401: Klient OAuth nebyl nalezen. Zkontrolujte, zda je Google Client ID v App.tsx správné a odpovídá platnému 'Web application' ID ve vaší Google Cloud Console.");
            } else {
              setAuthError("Chyba při propojování kalendáře. Zkuste to znovu.");
            }
          }
        });
        setTokenClient(client);
      } else {
        setTimeout(initClients, 100);
      }
    };
    initClients();
  }, [user, isClientIdValid]);

  const handleAuthorizeCalendar = () => {
    if (tokenClient) {
