        setApiKeySelected(true); 
      }
      setCheckingApiKey(false);
    };
    // Use a timeout to ensure aistudio is loaded
    setTimeout(checkKey, 500);

    // Origin Check
    const origin = window.location.origin;
    setCurrentOrigin(origin);
    // Zobrazí varování pouze pro ne-https (lokální vývoj) adresy, které nejsou v seznamu.
    if (!AUTHORIZED_ORIGINS.includes(origin) && window.location.protocol !== 'https:') {
        setIsOriginAuthorized(false);
    }
  }, []);

  const handleSelectApiKey = async () => {
      // @ts-ignore
      if (window.aistudio) {
          // @ts-ignore
          await window.aistudio.openSelectKey();
          // Optimistically set to true to avoid race condition and proceed
          setApiKeySelected(true);
          setCheckingApiKey(false);
      }
  };

  const isClientIdValid = GOOGLE_CLIENT_ID && !GOOGLE_CLIENT_ID.startsWith('YOUR_') && !GOOGLE_CLIENT_ID.startsWith('VASE_') && GOOGLE_CLIENT_ID.endsWith('.apps.googleusercontent.com');

  const handleCredentialResponse = useCallback((response: any) => {
    const payload = decodeJwt(response.credential);
    if (payload) {
      const email = payload.email;
      const matchingWorker = workers.find(w => w.email?.toLowerCase() === email.toLowerCase());

      setUser({
        id: matchingWorker ? matchingWorker.id : 'user-' + Math.random().toString(36).substr(2, 4),
        name: payload.name || matchingWorker?.name || 'Uživatel Stěhovák',
        email: email,
        avatar: payload.picture || 'https://picsum.photos/seed/user/200/200',
        role: (matchingWorker?.id === '1' || email === 'admin@stehovak2.com') ? 'admin' : 'user',
        workerId: matchingWorker?.id
      });
      setAuthError(null);
    } else {
      setAuthError("Chyba při dekódování tokenu. Zkuste to znovu.");
    }
  }, [workers]);

  useEffect(() => {
    const initGsi = () => {
      // @ts-ignore
      if (window.google) {
        setIsGsiLoaded(true);
        if (isClientIdValid) {
            // @ts-ignore
            window.google.accounts.id.initialize({
              client_id: GOOGLE_CLIENT_ID,
              callback: handleCredentialResponse,
              auto_select: false,
              ux_mode: 'popup', 
              cancel_on_tap_outside: true,
            });

            const btnElement = document.getElementById("googleBtn");
            if (btnElement) {
              // @ts-ignore
              window.google.accounts.id.renderButton(
                btnElement,
                { 
                  theme: "filled_blue", 
                  size: "large", 
                  width: 280, 
                  shape: "pill", 
                  text: "signin_with", 
                  locale: "cs" 
                }
              );
            }
        }
      } else {
        setTimeout(initGsi, 200);
      }
    };

    if (!user && apiKeySelected) {
      initGsi();
    }
  }, [user, apiKeySelected, handleCredentialResponse, isClientIdValid]);

  // New useEffect for GAPI and OAuth Token Client, runs after user logs in
  useEffect(() => {
    if (!user || !isClientIdValid) return; // Wait for user login and valid client ID

    const initClients = () => {
      // @ts-ignore
      if (window.gapi && window.google) {
        // GAPI client
        // @ts-ignore
        gapi.load('client', () => {
          // @ts-ignore
          gapi.client.init({ discoveryDocs: [CALENDAR_DISCOVERY_DOC] });
        });

        // OAuth Token client
        // @ts-ignore
        const client = window.google.accounts.oauth2.initTokenClient({
          client_id: GOOGLE_CLIENT_ID,
          scope: CALENDAR_SCOPE,
          callback: (tokenResponse: any) => {
            if (tokenResponse && tokenResponse.access_token) {
              // @ts-ignore
              gapi.client.setToken(tokenResponse);
              setIsCalendarAuthorized(true);
              setAuthError(null);
            }
          },
          error_callback: (error: any) => {
            console.error('GAPI Auth Error:', error);
            if (error.type === 'popup_closed') return;

            if (error.error === 'invalid_client') {
              setAuthError("Chyba 401: Klient OAuth nebyl nalezen. Zkontrolujte, zda je Google Client ID v App.tsx správné a odpovídá platnému 'Web application' ID ve vaší Google Cloud Console.");
            } else {
              setAuthError("Chyba při propojování kalendáře. Zkuste to znovu.");
            }
          }
        });
        setTokenClient(client);
      } else {
        setTimeout(initClients, 100);
      }
    };
    initClients();
  }, [user, isClientIdValid]);

  const handleAuthorizeCalendar = () => {
    if (tokenClient) {
      tokenClient.requestAccessToken({ prompt: 'consent' });
    }
  };

  const handleManualLogin = () => {
    setUser({
      id: '1',
      name: 'Jan Novák (Demo)',
      email: 'admin@stehovak2.com',
      avatar: 'https://picsum.photos/seed/admin/200/200',
      role: 'admin',
      workerId: '1'
    });
  };

  const getTabLabel = (tab: AppTab) => {
    switch (tab) {
      case AppTab.DASHBOARD: return 'PŘEHLED';
      case AppTab.CALENDAR: return 'KALENDÁŘ';
      case AppTab.FLEET: return 'FLOTILA';
      case AppTab.AI_LAB: return 'AI LABORATOŘ';
      case AppTab.PROFILE: return 'PROFIL';
      default: return '';
    }
  };

  if (checkingApiKey) {
    return (
        <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center">
            <div className="w-8 h-8 border-4 border-blue-400 border-t-transparent rounded-full animate-spin"></div>
        </div>
    );
  }

  if (!apiKeySelected) {
    return (
      <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white text-center">
        <div className="w-28 h-28 bg-blue-600 rounded-[35px] mb-8 flex items-center justify-center shadow-[0_20px_50px_rgba(59,130,246,0.3)] text-white">
            <Icons.Sparkles />
        </div>
        <h1 className="text-3xl font-black mb-2">Vyžadován API Klíč</h1>
        <p className="text-slate-400 mb-8 max-w-sm">
            Pro generování obrázků s prémiovým modelem je nutné vybrat Váš vlastní API klíč z placeného Google Cloud projektu.
        </p>
        <button 
            onClick={handleSelectApiKey}
            className="bg-blue-600 text-white font-black py-4 px-8 rounded-2xl shadow-xl shadow-blue-600/20 transition-all active:scale-95 text-sm uppercase tracking-widest hover:bg-blue-500"
        >
            Vybrat API klíč
        </button>
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-400 text-xs font-bold mt-6 hover:underline">
            Více o zpoplatnění &rarr;
          </a>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white animate-fade-in relative overflow-hidden">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-blue-600/10 rounded-full blur-[120px] pointer-events-none" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-red-600/10 rounded-full blur-[120px] pointer-events-none" />

        <div className="w-28 h-28 bg-blue-600 rounded-[35px] mb-8 flex items-center justify-center shadow-[0_20px_50px_rgba(59,130,246,0.3)] text-white transform rotate-3 relative z-10">
          <div className="transform -rotate-3 scale-125"><Icons.Truck /></div>
        </div>

        <h1 className="text-4xl font-black mb-2 tracking-tighter relative z-10">Stěhovák <span className="text-red-500">2.0</span></h1>
        <p className="text-slate-400 mb-12 text-center font-medium max-w-[250px] relative z-10">
          Logistický systém pro moderní týmy.
        </p>

        <div className="space-y-4 w-full max-w-[280px] relative z-10 flex flex-col items-center">
          {!isOriginAuthorized && (
            <div className="w-full text-center p-5 bg-purple-500/10 border border-purple-500/20 rounded-3xl">
              <p className="text-purple-400 text-xs font-black uppercase tracking-widest">NEAUTORIZOVANÝ PŮVOD</p>
              <p className="text-slate-300 text-sm mt-3 font-bold">
                  Váš původ <code className="bg-slate-700/50 text-purple-300 px-1.5 py-0.5 rounded-md font-mono text-xs">{currentOrigin}</code> není rozpoznán.
              </p>
              <p className="text-slate-400 text-[11px] mt-2 leading-relaxed">
                  Přidejte tuto URL do "Autorizovaných JavaScript zdrojů" ve vaší Google Cloud Console a do pole <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">AUTHORIZED_ORIGINS</code> v <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">App.tsx</code>.
              </p>
            </div>
          )}

          {!isClientIdValid ? (
            <div className="w-full text-center p-5 bg-yellow-500/10 border border-yellow-500/20 rounded-3xl">
              <p className="text-yellow-400 text-xs font-black uppercase tracking-widest">AKCE VYŽADOVÁNA</p>
              <p className="text-slate-300 text-sm mt-3 font-bold">
                  Nastavte Google Client ID
              </p>
              <p className="text-slate-400 text-[11px] mt-2 leading-relaxed">
                  Pro aktivaci přihlášení vložte Váš klíč do souboru <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">App.tsx</code>. Klíč musí končit na <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">.apps.googleusercontent.com</code>.
              </p>
              <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer" className="text-blue-400 text-xs font-bold mt-4 inline-block hover:underline">
                  Získat Client ID v Google Cloud Console &rarr;
              </a>
            </div>
          ) : (
            <div id="googleBtn" className="min-h-[44px]"></div>
          )}

          <button 
            onClick={handleManualLogin}
            className="text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-slate-300 transition-colors py-2"
          >
            Vstoupit v demo režimu
          </button>
        </div>

        {authError && (
          <div className="mt-8 px-4 py-3 bg-red-500/10 border border-red-500/20 rounded-2xl animate-slide-up relative z-10">
            <p className="text-red-500 text-[10px] font-black uppercase tracking-widest text-center">
              {authError}
            </p>
          </div>
        )}

        <div className="absolute bottom-12 text-center w-full">
           <p className="text-[10px] text-slate-700 font-black uppercase tracking-[0.4em]">Premium Logistics Core</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col w-full md:max-w-6xl mx-auto shadow-2xl overflow-hidden relative border-x border-slate-800">
      <header className="bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 p-5 sticky top-0 z-40 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-600/20">
            <Icons.Truck />
          </div>
          <div>
            <h1 className="text-lg font-black text-white leading-none">Stěhovák <span className="text-red-500">2.0</span></h1>
            <p className="text-[9px] text-red-500 font-black tracking-widest mt-0.5">{getTabLabel(activeTab)}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-2xl overflow-hidden border-2 border-slate-700 shadow-md">
            <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
        <div className="absolute bottom-0 left-0 w-full h-[2px] flex">
          <div className="h-full w-1/3 bg-blue-600"></div>
          <div className="h-full w-1/3 bg-slate-200"></div>
          <div className="h-full w-1/3 bg-red-600"></div>
        </div>
      </header>

      {authError && (
        <div className="p-4 bg-red-600/10 border-b border-red-500/20 text-center text-red-400 text-xs font-bold relative">
          <p className="pr-8">{authError}</p>
          <button onClick={() => setAuthError(null)} className="absolute top-1/2 right-4 -translate-y-1/2 text-red-400/50 hover:text-red-400 font-black text-xl">&times;</button>
        </div>
      )}

      <main className="flex-1 overflow-y-auto no-scrollbar p-5 pb-32">
        {activeTab === AppTab.DASHBOARD && <Dashboard tasks={tasks} workers={workers} vehicles={vehicles} user={user} isCalendarAuthorized={isCalendarAuthorized} onAuthorizeCalendar={handleAuthorizeCalendar} />}
        {activeTab === AppTab.CALENDAR && <CalendarView tasks={tasks} setTasks={setTasks} workers={workers} vehicles={vehicles} user={user} />}
        {activeTab === AppTab.FLEET && <FleetView workers={workers} setWorkers={setWorkers} vehicles={vehicles} setVehicles={setVehicles} />}
        {activeTab === AppTab.AI_LAB && <AILab />}
        {activeTab === AppTab.PROFILE && <Profile user={user} onLogout={() => setUser(null)} transactions={transactions} setTransactions={setTransactions} />}
      </main>

      <nav className="bg-slate-900/95 backdrop-blur-2xl border-t border-slate-800 fixed bottom-0 left-0 right-0 w-full md:max-w-6xl mx-auto z-40 flex justify-around p-4 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] rounded-t-[35px]">
        <NavButton active={activeTab === AppTab.DASHBOARD} onClick={() => setActiveTab(AppTab.DASHBOARD)} icon={<Icons.Home />} label="Domů" />
        <NavButton active={activeTab === AppTab.CALENDAR} onClick={() => setActiveTab(AppTab.CALENDAR)} icon={<Icons.Calendar />} label="Kalendář" />
        <NavButton active={activeTab === AppTab.FLEET} onClick={() => setActiveTab(AppTab.FLEET)} icon={<Icons.Truck />} label="Flotila" />
        <NavButton active={activeTab === AppTab.AI_LAB} onClick={() => setActiveTab(AppTab.AI_LAB)} icon={<Icons.Sparkles />} label="AI Lab" />
        <NavButton active={activeTab === AppTab.PROFILE} onClick={() => setActiveTab(AppTab.PROFILE)} icon={<Icons.User />} label="Profil" />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}

const NavButton: React.FC<NavButtonProps> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className="flex flex-col items-center justify-center gap-1.5 transition-all relative"
  >
    <div className={`transition-all duration-300 ${active ? 'scale-110 -translate-y-1 text-blue-400' : 'scale-100 text-white'}`}>
      {icon}
    </div>
    <span className={`text-[9px] font-black uppercase tracking-wider transition-opacity duration-300 ${active ? 'opacity-100 text-blue-400' : 'opacity-60 text-slate-400'}`}>
      {label}
    </span>
    {active && <div className="absolute -bottom-1 w-1 h-1 bg-blue-600 rounded-full" />}
  </button>
);

export default App;

import React, { useState, useRef } from 'react';
import { Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface FleetViewProps {
  workers: Worker[];
  setWorkers: React.Dispatch<React.SetStateAction<Worker[]>>;
  vehicles: Vehicle[];
  setVehicles: React.Dispatch<React.SetStateAction<Vehicle[]>>;
}

const FleetView: React.FC<FleetViewProps> = ({ workers, setWorkers, vehicles, setVehicles }) => {
  const [activeSubTab, setActiveSubTab] = useState<'workers' | 'vehicles'>('workers');

  // Modal states
  const [showVehicleModal, setShowVehicleModal] = useState(false);
  const [selectedVehicle, setSelectedVehicle] = useState<Partial<Vehicle> | null>(null);
  const [showWorkerModal, setShowWorkerModal] = useState(false);
  const [selectedWorker, setSelectedWorker] = useState<Partial<Worker> | null>(null);

  const carImageRef = useRef<HTMLInputElement>(null);
  const techCertImageRef = useRef<HTMLInputElement>(null);
  const workerPhotoRef = useRef<HTMLInputElement>(null);

  const getRoleLabel = (role: string) => {
    switch(role) {
      case 'Driver': return 'Řidič';
      case 'Loader': return 'Stěhovák';
      case 'Specialist': return 'Specialista';
      default: return role;
    }
  };

  const getStatusLabel = (status: string) => {
    switch(status) {
      case 'Available': return 'Volný';
      case 'On Task': return 'Na zakázce';
      case 'Off': return 'Mimo';
      case 'Ready': return 'Připraven';
      case 'In Use': return 'V provozu';
      case 'Maintenance': return 'Servis';
      default: return status;
    }
  };

  // Handlers
  const handleOpenWorker = (w: Worker) => { setSelectedWorker({...w}); setShowWorkerModal(true); };
  const handleAddWorker = () => { setSelectedWorker({ name: '', role: 'Loader', status: 'Available', phone: '' }); setShowWorkerModal(true); };

  const handleOpenVehicle = (v: Vehicle) => { setSelectedVehicle({...v}); setShowVehicleModal(true); };
  const handleAddVehicle = () => { setSelectedVehicle({ plate: '', model: '', status: 'Ready', capacity: '' }); setShowVehicleModal(true); };

  const saveWorker = () => {
    if (!selectedWorker) return;
    if (selectedWorker.id) {
      setWorkers(workers.map(w => w.id === selectedWorker.id ? selectedWorker as Worker : w));
    } else {
      setWorkers([...workers, { ...selectedWorker as Worker, id: Math.random().toString(36).substr(2, 9) }]);
    }
    setShowWorkerModal(false);
  };

  const saveVehicle = () => {
    if (!selectedVehicle) return;
    if (selectedVehicle.id) {
      setVehicles(vehicles.map(v => v.id === selectedVehicle.id ? selectedVehicle as Vehicle : v));
    } else {
      setVehicles([...vehicles, { ...selectedVehicle as Vehicle, id: Math.random().toString(36).substr(2, 9) }]);
    }
    setShowVehicleModal(false);
  };

  const handleImage = (e: React.ChangeEvent<HTMLInputElement>, type: 'photo' | 'car' | 'tech') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        if (type === 'photo') setSelectedWorker(p => ({...p, photo: base64}));
        if (type === 'car') setSelectedVehicle(p => ({...p, carImage: base64}));
        if (type === 'tech') setSelectedVehicle(p => ({...p, techCertImage: base64}));
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-900 p-1 rounded-2xl flex border border-slate-800">
        <button onClick={() => setActiveSubTab('workers')} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${activeSubTab === 'workers' ? 'bg-blue-600 text-white' : 'text-slate-600'}`}>Tým</button>
        <button onClick={() => setActiveSubTab('vehicles')} className={`flex-1 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${activeSubTab === 'vehicles' ? 'bg-blue-600 text-white' : 'text-slate-600'}`}>AUTA</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
        {activeSubTab === 'workers' ? (
          workers.map(w => (
            <div key={w.id} onClick={() => handleOpenWorker(w)} className="bg-slate-800 p-4 rounded-2xl border border-slate-700 flex items-center gap-4 hover:border-blue-500/50 cursor-pointer group">
              <div className="w-12 h-12 bg-slate-900 rounded-full border border-slate-700 overflow-hidden flex items-center justify-center">
                {w.photo ? <img src={w.photo} className="w-full h-full object-cover" /> : <Icons.User />}
              </div>
              <div className="flex-1">
                <h4 className="font-bold text-slate-100 group-hover:text-blue-400">{w.name}</h4>
                <p className="text-[10px] text-slate-500 font-bold uppercase">{getRoleLabel(w.role)}</p>
              </div>
              <span className={`text-[9px] px-2 py-1 rounded font-black uppercase ${w.status === 'Available' ? 'bg-blue-900/30 text-blue-400' : 'bg-red-900/30 text-red-400'}`}>{getStatusLabel(w.status)}</span>
            </div>
          ))
        ) : (
          vehicles.map(v => (
            <div key={v.id} onClick={() => handleOpenVehicle(v)} className="bg-slate-800 p-4 rounded-2xl border border-slate-700 flex items-center gap-4 hover:border-blue-500/50 cursor-pointer group">
              <div className="w-12 h-12 bg-slate-900 rounded-full border border-slate-700 overflow-hidden flex items-center justify-center">
                {v.carImage ? <img src={v.carImage} className="w-full h-full object-cover" /> : <Icons.Truck />}
              </div>
              <div className="flex-1">
                <h4 className="font-bold text-slate-100 group-hover:text-blue-400">{v.plate}</h4>
                <p className="text-[10px] text-slate-500 font-bold uppercase">{v.model}</p>
              </div>
              <span className={`text-[9px] px-2 py-1 rounded font-black uppercase ${v.status === 'Ready' ? 'bg-blue-900/30 text-blue-400' : 'bg-red-900/30 text-red-400'}`}>{getStatusLabel(v.status)}</span>
            </div>
          ))
        )}
      </div>

      <button onClick={activeSubTab === 'workers' ? handleAddWorker : handleAddVehicle} className="w-full border-2 border-dashed border-slate-800 py-4 rounded-2xl text-slate-600 font-black text-[10px] uppercase hover:text-blue-400 hover:border-blue-500 transition-all flex items-center justify-center gap-2">
        <Icons.Plus /> Přidat {activeSubTab === 'workers' ? 'člena týmu' : 'vozidlo'}
      </button>

      {/* Worker Modal */}
      {showWorkerModal && selectedWorker && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-50 flex items-end sm:items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-md rounded-[32px] p-8 border border-slate-800 animate-slide-up max-h-[90vh] overflow-y-auto no-scrollbar">
            <h3 className="text-2xl font-black text-white mb-6 uppercase tracking-tighter">Profil pracovníka</h3>
            <div className="space-y-4">
              <div className="flex justify-center mb-4">
                <div onClick={() => workerPhotoRef.current?.click()} className="w-24 h-24 bg-slate-800 rounded-3xl border-2 border-slate-700 overflow-hidden cursor-pointer flex items-center justify-center">
                  {selectedWorker.photo ? <img src={selectedWorker.photo} className="w-full h-full object-cover" /> : <Icons.Camera />}
                </div>
                <input type="file" ref={workerPhotoRef} hidden onChange={e => handleImage(e, 'photo')} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-500 uppercase px-1">Jméno</label>
                <input value={selectedWorker.name} onChange={e => setSelectedWorker({...selectedWorker, name: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-white border-none" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase px-1">Telefon</label>
                  <input value={selectedWorker.phone} onChange={e => setSelectedWorker({...selectedWorker, phone: e.target.value})} className="w-full bg-slate-800 rounded-xl p-3 text-white border-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase px-1">Pozice</label>
                  <select value={selectedWorker.role} onChange={e => setSelectedWorker({...selectedWorker, role: e.target.value as any})} className="w-full bg-slate-800 rounded-xl p-3 text-white border-none appearance-none">
