        if (isClientIdValid) {
            // @ts-ignore
            window.google.accounts.id.initialize({
              client_id: GOOGLE_CLIENT_ID,
              callback: handleCredentialResponse,
              auto_select: false,
              ux_mode: 'popup', 
              cancel_on_tap_outside: true,
            });

            const btnElement = document.getElementById("googleBtn");
            if (btnElement) {
              // @ts-ignore
              window.google.accounts.id.renderButton(
                btnElement,
                { 
                  theme: "filled_blue", 
                  size: "large", 
                  width: 280, 
                  shape: "pill", 
                  text: "signin_with", 
                  locale: "cs" 
                }
              );
            }
        }
      } else {
        setTimeout(initGsi, 200);
      }
    };

    if (!user && apiKeySelected) {
      initGsi();
    }
  }, [user, apiKeySelected, handleCredentialResponse, isClientIdValid]);

  const handleManualLogin = () => {
    setUser({
      id: '1',
      name: 'Jan Novák (Demo)',
      email: 'admin@stehovak2.com',
      avatar: 'https://picsum.photos/seed/admin/200/200',
      role: 'admin',
      workerId: '1'
    });
  };

  const getTabLabel = (tab: AppTab) => {
    switch (tab) {
      case AppTab.DASHBOARD: return 'PŘEHLED';
      case AppTab.CALENDAR: return 'KALENDÁŘ';
      case AppTab.FLEET: return 'FLOTILA';
      case AppTab.AI_LAB: return 'AI LABORATOŘ';
      case AppTab.PROFILE: return 'PROFIL';
      default: return '';
    }
  };

  if (checkingApiKey) {
    return (
        <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center">
            <div className="w-8 h-8 border-4 border-blue-400 border-t-transparent rounded-full animate-spin"></div>
        </div>
    );
  }

  if (!apiKeySelected) {
    return (
      <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white text-center">
        <div className="w-28 h-28 bg-blue-600 rounded-[35px] mb-8 flex items-center justify-center shadow-[0_20px_50px_rgba(59,130,246,0.3)] text-white">
            <Icons.Sparkles />
        </div>
        <h1 className="text-3xl font-black mb-2">Vyžadován API Klíč</h1>
        <p className="text-slate-400 mb-8 max-w-sm">
            Pro generování obrázků s prémiovým modelem je nutné vybrat Váš vlastní API klíč z placeného Google Cloud projektu.
        </p>
        <button 
            onClick={handleSelectApiKey}
            className="bg-blue-600 text-white font-black py-4 px-8 rounded-2xl shadow-xl shadow-blue-600/20 transition-all active:scale-95 text-sm uppercase tracking-widest hover:bg-blue-500"
        >
            Vybrat API klíč
        </button>
          <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-blue-400 text-xs font-bold mt-6 hover:underline">
            Více o zpoplatnění &rarr;
          </a>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-white animate-fade-in relative overflow-hidden">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-blue-600/10 rounded-full blur-[120px] pointer-events-none" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-red-600/10 rounded-full blur-[120px] pointer-events-none" />

        <div className="w-28 h-28 bg-blue-600 rounded-[35px] mb-8 flex items-center justify-center shadow-[0_20px_50px_rgba(59,130,246,0.3)] text-white transform rotate-3 relative z-10">
          <div className="transform -rotate-3 scale-125"><Icons.Truck /></div>
        </div>

        <h1 className="text-4xl font-black mb-2 tracking-tighter relative z-10">Stěhovák <span className="text-red-500">2.0</span></h1>
        <p className="text-slate-400 mb-12 text-center font-medium max-w-[250px] relative z-10">
          Logistický systém pro moderní týmy.
        </p>

        <div className="space-y-4 w-full max-w-[280px] relative z-10 flex flex-col items-center">
          {!isOriginAuthorized && (
            <div className="w-full text-center p-5 bg-purple-500/10 border border-purple-500/20 rounded-3xl">
              <p className="text-purple-400 text-xs font-black uppercase tracking-widest">NEAUTORIZOVANÝ PŮVOD</p>
              <p className="text-slate-300 text-sm mt-3 font-bold">
                  Váš původ <code className="bg-slate-700/50 text-purple-300 px-1.5 py-0.5 rounded-md font-mono text-xs">{currentOrigin}</code> není rozpoznán.
              </p>
              <p className="text-slate-400 text-[11px] mt-2 leading-relaxed">
                  Přidejte tuto URL do "Autorizovaných JavaScript zdrojů" ve vaší Google Cloud Console a do pole <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">AUTHORIZED_ORIGINS</code> v <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">App.tsx</code>.
              </p>
            </div>
          )}

          {!isClientIdValid ? (
            <div className="w-full text-center p-5 bg-yellow-500/10 border border-yellow-500/20 rounded-3xl">
              <p className="text-yellow-400 text-xs font-black uppercase tracking-widest">AKCE VYŽADOVÁNA</p>
              <p className="text-slate-300 text-sm mt-3 font-bold">
                  Nastavte Google Client ID
              </p>
              <p className="text-slate-400 text-[11px] mt-2 leading-relaxed">
                  Pro aktivaci přihlášení vložte Váš klíč do souboru <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">App.tsx</code>. Klíč musí končit na <code className="bg-slate-700/50 text-yellow-300 px-1.5 py-0.5 rounded-md font-mono text-xs">.apps.googleusercontent.com</code>.
              </p>
              <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer" className="text-blue-400 text-xs font-bold mt-4 inline-block hover:underline">
                  Získat Client ID v Google Cloud Console &rarr;
              </a>
            </div>
          ) : (
            <div id="googleBtn" className="min-h-[44px]"></div>
          )}

          <button 
            onClick={handleManualLogin}
            className="text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-slate-300 transition-colors py-2"
          >
            Vstoupit v demo režimu
          </button>
        </div>

        {authError && (
          <div className="mt-8 px-4 py-3 bg-red-500/10 border border-red-500/20 rounded-2xl animate-slide-up relative z-10">
            <p className="text-red-500 text-[10px] font-black uppercase tracking-widest text-center">
              {authError}
            </p>
          </div>
        )}

        <div className="absolute bottom-12 text-center w-full">
           <p className="text-[10px] text-slate-700 font-black uppercase tracking-[0.4em]">Premium Logistics Core</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col w-full md:max-w-6xl mx-auto shadow-2xl overflow-hidden relative border-x border-slate-800">
      <header className="bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 p-5 sticky top-0 z-40 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-600/20">
            <Icons.Truck />
          </div>
          <div>
            <h1 className="text-lg font-black text-white leading-none">Stěhovák <span className="text-red-500">2.0</span></h1>
            <p className="text-[9px] text-red-500 font-black tracking-widest mt-0.5">{getTabLabel(activeTab)}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 rounded-2xl overflow-hidden border-2 border-slate-700 shadow-md">
            <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
          </div>
        </div>
        <div className="absolute bottom-0 left-0 w-full h-[2px] flex">
          <div className="h-full w-1/3 bg-blue-600"></div>
          <div className="h-full w-1/3 bg-slate-200"></div>
          <div className="h-full w-1/3 bg-red-600"></div>
        </div>
      </header>

      {authError && (
        <div className="p-4 bg-red-600/10 border-b border-red-500/20 text-center text-red-400 text-xs font-bold relative">
          <p className="pr-8">{authError}</p>
          <button onClick={() => setAuthError(null)} className="absolute top-1/2 right-4 -translate-y-1/2 text-red-400/50 hover:text-red-400 font-black text-xl">&times;</button>
        </div>
      )}

      <main className="flex-1 overflow-y-auto no-scrollbar p-5 pb-32">
        {activeTab === AppTab.DASHBOARD && <Dashboard tasks={tasks} workers={workers} vehicles={vehicles} user={user} />}
        {activeTab === AppTab.CALENDAR && <CalendarView tasks={tasks} setTasks={setTasks} workers={workers} vehicles={vehicles} user={user} />}
        {activeTab === AppTab.FLEET && <FleetView workers={workers} setWorkers={setWorkers} vehicles={vehicles} setVehicles={setVehicles} />}
        {activeTab === AppTab.AI_LAB && <AILab />}
        {activeTab === AppTab.PROFILE && <Profile user={user} onLogout={() => setUser(null)} transactions={transactions} setTransactions={setTransactions} />}
      </main>

      <nav className="bg-slate-900/95 backdrop-blur-2xl border-t border-slate-800 fixed bottom-0 left-0 right-0 w-full md:max-w-6xl mx-auto z-40 flex justify-around p-4 shadow-[0_-10px_40px_rgba(0,0,0,0.5)] rounded-t-[35px]">
        <NavButton active={activeTab === AppTab.DASHBOARD} onClick={() => setActiveTab(AppTab.DASHBOARD)} icon={<Icons.Home />} label="Domů" />
        <NavButton active={activeTab === AppTab.CALENDAR} onClick={() => setActiveTab(AppTab.CALENDAR)} icon={<Icons.Calendar />} label="Kalendář" />
        <NavButton active={activeTab === AppTab.FLEET} onClick={() => setActiveTab(AppTab.FLEET)} icon={<Icons.Truck />} label="Flotila" />
        <NavButton active={activeTab === AppTab.AI_LAB} onClick={() => setActiveTab(AppTab.AI_LAB)} icon={<Icons.Sparkles />} label="AI Lab" />
        <NavButton active={activeTab === AppTab.PROFILE} onClick={() => setActiveTab(AppTab.PROFILE)} icon={<Icons.User />} label="Profil" />
      </nav>
    </div>
  );
};

