      {label}
    </span>
    {active && <div className="absolute -bottom-1 w-1 h-1 bg-blue-600 rounded-full" />}
  </button>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { MoveTask, Worker, Vehicle } from '../types';
import { Icons } from '../constants';

interface DashboardProps {
  tasks: MoveTask[];
  workers: Worker[];
  vehicles: Vehicle[];
  user: {
    workerId?: string;
    role: 'admin' | 'user';
  };
}

const Dashboard: React.FC<DashboardProps> = ({ tasks, workers, vehicles, user }) => {
  const [selectedTask, setSelectedTask] = useState<MoveTask | null>(null);
  const [isDesktop, setIsDesktop] = useState(window.innerWidth >= 1024);

  useEffect(() => {
    const handleResize = () => setIsDesktop(window.innerWidth >= 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const weeklyStats = useMemo(() => {
    const now = new Date();
    const startOfWeek = new Date(now);
    const day = now.getDay();
    const diff = now.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    startOfWeek.setDate(diff);
    startOfWeek.setHours(0, 0, 0, 0);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23, 59, 59, 999);

    const weekTasks = tasks.filter(t => t.start >= startOfWeek && t.start <= endOfWeek);
    const completed = weekTasks.filter(t => t.status === 'Completed').length;
    return { total: weekTasks.length, completed };
  }, [tasks]);

  const monthlyStats = useMemo(() => {
    const now = new Date();
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    endOfMonth.setHours(23, 59, 59, 999);

    const monthTasks = tasks.filter(t => t.start >= startOfMonth && t.start <= endOfMonth);
    const completed = monthTasks.filter(t => t.status === 'Completed').length;
    return { total: monthTasks.length, completed };
  }, [tasks]);

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  const isTomorrow = (date: Date) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    return date.getDate() === tomorrow.getDate() &&
      date.getMonth() === tomorrow.getMonth() &&
      date.getFullYear() === tomorrow.getFullYear();
  };

  // Logic for "My assigned tasks" specifically for the top start cards
  const myAssignedTasks = user.workerId 
    ? tasks.filter(t => t.assignedWorkers.includes(user.workerId!))
    : [];

  const myTodayStartTask = [...myAssignedTasks]
    .filter(t => isToday(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const myTomorrowStartTask = [...myAssignedTasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  // Logic for lists (Admins see all, users see assigned)
  const myTasksForList = user.role === 'admin' 
    ? tasks 
    : tasks.filter(t => t.assignedWorkers.includes(user.workerId || ''));

  const todayTasks = myTasksForList.filter(t => isToday(t.start));
  const tomorrowTasks = myTasksForList.filter(t => isTomorrow(t.start));

  // Find the company's first task for tomorrow (for the notification section)
  const firstTaskTomorrowGlobal = [...tasks]
    .filter(t => isTomorrow(t.start))
    .sort((a, b) => a.start.getTime() - b.start.getTime())[0];

  const handleOpenMaps = (address?: string) => {
    if (!address) return;
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  const sendNotification = (type: 'whatsapp' | 'sms', task: MoveTask) => {
    const timeStr = `${task.start.getHours()}:${task.start.getMinutes().toString().padStart(2, '0')}`;
    const message = `Stěhovák 2.0: Připomínka zítřejšího startu. První zakázka '${task.title}' začíná v ${timeStr}. Buďte připraveni!`;
    const encodedMsg = encodeURIComponent(message);

    if (type === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodedMsg}`, '_blank');
    } else {
      window.location.href = `sms:?body=${encodedMsg}`;
    }
  };

  const formatTime = (date: Date) => {
    return `${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`;
  };

  // Fix: Explicitly define TaskCardProps to resolve TypeScript error with the 'key' prop in lists.
  interface TaskCardProps {
    task: MoveTask;
  }

  // FIX: Explicitly type TaskCard as a React.FC to ensure TypeScript recognizes it as a component that can accept a 'key' prop.
  const TaskCard: React.FC<TaskCardProps> = ({ task }) => (
    <div 
      onClick={() => setSelectedTask(task)}
      className="bg-slate-800 p-5 rounded-[2.5rem] shadow-sm border border-slate-700 flex items-center gap-5 hover:bg-slate-700 hover:border-blue-500/30 transition-all cursor-pointer active:scale-[0.98] group"
    >
      <div className="flex flex-col items-center justify-center bg-slate-900 group-hover:bg-blue-600 group-hover:text-white rounded-[2rem] p-4 min-w-[75px] transition-colors duration-300 text-slate-400">
        <span className="font-black text-xl leading-none group-hover:text-white transition-colors">
          {task.start.getHours()}
        </span>
        <span className="text-[10px] font-black opacity-40 uppercase mt-1">HOD</span>
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="font-black text-slate-100 text-base leading-tight group-hover:text-blue-400 transition-colors">{task.title}</h3>
        <p className="text-xs text-slate-400 font-bold mt-1 uppercase tracking-tight">{task.customer}</p>
        <div className="flex items-center gap-2 mt-2">
          <div className="flex -space-x-2">
            {task.assignedWorkers.slice(0, 3).map((_, i) => (
              <div key={i} className="w-5 h-5 rounded-full bg-slate-700 border-2 border-slate-800 flex items-center justify-center text-[8px] font-black text-blue-400"><Icons.User /></div>
            ))}
          </div>
          <span className="text-[10px] text-slate-500 font-bold truncate">
            {task.from}
          </span>
        </div>
      </div>

      <div className={`w-3 h-3 rounded-full shadow-[0_0_10px_rgba(0,0,0,0.5)] ${
        task.status === 'Confirmed' ? 'bg-blue-500' : 
        task.status === 'In Progress' ? 'bg-red-500 animate-pulse' : 'bg-slate-600'
      }`} />
    </div>
  );

  return (
    <div className="space-y-10">
      {/* Personalized Start Times */}
      <div className="grid grid-cols-2 gap-4">
        <StartCard 
          label="Tvůj dnešní start" 
          time={myTodayStartTask ? formatTime(myTodayStartTask.start) : '--:--'} 
          subtitle={myTodayStartTask?.title || 'Dnes nemáš zakázku'}
          color="red" 
        />
        <StartCard 
          label="Tvůj zítřejší start" 
          time={myTomorrowStartTask ? formatTime(myTomorrowStartTask.start) : '--:--'} 
          subtitle={myTomorrowStartTask?.title || 'Zítra nemáš zakázku'}
          color="blue" 
        />
      </div>

      {/* Desktop Statistics Section */}
      {isDesktop && (
        <section className="grid grid-cols-2 gap-4 animate-fade-in">
          <StatCard 
            title="Tento týden"
            completed={weeklyStats.completed}
            total={weeklyStats.total}
            color="blue"
          />
          <StatCard 
            title="Tento měsíc"
            completed={monthlyStats.completed}
            total={monthlyStats.total}
            color="red"
          />
        </section>
      )}

      {/* Tomorrow Morning Reminder Section (Admin/Global focus) */}
      {user.role === 'admin' && firstTaskTomorrowGlobal && (
        <section className="bg-blue-600/10 border border-blue-500/20 rounded-[3rem] p-6 animate-fade-in relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
            <Icons.Sparkles />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4">
               <span className="w-2 h-2 bg-blue-400 rounded-full animate-pulse shadow-[0_0_8px_#60a5fa]" />
               <h2 className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Zítřejší ranní start (Firma)</h2>
            </div>
            <div className="flex items-end justify-between">
               <div>
                  <p className="text-2xl font-black text-white tracking-tighter">{formatTime(firstTaskTomorrowGlobal.start)}</p>
                  <p className="text-xs font-bold text-slate-400 uppercase truncate max-w-[180px]">{firstTaskTomorrowGlobal.title}</p>
               </div>
               <div className="flex gap-2">
                  <button 
                    onClick={() => sendNotification('sms', firstTaskTomorrowGlobal)}
                    className="p-4 bg-slate-800 text-white rounded-2xl border border-slate-700 hover:bg-slate-700 transition-all shadow-lg active:scale-90"
                  >
                    <Icons.Message />
                  </button>
                  <button 
                    onClick={() => sendNotification('whatsapp', firstTaskTomorrowGlobal)}
                    className="p-4 bg-green-600 text-white rounded-2xl border border-green-500 hover:bg-green-500 transition-all shadow-lg shadow-green-600/20 active:scale-90"
                  >
                    <Icons.WhatsApp />
                  </button>
               </div>
            </div>
          </div>
        </section>
      )}

      {/* Main Task Lists Container - Responsive Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <section className="space-y-5">
            <div className="flex items-center justify-between px-2">
            <h2 className="text-xl font-black text-slate-100 tracking-tighter uppercase">Dnešní <span className="text-red-500">Mise</span></h2>
            <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_#ef4444]" />
            </div>
            <div className="space-y-4">
            {todayTasks.length > 0 ? todayTasks.map(task => (
                <TaskCard key={task.id} task={task} />
            )) : (
                <div className="bg-slate-800/50 rounded-[2.5rem] p-10 text-center border-2 border-dashed border-slate-700">
                <p className="text-xs font-black text-slate-600 uppercase tracking-widest">Žádné dnešní úkoly</p>
                </div>
            )}
            </div>
        </section>

        <section className="space-y-5">
            <h2 className="text-xl font-black text-slate-100 tracking-tighter px-2 uppercase">Plány <span className="text-blue-500">Zítra</span></h2>
            <div className="space-y-4">
            {tomorrowTasks.length > 0 ? tomorrowTasks.map(task => (
                <TaskCard key={task.id} task={task} />
            )) : (
                <div className="bg-slate-800/50 rounded-[2.5rem] p-10 text-center border-2 border-dashed border-slate-700">
                <p className="text-xs font-black text-slate-600 uppercase tracking-widest">Zítra volno</p>
                </div>
            )}
            </div>
        </section>
      </div>

      {/* Task Detail Modal */}
      {selectedTask && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-50 flex items-end sm:items-center justify-center p-4" onClick={() => setSelectedTask(null)}>
          <div 
            className="bg-slate-900 w-full max-w-md rounded-[3rem] p-8 shadow-2xl animate-slide-up border border-slate-800"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex justify-between items-start mb-8">
              <div>
                <span className="text-[10px] font-black uppercase tracking-[0.2em] px-3 py-1 bg-red-600 text-white rounded-lg mb-3 inline-block">
                  {selectedTask.status}
                </span>
                <h3 className="text-3xl font-black text-white tracking-tighter">{selectedTask.title}</h3>
              </div>
              <button onClick={() => setSelectedTask(null)} className="bg-slate-800 p-3 rounded-2xl hover:bg-slate-700 transition-colors text-slate-400">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>

            <div className="space-y-8">
