import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

// Striktní systémová instrukce pro vynucení češtiny
const SYSTEM_INSTRUCTION = "Jsi expertní logistický asistent pro českou aplikaci 'Stěhovák 2.0'. TVŮJ JAZYK JE ČEŠTINA. \n\n1. Veškerá komunikace musí probíhat výhradně v češtině (Czech language only).\n2. Odpovídej věcně, profesionálně a s ohledem na české reálie.\n3. Používej metrický systém (metry, kilogramy) a českou měnu (Kč).\n4. Data formátuj jako DD.MM.RRRR.\n5. Pokud uživatel zadá dotaz v jiném jazyce, přelož si ho a odpověz česky.";

export const geminiService = {
  /**
   * Thinking mode for complex queries (Gemini 3 Pro)
   */
  async thinkComplex(prompt: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });
    return response.text || "Nebyla vygenerována žádná odpověď.";
  },

  /**
   * Analyze images (Gemini 3 Pro)
   */
  async analyzeImage(imagePrompt: string, base64Image: string): Promise<string> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: imagePrompt } // Prompt je v AILab.tsx defaultně nastaven na češtinu
        ]
      },
      config: {
        systemInstruction: SYSTEM_INSTRUCTION
      }
    });
    return response.text || "Nepodařilo se analyzovat obrázek.";
  },

  /**
   * Generate images (Gemini 3 Pro Image)
   */
  async generateImage(prompt: string, size: '1K' | '2K' | '4K', aspectRatio: string): Promise<string | null> {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      // Vynucení českého kontextu přímo v promptu pro obrázek
      contents: { parts: [{ text: `Vysoce kvalitní, fotorealistický obrázek, české prostředí: ${prompt}` }] },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
          imageSize: size
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  },

  /**
   * Maps Grounding (Gemini 2.5 Flash)
   */
  async getMapsInfo(query: string, lat?: number, lng?: number): Promise<{ text: string, links: any[] }> {
    const ai = getAI();
    const config: any = {
      tools: [{ googleMaps: {} }],
      systemInstruction: SYSTEM_INSTRUCTION
    };

    if (lat !== undefined && lng !== undefined) {
      config.toolConfig = {
        retrievalConfig: {
          latLng: { latitude: lat, longitude: lng }
        }
      };
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Najdi v okolí (odpověz česky): ${query}`,
      config
    });

    return {
      text: response.text || "",
      links: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
    };
  }
};

import React, { useState, useRef } from 'react';
import { geminiService } from '../services/geminiService';
import { Icons } from '../constants';

const AILab: React.FC = () => {
  const [activeTool, setActiveTool] = useState<'thinking' | 'vision' | 'generation' | 'maps' | null>(null);
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [result, setResult] = useState<any>(null);
  const [input, setInput] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [aspectRatio, setAspectRatio] = useState('1:1');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const aspectRatios = ["1:1", "2:3", "3:2", "3:4", "4:3", "9:16", "16:9", "21:9"];

  // Speech Recognition setup for Czech language
  const startListening = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Rozpoznávání řeči není v tomto prohlížeči podporováno.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'cs-CZ'; // Explicitně nastaveno na češtinu
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => (prev ? `${prev} ${transcript}` : transcript));
    };

    recognition.start();
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSelectedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const getCurrentLocation = (): Promise<{lat: number, lng: number} | null> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) return resolve(null);
      navigator.geolocation.getCurrentPosition(
        (pos) => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        () => resolve(null),
        { timeout: 5000 }
      );
    });
  };

  const runTool = async () => {
    if (!input && !['vision', 'generation'].includes(activeTool || '')) return;
    setLoading(true);
    setResult(null);
    try {
      if (activeTool === 'thinking') {
        const res = await geminiService.thinkComplex(input);
        setResult(res);
      } else if (activeTool === 'vision' && selectedImage) {
        const base64 = selectedImage.split(',')[1];
        // Defaultní prompt je v češtině
        const res = await geminiService.analyzeImage(input || "Co vidíš na této fotce v kontextu stěhování? Popiš to česky.", base64);
        setResult(res);
      } else if (activeTool === 'generation') {
        const res = await geminiService.generateImage(input, '1K', aspectRatio);
        setResult(res);
      } else if (activeTool === 'maps') {
        const loc = await getCurrentLocation();
        const res = await geminiService.getMapsInfo(input, loc?.lat, loc?.lng);
        setResult(res);
      }
    } catch (e: any) {
        console.error(e);
        if (e.message?.includes("API key not valid")) {
             setResult("Váš API klíč není platný. Prosím, obnovte stránku a vyberte platný klíč z placeného projektu.");
        } else {
             setResult("Omlouváme se, AI služba je momentálně přetížena nebo došlo k chybě.");
        }
    }
    setLoading(false);
  };

  const reset = () => { setActiveTool(null); setResult(null); setInput(''); setSelectedImage(null); };

  if (!activeTool) {
    return (
      <div className="space-y-6">
        <h2 className="text-xl font-black text-white tracking-tighter uppercase">Gemini <span className="text-blue-400">AI</span> Laboratoř</h2>
        <div className="grid grid-cols-2 gap-4">
          <ToolCard title="Plánovač" desc="Strategické myšlení." icon={<Icons.Sparkles />} onClick={() => setActiveTool('thinking')} />
          <ToolCard title="Vision" desc="Analýza objemu z foto." icon={<Icons.Camera />} onClick={() => setActiveTool('vision')} />
          <ToolCard title="Design" desc="Tvorba vizuálů." icon={<Icons.Plus />} onClick={() => setActiveTool('generation')} />
          <ToolCard title="Průzkum" desc="Mapová data." icon={<Icons.Map />} onClick={() => setActiveTool('maps')} />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center gap-3">
        <button onClick={reset} className="p-2 bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <h2 className="text-lg font-black text-white uppercase tracking-tight">
          {activeTool === 'thinking' ? 'Strategický Plánovač' : 
           activeTool === 'vision' ? 'Vizuální Odhad' : 
           activeTool === 'generation' ? 'AI Design' : 'Průzkum Trasy'}
        </h2>
      </div>

      <div className="bg-slate-800 rounded-[32px] p-6 shadow-xl border border-slate-700 space-y-4">
        {activeTool === 'vision' && (
          <div onClick={() => fileInputRef.current?.click()} className="aspect-video bg-slate-900 rounded-2xl border-2 border-dashed border-slate-700 flex flex-col items-center justify-center cursor-pointer overflow-hidden mb-4 group hover:border-blue-500 transition-all">
            {selectedImage ? (
              <img src={selectedImage} className="w-full h-full object-cover" />
            ) : (
              <div className="text-slate-600 text-center p-4">
                <Icons.Camera />
                <p className="text-[10px] font-black mt-2 uppercase">Klikni pro nahrání nebo vyfocení</p>
              </div>
            )}
            <input 
              type="file" 
              ref={fileInputRef} 
              hidden 
              accept="image/*" 
              capture="environment"
              onChange={handleImageUpload} 
            />
          </div>
        )}

        {activeTool === 'generation' && (
          <div className="space-y-3 mb-4">
            <label className="text-[10px] font-black text-slate-500 uppercase px-1 tracking-widest flex items-center gap-2">
              <Icons.AspectRatio />
              Poměr stran
            </label>
            <div className="flex flex-wrap gap-2">
              {aspectRatios.map(ratio => (
                <button
                  key={ratio}
                  onClick={() => setAspectRatio(ratio)}
                  className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border ${aspectRatio === ratio ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-slate-900 border-slate-700 text-slate-400 hover:bg-slate-700'}`}
                >
                  {ratio}
                </button>
              ))}
            </div>
          </div>
        )}

        <div className="relative">
          <textarea 
            placeholder={
              activeTool === 'thinking' ? "Zadejte logistický oříšek (např. jak naplánovat trasu Praha-Brno)..." : 
              activeTool === 'vision' ? "Zeptejte se na fotku (např. Kolik krabic bude potřeba?)..." : 
              activeTool === 'maps' ? "Hledejte místa (např. restaurace v okolí)..." :
              "Popište co má AI vytvořit (např. návrh polepu auta)..."
            }
            value={input}
            onChange={e => setInput(e.target.value)}
            className="w-full bg-slate-900 border-none rounded-2xl p-5 pr-14 min-h-[140px] focus:ring-2 focus:ring-blue-500 outline-none text-sm text-slate-100 placeholder-slate-600"
          />
          <button 
            onClick={startListening}
            className={`absolute right-4 top-4 p-3 rounded-xl transition-all ${isListening ? 'bg-red-600 text-white animate-pulse shadow-[0_0_15px_#dc2626]' : 'bg-slate-800 text-slate-500 hover:text-white'}`}
            title="Diktovat (Čeština)"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3Z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><line x1="12" x2="12" y1="19" y2="22"/>
            </svg>
          </button>
        </div>

        <button 
          onClick={runTool}
          disabled={loading || (!input && !['vision', 'generation'].includes(activeTool || ''))}
          className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 flex items-center justify-center gap-3 disabled:opacity-30 transition-all"
        >
          {loading ? (
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
          ) : (
            <><Icons.Sparkles /> {activeTool === 'maps' ? 'Vyhledat v mapách' : 'Spustit AI'}</>
          )}
        </button>
      </div>

      {result && (
        <div className="bg-blue-600/10 border border-blue-500/20 p-6 rounded-[32px] animate-fade-in overflow-hidden">
          {isListening && (
            <div className="flex items-center gap-2 mb-4">
              <span className="flex h-2 w-2 rounded-full bg-red-600 animate-ping"></span>
              <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">Naslouchám...</span>
            </div>
          )}
          {typeof result === 'string' && result.startsWith('data:') ? (
            <img src={result} className="w-full rounded-xl shadow-2xl" />
          ) : typeof result === 'object' && result.text ? (
             <div className="space-y-4">
               <p className="text-blue-100 text-sm leading-relaxed whitespace-pre-wrap">{result.text}</p>
               {result.links?.map((l:any, i:number) => (
                 <a key={i} href={l.maps?.uri} target="_blank" className="flex items-center justify-between bg-slate-900 p-3 rounded-xl text-[10px] font-black text-blue-400 hover:bg-slate-800 transition-colors">
                   {l.maps?.title || "ZOBRAZIT MÍSTO"} <Icons.ChevronRight />
                 </a>
               ))}
             </div>
          ) : (
            <p className="text-blue-100 text-sm leading-relaxed whitespace-pre-wrap">{result}</p>
          )}
        </div>
      )}
    </div>
  );
};

